/* 令和6年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r06.committeeSessions.push(...[{"id":"r06-20240925-7","meetingId":"r06-cm09","date":"2024年9月25日","dateIso":"2024-09-25","committee":"厚生委員会","time":"午前１０時００分～午後 ０時１７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件整理しています。","topics":[{"id":"topic-01","title":"令和５年度指定管理者の管理に対するモニタリング・評価の結果","agenda":"令和５年度指定管理者の管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"ひがし委員","kind":"確認","question":"私からは、障害者支援課の所管施設分のところの２ページでまず１点、確認となります。高次脳機能障害の利用が増えた理由をどう分析しているのかというところと、利用促進に向けた取組、また今後の課題について説明を求めました。","respondent":"松山障害者支援課長","answer":"自立訓練につきましては、やはり委員おっしゃられるとおり、病院からの高次脳機能障害の方がかなり多数を占めております。例えば特別支援学校への周知等々、それを周知するというようなことを考えて、心身障害者福祉会館としての姿勢です。","id":"exchange-001"},{"speaker":"ひがし委員","kind":"質問・要望","question":"次に、２５ページからの品川区立障害児者総合支援施設ぐるっぽの件から幾つか質問させてください。一くくりになっているのですけれども、居宅介護、重度訪問介護、同行援護と行動支援とあると思うのですけれども、内訳について説明を求めました。","respondent":"松山障害者支援課長","answer":"１名の方なので非常にちょっとセンシティブな内容になっておりますので、それについては差し控えします。居宅介護が年間で６７２件、それから重度訪問介護が１１９件、同行援護が８件、行動援護が０件、それから移動支援が６４９件です。","id":"exchange-002"},{"speaker":"ひがし委員","kind":"質問","question":"子ども発達相談室だと１,０００件減っていて、その下の相談件数、これは一般相談ですか。１日に複数件の相談ができる体制を構築し、その件についてどのように分析をしているのかというところを聞かせてほしいと求めました。","respondent":"松山障害者支援課長","answer":"行動援護が０件ということですけれども、計画では確かに委員おっしゃられるとおり、見込みで８６時間という計画を記載させていただきました。","id":"exchange-003"},{"speaker":"ひがし委員","kind":"確認","question":"１点だけ。今言っていた統計上、カウントの仕方が違うというところをもう少し詳しく教えてほしいと求めました。","respondent":"松山障害者支援課長","answer":"子ども発達相談室の相談件数のカウントの仕方ですが、以前の指定管理者は、電話を１件取るたびに１カウント。それは利用者ではなくて関係機関からも１カウントしていた分、現在の法人と区が協議して、実際の相談件数に見直したということになります。","id":"exchange-004"},{"speaker":"ひがし委員","kind":"意見","question":"子ども発達相談室以外の一般相談のところの相談件数が載っているのかというところをご答弁いただけなかったと思うので、改めて聞かせてください。この減っている理由というのも、その認識が合っているかどうかも併せて聞かせてほしいと求めました。","respondent":"松山障害者支援課長","answer":"失礼いたしました。同じようにやはり電話を１本取るたびに１件と数えていたところを、実際の相談件数でカウントしたということになります。","id":"exchange-005"},{"speaker":"ひがし委員","kind":"意見","question":"理解をいたしました。最後に、現在の初回の面接に向けて待ち時間、期間というのはどのぐらいあるのかを最後にお聞かせほしいと求めました。","respondent":"松山障害者支援課長","answer":"子ども発達相談室の初回待ちというのは、今現在は解消しております。","id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問","question":"そこを区がどう支えて応えていくのかというのが、大事になると思っています。障害者のほうから伺いたいのですけれども、１ページの心身障害者福祉会館なのですけれども、理由を教えていただけたらと思います。","respondent":"松山障害者支援課長","answer":"指定管理事業の中身ですけれども、人件費が主なものです。","id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問","question":"この１.５倍、令和３年度からすると２倍に上がっているという、この指定管理料の上がった理由はなぜなのかということを伺いたいと思います。公表はどのようにされているのか伺いたいのですけれども、今、取られているものがありましたらお聞かせいただけたらと思います。","respondent":"松山障害者支援課長","answer":"例えば大体２億円ぐらいで、国が９００万円ぐらい、東京都のほうが２,８００万円程度ということになります。それから、区としては指定管理３年目にどの施設も実施するということになっておりまして、評価というのは高いものとなっております。","id":"exchange-008"},{"speaker":"鈴木委員","kind":"質問","question":"放課後等デイサービスも３７.１％ということで、なぜこれほど少ない状況になっているのか、そこはどう捉えられているのか伺いたいと思います。少ないままという状況になっているのですが、この点についてはどう捉えられているのか、その点についても伺いたいと思います。","respondent":"松山障害者支援課長","answer":"次に、就労継続支援Ｂ型についてです。就労継続支援Ｂ型については企業に就職をしたいという利用者が多くあり、どこの施設も苦戦しているような状況にあります。","id":"exchange-009"},{"speaker":"鈴木委員","kind":"質問・要望","question":"区の地域生活支援拠点ということで、緊急時の受入れ対応が求められていると思いますが、どの程度の緊急時の対応を実施できているのか。２４時間の電話対応というのを以前はされていたと思うのですが、現在はどうなっているのかについても伺いたいと思います。","respondent":"松山障害者支援課長","answer":"ほかに支援できる方がいないといったときに対応しています。２４時間というのは、連絡が入れば法人のほうにも連絡がつくようになっていますので、法人のほうで対応をしています。","id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問","question":"最後のほうを伺いたいと思うのですけれども、介護ではまず２ページなのですけれども、今幾らぐらいになっているのか。それなので、そういうところは少し見直していくことも必要なのではないかと思うのですけれども、その点を１点伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"今年度から居住支援手当のほうを支給させていただいて、まだちょっと今手続きのところでちょうど受付を開始したところということもありますので。今ちょっと要項のほうを整えておりまして、もう間もなく受付を開始するという次第になっておりますので。","id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問・要望","question":"いやもう大本は国なのですけれども、またこれからもさらに支援できるものがあれば、ぜひしてほしいと求めました。ここの１４ページのところで、これについては区としてはどういう対応がされているのか、その点も伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"区としましては令和４年度、定員に対するサポート対策支援金というのを事業者のほうには支援金として出していますので。今までは国の支援金、他区の動向も見ながら、東京都のほうは若干食費とかそういった部分の支援金を出すみたいな動きもありますので。","id":"exchange-012"},{"speaker":"筒井委員","kind":"質問","question":"幾つかお聞きしたいと思いますけれども、現在どの程度そのＩＣＴ機器を導入されているのか、どのぐらいの割合で進んでいるのかをお聞きしたいと思います。","respondent":"菅野高齢者福祉課長","answer":"その事業者といろいろ相談をしながら、必要な見守り機器というか、ＩＣＴ機器の導入を進めさせていただいているところです。今年度、平塚橋特別養護老人ホームのほうで進めさせていただいているのですけれども、支援をさせていただいているところです。","id":"exchange-013"},{"speaker":"筒井委員","kind":"質問","question":"７２ページだとか４４ページとかに、大体外国人の職員の方というのはおおむねどのぐらい採用しているものなのでしょうか。その現状が分かればお知らせください。","respondent":"菅野高齢者福祉課長","answer":"この７２ページのところで、三徳会は積極的に令和４年度以降外国人の採用を行いまして、記載されているのかなというところです。区として把握しているのは今２０名少々というところで、宿舎の確保とか、そういったところで支援をさせていただいているのを把握しております。","id":"exchange-014"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"年度途中の採用活動により２名を正規雇用とし、これは２３ページのところで人件費を大幅に削減したとなると、お教えほしいと求めました。","respondent":"菅野高齢者福祉課長","answer":"令和５年度が８,４４７万円ということで、人件費は５００万円ほど増えているけれどもこういう記載があるということで、その辺りは人件費の確保に苦慮しているのではないかと私どもとしては推測しております。","id":"exchange-015"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"前提の問題としてお伺いしたいのが、人材派遣の場合というのは外注費になって、人件費ではない気がするのです。その辺はどのように基準が決まっているのか、お教えほしいと求めました。","respondent":"菅野高齢者福祉課長","answer":"派遣職員とか、このモニタリングシートにおいては、そういうのも全部ひっくるめて人件費のほうに入れていただくようにお願いさせていただいています。","id":"exchange-016"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"一応確認ですけれども、あと、これはどこまで人件費に。その辺の線引きをお教えほしいと求めました。","respondent":"菅野高齢者福祉課長","answer":"１００％そうだと言い切れないところもありますが、派遣職員とか紹介料についても人件費の中に入れていただくように、今後も法人のほうにはお話する予定です。","id":"exchange-017"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"現状のように一般の会計種別とは別にこのようにしていただいたほうが分かりやすいと思うので、今後もよろしくお願いいたします。別なのですけれども、少々要望にも近いかもしれないですけれども、モニタリングで毎回事業所から提出というのはされていらっしゃるのか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"離職率につきましては法人単位で出させていただいているので、ちょっと施設ごとにというのは難しい部分もあります。離職率については５年に一回、そこでは法人全体、そこで検証はしていきたいと考えています。","id":"exchange-018"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ちょっと近い話なのですけれども、品川の福祉専門学校の卒業生の方がどれだけ入職されて、もしくはその中で離職をされたみたいな、そういったデータというのは取ってあったり、もしくはそういった掲載を入れるというのは可能なのかどうか、その辺もお伺いしたいと思います。","respondent":"菅野高齢者福祉課長","answer":"介護福祉専門学校からは約８００人を超える学生が卒業しており、多くの卒業生がかなりの割合で区内法人に勤めていただいているのが実情です。","id":"exchange-019"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"もうそれで３年働いただけでもありがたいのですけれども、ぜひその辺は、区でもしっかり把握してほしいと求めました。これはちょっと要望ということで、ひとまず、以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"鈴木委員","kind":"質問・要望","question":"介護のほうの１７ページなのですけれども、それについてはどう捉えられているのか、ひとつ伺いたいと思います。これは基本週２回ということになっていると思うのですけれども、ほかにも勧めていただきたいと思っているのですが、その点も伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"４点ご質問いただきましたので、順番にご説明していきたいと思います。全体的な対応方針としても書かれているのは、通所介護との、もちろん利用者の利用料も高くなるという部分もあります。","id":"exchange-021"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"報告みたいなものがあったかどうか、ちょっとご説明いただきたいのですけれども、いかがでしょうか。何かありましたか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"その辺りのところは、お話があると事業者のほうに工夫をしていただくなど、近隣の理解も得られるようにということでお話をさせていただいた事例があります。","id":"exchange-022"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"それをするのも、そこから３０メートル歩けないみたいな方もいるので、ドア・トゥー・ドアとなっているという事例もあると思うのです。なので、そういう事情があるというのもぜひ所管として把握しておいてほしいと求めましたので、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"鈴木委員","kind":"質問","question":"健康センターのところで１点伺いたいのですけれども、指定管理料が令和４年度から令和５年度に少し増えている理由を教えていただけたら。令和４年度で収支とかはそれほど関係性はないのかもしれないですけれども、その結果、この理由を説明を求めました。","respondent":"若生健康課長","answer":"指定管理料のほうは令和４年度についてはかなり回復するだろうと見込んでいたところ、当初その収入を見込んでいた関係で指定管理料を低く抑えたのですが、約１.５億円弱ぐらいの指定管理料になっているというのが現状です。","id":"exchange-024"},{"speaker":"鈴木委員","kind":"確認","question":"そうすると、令和５年度が２,０００万円を超えての黒字になって、令和６年度というのも同じような指定管理料になっているのか。その確認だけお願いします。","respondent":"若生健康課長","answer":"指定管理料、令和６年度につきましても、これは指定管理の更新があった関係で若干指定管理料が上がっているところは、人件費等の増加に伴ってあるのですけれども、指定管理料につきましてはほぼ同水準ぐらいに推移しているところであります。","id":"exchange-025"},{"speaker":"鈴木委員","kind":"意見","question":"分かりました。これからどういう状況になっていくのかというのを注視したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"なぜなら、その成果がやはり出るというのが、多分令和５年はまだ改善途中だったのかな。令和６年は大手を振って変わりましたと言えるようになってほしいと思っていて、そうなりますと言っていただけるのかどうか、そこだけ聞きますとの意見を述べました。","respondent":"寺嶋福祉部長","answer":"経営改善を含めて鋭意取り組んでいるというところは情報も入ってきております。そうなるように鋭意取り組んでいることと、区もしっかり支援していることは間違いございませんので、ぜひ来年に期待していただきたいと考えています。","id":"exchange-027"}]},{"id":"topic-02","title":"令和７年度分品川区立高齢者住宅（単身用）補欠登録者の募集","agenda":"令和７年度分品川区立高齢者住宅（単身用）補欠登録者の募集","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"実績を少し伺いたいのですけれども、令和４年度の募集で何人が応募して、令和５年度で何人入れたのか伺います。それから、去年の令和５年度の応募者が何人かも説明を求めました。","respondent":"樫村高齢者地域支援課長","answer":"令和４年度の実績ですが、６５名の方に登録いただきまして、入居された方が２２名いらっしゃいます。それから、昨年度につきましては、６２名の方に申込みをいただいているところです。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/814344?Template=document&Id=6829#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":43540,"voices":93}},{"id":"r06-20240925-8","meetingId":"r06-cm09","date":"2024年9月25日","dateIso":"2024-09-25","committee":"建設委員会","time":"午前１０時００分～午後 ０時０４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件整理しています。","topics":[{"id":"topic-01","title":"令和６年１１月都営住宅入居者募集","agenda":"令和６年１１月都営住宅入居者募集","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"いつも聞いておりますが、これまでの応募倍率と実績を伺いたいのと、あと、この間入居された人数も伺いたいと思います。併せて伺いたいと思うのですけれども、消印有効でも有効になるようにしていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"川原住宅課長","answer":"申込みの初日に列をなしてお待ちいただいている、それがやはり郵送ではなくて、そういった詳しいご説明の期間というのを一定度設けしています。検討していただいて、お出しいただくという形で、区としても同様な形を取らせていただいているところです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"単身は特に５５倍ということで倍率が高くなっているということですので、東京都に増設を求めてほしいと求めましたけれども、いかがでしょうか。区営住宅も同様に、ぜひ、やはりニーズが高いと思いますので、増設をしてほしいと求めましたけれども、いかがか尋ねました。","respondent":"川原住宅課長","answer":"空き家は、空き家対策というところと居住支援というところも含めて、民間住宅の支援というところも含めて実施をしていきたいと考えていますので。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"空き家の問題は確かにありますので、民間の活用もよいのですけれども、やはり公営住宅の役割、特に福祉的な役割を発揮していただきたいと。そのためには増設をしていっていただきたいということで求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"質問者もいつも聞いていると述べているほど毎回聞いていると思うので、あらかじめ資料に載せていただきたいと思うのですけども、いかがでしょうか。この委員会資料に載せていただいて、中身の議論を進めたほうがよいのではないかなと思うのですけども、いかがか尋ねました。","respondent":"川原住宅課長","answer":"倍率の記載についてご意見をいただきまして、ありがとうあります。各区の住宅担当課長会等もありますので、他区の募集の内容の記載方法について等も併せて情報収集と研究をしてまいりたいと思います。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"とありましたけど、資料を載せることで実質的な中身の議論にすぐ入れると思いますので、ぜひ記載を改めて求めておきたいと思います。都営住宅の増設を東京都に求めるのではなくて、造るのではなくて民間の活用とする理由は何か、伺いたいと思います。","respondent":"川原住宅課長","answer":"区としては、障害者ホームであるなどの多大な土地を必要としているところで、庁内全体での協議というところも非常に必要となってくると思います。賃貸人、オーナーの方の支援にもつながる、大きな意味での居住支援という形になるかとは考えてあります。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"いわゆる公営住宅を造るのは、そもそも造るという考えがないのか、庁内での協議が難しいというところがどういう意味合いなのか伺いたいと思います。区営住宅と都営住宅にならう部屋の大きさの家賃というのは、品川区は把握されていらっしゃるのか伺いたいと思います。","respondent":"川原住宅課長","answer":"そして、次の質問のまず１点目、庁内の協議が難しいであるとか、優先順位が下であるといったような考えは全くございません。現時点では考えがないというところと、区としての方向性と、そういった形で実施をしていきたいと考えております。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"とどのつまりは東京都と国がそういう方針だから、もうそういう方針なのですと、そういうことなのですか。これはいただけないなと思うのですけども、最後にいかがか尋ねました。","respondent":"川原住宅課長","answer":"過去の居住支援協議会の参考の資料の中で、答弁ができない形で申し訳ございませんが、調査した経緯はあります。住宅施策については総合的に検討をしていく必要があると考えていますので、民間住宅も含めて、引き続き実施していきたいと考えているところです。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"しかも単身の倍率が５５倍と求められている住宅については、住宅施策がゆがんでいると今までも述べさせていただきましたけど、改めて指摘させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"つる委員","kind":"質問","question":"配布場所なのですが、この考え方というところをまず教えてください。対象がいろいろ、何向けとかあって、全世代だからというところだったのですが、この配布場所になっているということを説明を求めました。","respondent":"川原住宅課長","answer":"配布場所についての考え方というご質問であったかと思います。品川宅建管理センターに管理をお願いしていますので、この品川宅建管理センターの中延の事務所のほうでも配布をさせていただいているです。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問","question":"今の答弁を伺うと、例えば、今あるのかもしれないですけど、シルバーセンターは配布場所になっていないのですかね。配布場所になっていないという理由も含めて説明を求めました。","respondent":"川原住宅課長","answer":"そういったシルバーセンターの設置等も研究してまいりたいと思います。ご意見ありがとうあります。","id":"exchange-010"},{"speaker":"つる委員","kind":"質問・要望","question":"そういう視点でもちょっと確認させていただいたのですけど、同じような配布場所だと思うので、ぜひ検討いただきたいなと思います。これは要望で、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-02","title":"令和５年度指定管理者による管理に対するモニタリング・評価","agenda":"令和５年度指定管理者による管理に対するモニタリング・評価","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"昨年聞いたところ、５年に一度の契約のときにはやっているというお話だったのですが、この労務関係のチェックは常にやるべきではないかと思います。いかがでしょうかというのと、それぞれの労務関係の状況を伺いたいと思います。","respondent":"川原住宅課長、中西環境課長、山下交通安全担当課長","answer":"今年度についても、実施した内容については鋭意確認をするところです。細かな視点、指摘事項があったものについては… アクティオ株式会社についての労務管理のチェックです。社会保険労務士による労働環境のチェックが指定管理３年目のタイミングで行われるものですので… なお、人件費につきましては、一般管理費のおおむね約６割というところで把握をしています。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問・要望","question":"住宅のところは昨年、令和５年度にやられたということですかね。あったのかどうか確認させていただきたいのと、そのためにも、毎年この労務関係をチェックしていくことをお願いしたいと思います。","respondent":"川原住宅課長","answer":"株式会社品川宅建管理センターに関しても、法令違反があるレベルに達しているという事例はございませんでした。一部、提出期限漏れの書類の提出があったところの指摘があったところが減点となってございましたが、特に法令違反等はございません。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問・要望","question":"夜９時までやっていますので、そうした中で大変だろうとは思っていたのですが、どういう状況だったのかというところを伺いたいと思います。シニアボランティア、学生ボランティアなどがいらっしゃるということなので、その内訳も分かれば伺いたいと思います。","respondent":"中西環境課長","answer":"職員からも、２名増えたことで体制が回りやすくなったといったお話は聞いているところです。全体で１９名のボランティアの方にご登録をいただきまして、講座ですとか、あとはエコルフェスのイベント等で従事をいただいているといった状況です。","id":"exchange-014"},{"speaker":"のだて委員","kind":"質問","question":"いかがでしょうかというのと、ボランティアの方は１９名ということで、そうしたボランティアの方の労働環境はどうなっているのかというところを伺いたいと思います。","respondent":"中西環境課長","answer":"エコルとごしの職員と会話を続けておりますので、その中で体制が組めるところに関してはこちらでも対応してまいりたいと考えています。","id":"exchange-015"},{"speaker":"のだて委員","kind":"質問","question":"その講座の内容を伺いたいのと、シートにもエネルギー削減率が９８.５％と書かれておりますけれども、その実績をもう少し詳しく伺えたらと思います。いかがか尋ねました。","respondent":"中西環境課長","answer":"６９講座ありますので、かいつまんでご説明をしますと、様々なジャンルを設けてあります。例えば５月、６月の時点では空調をそんなにかけずに地中熱の冷えた空気で足元が涼しくなる、こういった削減率になっていると認識しています。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問・要望","question":"こうした施設を増やしていくことが必要だと思いますので、環境課としてもその重要性を訴えていただいて、ぜひ広げていってほしいと求めました。原発がある中で再エネ利用も抑制されているということも知らせて大本から変えていこうという講座も必要ではないかと思うのですが、いかがか尋ねました。","respondent":"中西環境課長","answer":"区としても、引き続き施設整備課、それから学校施設担当とも連携しながら進めてまいりたいと考えています。引き続き進めてまいりたいと考えています。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問・要望","question":"それはもちろんやっていただきたいと思うのですが、日本もＣＯ２の排出が世界でも５位というところですから、これは要望しておきたいと思います。９０日以上、そうすると３か月かかるというところで、区としてこの対策など考えているところがあれば伺いたいと思います。","respondent":"川原住宅課長","answer":"なので、６か月を超過して入居まで時間がかかった方がいたというのが事例としてあったところです。人数の細かいところは今確認中です。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"令和３年度は６１日ということで短めになっていますので、そうしたところで進めていくというところが、それでも約２か月ですからね。実際にどういった形でつなげてきたのかというところが分かれば伺いたいと思います。","respondent":"川原住宅課長","answer":"その中でも、ご説明を丁寧にさせていただいた上で、まずはその方が保護を受ける前であれば相談係のほうに引き継ぐといったケースは実際にあります。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"生活保護のほうもつないでいただいているということで、ほかにも保険料ですとか税金ですとか滞納している可能性もありますので、そうしたところもしっかりと福祉関係にもつなげていただいて、暮らしていけるように支援していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"横山委員","kind":"確認","question":"一つ一つ確認をさせていただけたらと思っています。計画的、それを引き続き行っていくということだと思うのですが、現在の状況について確認させていただけたらと考えています。","respondent":"川原住宅課長","answer":"令和５年度に実施したものではなくて今年度実施する予定ということでよろしいでしょうか。実際に令和６年度に実施する修繕につきましては、区民それぞれ計画修繕として、今年度実施予定ということで上がっているところです。","id":"exchange-021"},{"speaker":"横山委員","kind":"質問・要望","question":"計画のほうも見直ししたり、必要に応じて進めてほしいと求めましたので、要望します。ボランティアのところですけれども、何人くらい減ってしまったのか尋ねました。","respondent":"中西環境課長","answer":"お子様と触れ合うことが楽しいと思っていただける方ですとか、そういった部分を含めて今後、検討してまいりたいと考えています。増えているのかなという認識がありますので、プライベートでの活動、そういったものを受け入れられる態勢を組んでいきたいと考えています。","id":"exchange-022"},{"speaker":"横山委員","kind":"質問・要望","question":"インターンではないですけれども、何かいろいろな関わりのポイントを作っていくところを工夫していただきたいなと考えています。もう１点、来館者は何語をお話しになられる方がどのくらいいらっしゃって、国の傾向とかがもしありましたら教えていただけたらと思います。","respondent":"中西環境課長","answer":"外国語のスタッフに関しましては、１名英語がしゃべれるスタッフがおるという状況です。定数的に取れているものがございませんので、ただ、英語がしゃべれるスタッフのほうで対応させていただいているところです。","id":"exchange-023"},{"speaker":"横山委員","kind":"質問・要望","question":"これまでいろいろ自転車の駐輪場について、区民の皆さんの利便性の向上のために様々な工夫をしていただいてきたなと私は思っております。そういうところも見ていただきながら、使いやすいものにしていっていただけるといいなと思いますので、要望で終わらせていただきます。","respondent":"川原住宅課長","answer":"そこの点をご承知おきいただきたいのと、あとは現時点で判明しているのが８月末時点での滞納者の世帯数という形でのご答弁となります。区営住宅においては１７世帯、区民住宅においては５５世帯という形になってあります。","id":"exchange-024"},{"speaker":"つる委員","kind":"確認","question":"この中でお声として伺ったので確認ですが、南大井５丁目で地域の方から伺うと、お風呂とか配管ですかね。ここの予算執行、財務の視点というのは、どちらのセルフチェックなのかというところも含めて説明を求めました。","respondent":"川原住宅課長","answer":"ただ難しいのが、現状、居住者の方がいながらの工事というところでは補修の工事を緊急的な工事も含めて選ばざるを得ない状況です。退去した際には、原状回復費用は年々高騰しているのですけれども、退去後にはしっかりと根本的な部分を修繕しているといった事情があります。","id":"exchange-025"},{"speaker":"つる委員","kind":"質問","question":"それも含めて必要かどうか、やらざるを得ないというか、この辺は施設の維持というところではどうなのだろうと思います。当然、入居者のお考えだとかが大事だと思うのですが、施設維持、水回りの劣化状況がどのぐらいなのか、この辺りはどういうお考えか尋ねました。","respondent":"川原住宅課長","answer":"ファミーユにつきましては、そういった一時的な修繕で必要な場合は、そこの空いた部屋に移っていただくといったご案内もさせていただいたところです。","id":"exchange-026"},{"speaker":"つる委員","kind":"質問","question":"ぜひ検討していただいて。ちょっと一回退いてもらいますよという話は、それぞれの該当する方には、既に話としてはずっとされているという理解でよいか尋ねました。","respondent":"川原住宅課長","answer":"委員がおっしゃっていたケースが同一人かというところは後ほど確認させていただければと思いますけれども、私のほうで報告として把握しておりますところには、同室の区民住宅内での部屋の一時の転居というご案内はしたケースはあったと伺っているところです。","id":"exchange-027"},{"speaker":"つる委員","kind":"質問・要望","question":"これは定期利用のところを使ったから１００％を超えているという意味ですか。令和５年度については決算書を見れば分かったのですけれども、年間の使用料は全部で幾らになっているか説明を求めました。","respondent":"山下交通安全担当課長","answer":"当日、バイク、自転車込みで２億６,１８６万円という計上になっております。","id":"exchange-028"},{"speaker":"つる委員","kind":"質問","question":"そうすると、指定管理者の数字、１ページ目の収入指定管理料というのは、指定管理者、ＮＣＤの収入ということなので、２億３,８４３万円。区の収入が２億６,０００万円余ということなので、そうすると、駐輪場の区としての運営という部分ではうまくいっているという理解でよいか尋ねました。","respondent":"山下交通安全担当課長","answer":"そういった費用がかかってまいりますので、全体からすると１００％ではないですけれども、支払っている額よりは確かに歳入があるです。","id":"exchange-029"},{"speaker":"つる委員","kind":"質問","question":"当日で１か月使ってもらったほうが区の入るお金は１,２５０円とかそのぐらい違うわけです。こういう視点ではいかがか尋ねました。","respondent":"山下交通安全担当課長","answer":"１００％以上に達していて満車である場合に案内することによって、駐輪場での対応になってくると思いますので、管理員が柔軟に対応できるような指導等をしていきたいなと考えております。","id":"exchange-030"},{"speaker":"つる委員","kind":"意見","question":"その他の駅周辺等の駐輪対策に充てていく、本当に僅かかもしれないですけども、でもそういう視点というのは大事ではないか。それは当然利便性向上というのが必須である中で、そこを有効活用するにはどうしたらいいだろうという線引きをまた引き続きお願いしたいと思いますとの意見を述べました。","respondent":"山下交通安全担当課長","answer":"大変失礼しました、昨年令和５年度におきましては、２億１,３５８万円と若干歳出を下回っている状況ということが確認できましたので訂正します。大変申し訳ありませんでした。","id":"exchange-031"},{"speaker":"つる委員","kind":"質問・要望","question":"その訂正の下で、であるならば、むしろどれだけもう少し利用料で増やしていくかということも、これは努力として、これはこれで必要。区としても、先ほど指導とあったわけですけれども、していただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"}]},{"id":"topic-03","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"塚本委員長","kind":"質問・要望","question":"視察先で特に質問や確認したい事項、ご要望について伺いますが、既に視察先より質問等があれば事前に伺いたいとの依頼があり。視察先について、この場で質問、確認したい事項、ご要望等がございましたらご発言をお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"のだて委員","kind":"質問","question":"専用住宅があるのかどうか、どういう形になっているのかというところで、そこが結構いろいろなところでも課題。品川区もゼロということですので、そこのところをお聞きしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"横山委員","kind":"質問・要望","question":"離婚を検討中の方、ＤＶ被害者の方、そういった方への支援をどうやっていらっしゃるのかというところを詳しくお伺いできたらと考えています。パンフレットの２１ページに、住まいだけではなくて、勉強させていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/463917?Template=document&Id=6827#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":37799,"voices":91}},{"id":"r06-20240925-9","meetingId":"r06-cm09","date":"2024年9月25日","dateIso":"2024-09-25","committee":"文教委員会","time":"午前１０時００分～午後 １時４６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件整理しています。","topics":[{"id":"topic-01","title":"品川区教育振興基本計画（素案）に係るパブリックコメントの実施","agenda":"品川区教育振興基本計画（素案）に係るパブリックコメントの実施","exchanges":[{"speaker":"田中委員","kind":"質問","question":"幾つかありますが、今回、この素案に関してのパブリックコメントを行うという報告でありますので、教育ビジョンの中身についてのやり取りは大丈夫か尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"田中委員","kind":"質問・要望","question":"寄せられた内容にもよりますが、コメントの内容によっては、この素案自体の修正ということも可能なのかどうかという確認です。その位置づけをお聞かせほしいと求めました。","respondent":"舩木庶務課長","answer":"パブリックコメントの目的は、広く区民の方に周知し、そして、いろいろなご意見を頂くことと認識しております。しっかりと策定委員会を設置して、ないかも含めて、私ども教育委員会での審議で考えていきたいと考えております。","id":"exchange-002"},{"speaker":"田中委員","kind":"質問・要望","question":"その上で、少しお伺いしたいところがあります。子ども中心のビジョンであるべきだと思っていますが、そのことについてのご意見といいますか、受け止めをお聞かせほしいと求めました。","respondent":"舩木庶務課長","answer":"ご説明しましたように、まさにＯＥＣＤ「ラーニング・コンパス２０３０」で、ここは区としても示していきたいところです。ご指摘の２３ページにつきましては、品川区がこれまで進めてまいりました「品川教育ルネサンス」で示されている３つの基盤をしっかりと活かした上で。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"どのような人物育成につながったか、あるいは小学校・中学校の分離型の学校を卒業した卒業生の声も、私は聞くべきかなと思っているのです。その検証についての今の受け止めをお聞かせほしいと求めました。","respondent":"舩木庶務課長、中谷指導課長","answer":"市民科の発展と申し上げましたが、学習にどのように活かしていくかというところは、これからさらに進めていかなければいけないところと考えています。卒業された方がどのような進路をたどってという部分… 「プラン２１」時代にご自身が品川区の公立学校のお子さんとして学ばれて、大人になって、教員として帰ってきてくれるということが起きています。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ検証のほうも受け止めていただいて、進めてほしいと求めました。もう少しいいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問","question":"今年も１月１日から能登半島で大きな災害がありましたが、やはり一つの切り口として取り入れていくべき大きな課題だと思っているのです。３６ページ、３７ページでのＳＤＧｓ関連について、受け止めはいかがか尋ねました。","respondent":"舩木庶務課長","answer":"学校教育として捉えたときに、主たるもの、一番結びつきの濃いものをここに示しているということで、今、素案を示しております。あるいは、区の中でこのような考え方をどのように受け止めていけばいいかというところも、連携をとりながら整理していければと考えております。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問","question":"その中で若干伺いたいのですけれども、２７ページの今回特筆すべき点として、「学びの羅針盤」２０２３というところです。そこを、まず１点、伺いたいと思います。","respondent":"舩木庶務課長","answer":"子どもたちがそういったことを認識して、当事者である子どもの意見を反映させるために、９月の初旬に様々な声を聞いているところです。教育現場もそうですし、区が目指す方向性はこのようなことなのだと伝えることについては、しっかりと検討を進めていきたいと考えております。","id":"exchange-007"},{"speaker":"あくつ委員","kind":"確認","question":"何かあればご意見を伺いたいのですが、３４ページの方針８のところで、災害時における教育活動の継続に向けた体制構築があります。ここに書いてあるので、そういうことなのでしょうけれども、そういったことなのかどうかを確認したい。","respondent":"舩木庶務課長","answer":"初めに、１点補足になりますが、子どもたちに伝わるようにという意味で、本計画につきましては、概要版の作成を予定しております。方針８に見受けられますように、このような体系的に施策推進の方針という形で示したのは、本計画が初めてだと認識しております。","id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"子どもとしてそういった能力と資質を身につけて、子どもたちが共生社会をつくるというメッセージをぜひ入れていただきたいという発言がありました。大変すばらしいご意見だと思って、そういったこともきっとこの計画の中には入っているのだと思うので、また別の機会にお尋ねします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"山本副委員長","kind":"質問・要望","question":"今、ご答弁いただきましたとおり、さらにそれぞれの具体例として展開いただけるように、情報共有しながら進めてほしいと求めました。１点、知っていただくことはいいと思うのですけれども、いかがか尋ねました。","respondent":"舩木庶務課長","answer":"第一義的には、広報しながわ、それから、区のホームページにて、広く多くの方の目にとめていただけるような方法で周知をしてまいります。","id":"exchange-010"},{"speaker":"山本副委員長","kind":"意見","question":"私も区内小・中学校に通う子どもがおりまして、感じることとしては、学校にはＰＴＡやそれ以外の保護者の方が出入りされる機会も結構あります。効果的に見ていただけるのかなと思いますので、御検討ほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"西村委員","kind":"質問・要望","question":"私からも１点質問と、感想も述べさせてほしいと求めました。１点伺いたいのが、柱２に「誰一人取り残さないきめ細やかな教育」とあるのですけれども、私には発見できませんでした。","respondent":"丸谷教育総合支援センター長","answer":"方針７の「ダイバーシティ＆インクルージョンに根差した教育」という方針の中で不登校支援の１つの例として「メタバースを活用した学習支援」をあげ…教育支援センターのマイスクール等も含まれておりまして、不登校施策の一連のものがここに含まれているようにしております。","id":"exchange-012"},{"speaker":"西村委員","kind":"質問・要望","question":"要望でもあるのですが、特に誰一人取り残されないという意味においては、どうぞよろしくお願いいたします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"せらく委員","kind":"質問・要望","question":"空欄ではあるのですが、このワークショップはいつ開催するのかというところを教えてほしいと求めました。３４ページの方針８「社会・経済状況によらない教育の実現」というところで、それについて、ご意見や思いをお聞かせほしいと求めました。","respondent":"舩木庶務課長、柏木学務課長","answer":"子どもたちに分かりやすいようにもう少しかみ砕いて丁寧に説明した上で、ワークショップを行い、共有するということを行いました。今後、今期の素案では示し切れておりませんけれども… できるものはやっていきたいと考えていますが、まだ、何をするということを区として決めたというものはございません。今後、予算編成の中で、様々議論しながら整理をしていきたいと考えています。","id":"exchange-014"},{"speaker":"せらく委員","kind":"質問","question":"無償化の部分では、こちらの計画の中には、文言として教材費と給食費が入っているところですけれども、今後、ほかの部分も追加される可能性があると認識してよろしいか尋ねました。","respondent":"柏木学務課長","answer":"今、これをやるというものはないので、お答えできないところですけれども、先ほどの答弁の繰り返しになりますけれども、今後、予算編成の中で様々議論しながら整理をしていきたいと考えています。","id":"exchange-015"}]},{"id":"topic-02","title":"令和５年度保護者アンケートおよび児童・生徒アンケートの結果","agenda":"令和５年度保護者アンケートおよび児童・生徒アンケートの結果","exchanges":[{"speaker":"田中委員","kind":"確認","question":"併せてお伺いしますが、特に保護者アンケートの６番の「現在通っている学校に満足している」というところで、「満足」が全体で９２.５％とあります。そこを確認したいと思います。","respondent":"中谷指導課長","answer":"肯定的な回答は９２.１％というところで、ご指摘いただいた５.８％、「当てはまらない」という回答もあるところです。様々な教育活動で実施しているところで、一部のお子さんに対する学習支援、より一層きめ細かくやっていく必要があると捉えているところです。","id":"exchange-016"},{"speaker":"田中委員","kind":"質問・要望","question":"親御さんのコミュニティ・スクールの真に「当てはまる」は４０数％ということで、つながっているように受け止められるのです。この分析結果を見て、どのように受け止めていらっしゃるのか。","respondent":"中谷指導課長","answer":"全校で「品川コミュニティ・スクールＤＡＹ」という行事を実施させていただいておりまして、お子さんと大人が同じ場で交流をするというものです。一定の成果が出ているのではないかなと思っており、この活動については、やはり継続していきたいなと考えています。","id":"exchange-017"},{"speaker":"田中委員","kind":"質問・要望","question":"このような傾向で、経年的な評価も、今、お話いただいたとおりだと思っていますので、そこも含めて、しっかり保護者の方や児童・生徒の方の声を教育の改善に活かしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"西村委員","kind":"質問・要望","question":"４番の将来なりたい職業ややりたいことのところで、何かお考えがあれば、お聞かせいただきたいなと思います。児童・生徒が日常的に取り組んでいたり、イメージができるボランティア活動にはどのようなものがあるのか、改めてお聞かせほしいと求めました。","respondent":"中谷指導課長","answer":"今、取り組める「しながわドリームジョブ」などの取組にもぜひ希望を挙げていただきたいという投げかけをしてまいりたいと考えています。","id":"exchange-019"},{"speaker":"西村委員","kind":"意見","question":"コロナ禍に町会、また思い出していきながら、積極的に児童・生徒が関われる機会を増やしていければいいなと思いました。ありがとうございましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"高橋（し）委員","kind":"質問","question":"地区委員会のイベントや、そういうボランティアの事例がリスト化されて、学校に提示されているのかというところをお尋ねします。本当は、児童・生徒の質問に「多様性・多文化理解」とあるため、もしそちらも何か分かったらお願いします。","respondent":"中谷指導課長","answer":"ご覧いただいております概要版と、それぞれの各項目のグラフを、こちらの会議が終わった後にアップする予定でおります。実際、一般的には特別支援学級がある学校のほうが、やはり肯定的な回答の数値が高く出やすいというところはあるかなと考えています。","id":"exchange-021"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"かなりコーディネーターの方同士のネットワークですごく緊密にやりとりが行われていると伺っているので、そこでもお話が出ていると思うのです。特別支援学級と多様性との認識というか、関係については、また別の機会にお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"山本副委員長","kind":"質問","question":"私からも２点伺わせていただきます。来年度以降は変わった形にしていく必要があるのかなと思ったのですけれども、そこら辺をどのようにお考えかということを説明を求めました。","respondent":"中谷指導課長、舩木庶務課長","answer":"設問７の回答結果ですけれども、やはりＩＣＴの活用というのは、校種を問わず、年々進んでいるかなと思っています。ですので、会社で何を体験するかというところも、積極的に情報を取って進めていきたいと考えています。 いろいろなところにしっかりと根づかせてご理解を頂いていくことが肝要かと思いますので、同時に、そういった中で設問の在り方についても検討していきたいと考えております。","id":"exchange-023"},{"speaker":"山本副委員長","kind":"質問・要望","question":"そして、ぜひともそのようなことをして進めていただきたいと考えています。併せて、どう効果検証していくかというところもすごく大事だと思いますので、ぜひ在り方のほうも検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]},{"id":"topic-03","title":"区立学校におけるいじめの重大事態の発生状況","agenda":"区立学校におけるいじめの重大事態の発生状況","exchanges":[{"speaker":"せらく委員","kind":"質問","question":"今回、いじめの重大事態の分類が１号、２号、どちらも当てはまるということなのですけれども、これまで１号か２号どちらかということだったので、どちらも当てはまるということは結構重大な内容だったのかなと思うのですけれども、その辺りをお聞かせいただけますか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"１号および２号という形で、１号は生命、財産に重大な被害が生じた疑いがある。どちらが先ということもあるのですけれども、１号と２号にそれぞれ該当するような事案であるということで、このような認定をしているものになります。","id":"exchange-025"}]},{"id":"topic-04","title":"令和５年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"令和５年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"いわゆる運営側の努力もあるのでしょうけれども、コロナ等もありましたが、何かそのほかに分析されていることがあるのかどうかということが１つです。「有資格者配置率は６１％と高い水準を維持している」とありますが、何と比較しているのかというところも少し教えてほしいと求めました。","respondent":"河内品川図書館長","answer":"あるいは外部研修の補助などを行い、より有効な図書館業務につながるよう、業務向上に努めているところです。検索の仕方といった能力を総合的に高めることが、その出口になるのではないかということで、こういったものについても進めているところです。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"意見","question":"そういった中で微減というか、マイナス２％、３％というのは非常に健闘されているのかなというのが正直な感想です。そこについては、区側もしっかりと支援をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"あくつ委員","kind":"提案","question":"行政視察先の候補地として私が提案した徳島市では、５００円で利用できるけれども、そういった改善策をとっていました。その課題をどのように捉え、これからどのような改善策を指定管理者とともに考えていくのか、その辺りをお伺いしたいと思いますとの意見を述べました。","respondent":"染谷子ども家庭支援センター長","answer":"そちらの活用が可能なのかどうかというところを、今、実際に検討・研究を進めているところです。例えば、児童センターなどの公共施設を活用して、そちらでお預かりできるような仕組みを実施できないかという検討を現在進めているところです。","id":"exchange-028"},{"speaker":"あくつ委員","kind":"確認","question":"真摯に取り組んでいただいていることが確認できましたので、できれば来年度から、今おっしゃられた検討・研究されていることを１つでも実現してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"西村委員","kind":"質問","question":"区民に寄り添っていただいている取組が様々ありますので、指定管理者の中で取り組んでいることがあれば、伺いたいというのが１点です。今は、教え合ったり、その辺りでどのような取組が考えられるかのご意見を伺いたいと思います。","respondent":"河内品川図書館長、染谷子ども家庭支援センター長、飛田子育て応援課長","answer":"いろいろな地域の方との連携や、人の流れやにぎわいの創造も含めまして、皆様の教養に資するようにということで取り組んでいるところです。仲間と… 子育て短期支援事業における年齢拡大に関してお答えいたします。利用が発生していますけれども、全体から見ると非常に少ない数でして… あんしんセンターの退所者の自立支援の件ですが、また日常の生活の困り事などはないか聞き取りをして、処遇などを一緒に相談に乗っているところです。","id":"exchange-030"},{"speaker":"西村委員","kind":"質問","question":"そこは学校と連携していただいていると伺っているのですけれども、品川区の図書館は本当に居心地がいいですから。今後、児童相談所とのすみ分けや連携もさらに重要になってくると思いますので、引き続きお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"高橋（し）委員","kind":"質問","question":"そういう観点で、今後の図書館とまちづくりとの関わりをどのような形で役割を果たしていくかというところを少し伺いたいです。図書館の持っている本や役割、あるいはいろいろな特集をできる指定管理者のパワーなどもあると思うので、その辺を少しお願いします。","respondent":"河内品川図書館長","answer":"先ほど、若年層に対しまして、全年齢層に関わるところを強みとして持っていくところが今後の大事なポイントではないかなと考えているところです。障害者のバリアフリーなどの対応、まちづくりの核として、非常に重要ではないかと考えているところです。","id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今後も、ぜひまちづくりの核として、より一層図書館を活用してほしいと求めました。これは確認で、もしその辺が分かれば、お願いします。","respondent":"芝野保育入園調整課長","answer":"話しあいのほうは進めておりまして、令和１３年に認定こども園化を目指すということで検討を進めている〔同日後刻に「西五反田保育園の改築が令和１３年度に終了予定となっておりますので、認定こども園化の検討を行っている」と答弁訂正あり〕ところです。","id":"exchange-033"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"少し先の話ですけれども、ぜひ円滑に進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"田中委員","kind":"確認","question":"図書館からお伺いします。１つの成果として、そのようなことが可能なのかどうか、確認したいと思います。","respondent":"河内品川図書館長","answer":"その中で、指定管理者ですので、例えば、館の運営、選書、トラブル対応、いろいろな強みがあります。そういった情報も引き上げるように、毎月の館長会、定例会などでも共有しています。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"そういう中で、ここにもあるように、開園されて２０年、施設としては約３０年ぐらいですか。確保についての今現在と、将来的な建て替えも含めて、安全確保の視点での区の責任についての考えをお聞かせほしいと求めました。","respondent":"芝野保育入園調整課長","answer":"区の安全管理に関する考え方ですが、開設後２０年ということで、一部の施設については老朽化が進んでおります。建て替えの考え方ですが、まだ施設が２０年ですので、検討していかなければいけない課題であるということは認識しております。","id":"exchange-036"}]},{"id":"topic-05","title":"法改正に伴う児童扶養手当の所得限度額の引き上げ等","agenda":"法改正に伴う児童扶養手当の所得限度額の引き上げ等","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"今回の限度額の引き上げに伴いまして、対象人数が増えてくると思いますが、どれぐらい増えるのか。今までと比較しまして、トータルでどれぐらいの支給額が増えるのか、お聞かせほしいと求めました。","respondent":"飛田子育て応援課長","answer":"今のところ、試算しますと、約３４０人ほど増えるのではないかと考えております。予算としまして、令和６年度分の増額として、現在６,５８５万円を想定しています。","id":"exchange-037"}]},{"id":"topic-06","title":"順番を入れ替えて、予定表の３、その他","agenda":"順番を入れ替えて、予定表の３、その他","exchanges":[{"speaker":"西村委員","kind":"質問","question":"この施設に直接見に行かせていただくのだろうなということが分かるのですけれども、大和郡山市などは、どこでお話を伺うのか。役所の中でお話しいただくだけなのか、「ＡＳＵ」に行くのかということがもし分かれば、教えていただけますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/435368?Template=document&Id=6825#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":52096,"voices":142}},{"id":"r06-20240925-5","meetingId":"r06-cm09","date":"2024年9月25日","dateIso":"2024-09-25","committee":"総務委員会","time":"午前１０時００分～午前１１時１９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":"説明に入る前に各所管委員会における審査結果","agenda":"説明に入る前に各所管委員会における審査結果","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私たちも総務委員会等で求めてきたのですが、なぜ９月の補正で予算を組んだというのが分かれば教えていただきたいのと。６年経過以後継続して補助金が出るようにすべきではないか、その辺のお考えはどうか、この３点を伺いたいと思います。","respondent":"加島財政課長","answer":"こちらの検討に時間を要したため、９月補正のほうで今回要求させていただいたような状況となっております。６年経過した後、今後どのような形で検討していくかというのはまた五、六年後に判断が必要だと考えております。","id":"exchange-001"},{"speaker":"西本委員","kind":"確認","question":"難聴対策についての対応はどういうスキームになっていたかなと思っているので、それをお知らせください。なかなかできなくて、今回、この９月の補正で入れ込んだというのはあるのかどうかをまず確認したいと思います。","respondent":"加島財政課長","answer":"介護支援専門員、令和５年度補正でも入れましたけれども、こちらを新たに今回の補正で入れさせていただいているところです。特別支援学校の補助教材費につきましては、こちらは拡大というような内容になってあります。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"これはどういう考えで今やろうとしているのでしょうか。流用していこうという考えなのか、今回、これは何なのか尋ねました。","respondent":"加島財政課長","answer":"今回実施するに当たっての考え方ということなのですけれども、区のほうで子どもが伸びる、育つというところと。年度途中ではありますけれども、東京都のほうでたまたま区で実施を目指していた方向と合致する補助金がございましたので、区立園全園。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"確かにビオトープとか、では、今までの成果の中で品川区としての特徴としてどういう方向に持っていくのかという議論はされているのですか。だけれども、そこは今までやってきたことの整合性はどういうふうにされているのかなと思うのですけれども、いかがか尋ねました。","respondent":"加島財政課長","answer":"今まで実施を確かにしてきた流れというのがある中で大がかりなものを実施しようとしたときには、利用者負担を求めずに実施することができるといった背景からも所管のほうで本事業を活用して、今回の補助の申請に至ったものです。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"義務教育学校になったではないですか。もっと品川区発信でいろいろやれるのではないの、やってきたよねというのが非常にあるのですけれども、その考え方をお聞きしたいと思います。","respondent":"加島財政課長","answer":"幼保一体ですとか、小中一貫ですとか、先進的な施策に確かに区として取り組んできたことは事実です。例えば、これからもるる機会を捉まえてそういったことを実践して予算編成の中でそういった気持ちを持って臨んでまいりたいと考えております。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"これは企画経営部長にお話しいただきたいのですけれども、今回のすくわくプログラムもそうなのですけれども、ちょっと危惧しているのです。今後、品川区はどういう考え方でやろうとしているのか、企画という観点で教えていただきたいなと思っています。","respondent":"久保田企画経営部長","answer":"決してばらまきではありませんので、我々はきちんとした考えに基づいて施策を進めているですので。そういった取組を進めてまいりまして、生きづらさをなくすといったような、そういった品川区を目指して進んでいきたいと考えているところです。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"それは大切にしてほしいなという思いがありますので、説明の中には加えていただきたいなと思います。どういう方向に行っているのかというのが見えなくなってしまうので、ぜひこういう説明というか、考え方をしてほしいと求めました。","respondent":"久保田企画経営部長","answer":"その中の１つとして子育て世代の負担を軽減していくといったことを柱に置いて、この間、政策予算等を組んできたといったところです。子どもたちのいろいろな探究心などを伸ばしていくといったところ、そういった補助金も活用しながら進めていきたいです。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"予備費でも何でも執行をどんどんするべきではないのですか。その３点だけ説明を求めました。","respondent":"加島財政課長","answer":"こちらは国のほうで８月から１０月まで電気料抑制策が取られていましたけれども、今のところ、１１月からはその抑制策がなくなる予定です。令和６年の１２月に仮設校舎を建設すべく、契約行為が動く予定でしたけれども、仮設校舎建設の時期が令和７年６月にずれ込みました。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"区としてもしっかり予定を組んで、各事業を進めているのですから、私は今回のは問題があるのかなと思います。意見だけ言わせていただきます。","respondent":"加島財政課長","answer":"私のほうで鈴ヶ森小学校について説明不足の点があったので、補足させてください。入札を改めてやり直したことによって、今回仮設校舎建設時期が６か月ほど後倒しになってしまったです。","id":"exchange-009"},{"speaker":"須貝委員","kind":"意見","question":"そうするとまた言わなければいけないのですけれども、６か月、結局、不調で延びた。過去にもありますけれども、そういうことがあるというのは一つ大きな、契約の時点で問題点として指摘しておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今回、いろいろ継続実施等を求めてきた省エネルギー対策の拡大とか復活、学校補助教材費の無償化の特別支援学校への拡大など、区民にとって大事なことが含まれておりますので、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"賛成としますが、先ほど企画経営部長からのお答えもいただいて、お考えもお聞きしました。そこは職員の方々、思い出してと私は思いますけれども、今までやってきたのでできるわけですからということで期待を込めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]},{"id":"topic-02","title":"意見書（案）","agenda":"意見書（案）","exchanges":[{"speaker":"西本委員","kind":"確認","question":"出しっぱなしというのも何か、どうなのですか。ちょっと確認してもらっていいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-03","title":"荏原文化センター大ホール照明更新工事請負契約","agenda":"荏原文化センター大ホール照明更新工事請負契約","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"これは要はＬＥＤ化がどんどん進んでいる中で、このタイミングになるというのは順次ということで、今なのでしょうか。そのタイミングのところをお聞きしたいのですけれども。","respondent":"長尾施設整備課長","answer":"区有施設の照明のＬＥＤ化については順次進めております。前回設置したものから経過年数としておおむね１０年程度たっておりますので、このタイミングでＬＥＤ化を図ったという内容になっております。","id":"exchange-014"},{"speaker":"まつざわ委員","kind":"質問","question":"工事にお金をかけるのもいいのですけれども、現場の意見からすると、もう大きくやらないと。いいのではないですかみたいなお話も伺ったことがあって、そういう方向性とか考えというか、そういうものはどうなのか尋ねました。","respondent":"長尾施設整備課長","answer":"３０年、４０年後ということで、まだ長く使っていく計画にしております。大切に使うといいますか、中の設備の更新であるとか、長寿命化を図るといったところを行っていく計画としております。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"長寿命化と決まっていると言いつつも、変更はあり得るのか、どうなのでしょうか。前向きに考えてほしいなと思います。","respondent":"長尾施設整備課長","answer":"建て替えを検討してはいいのではないかというお話ですけれども、私の立場だけでは方向性を変えるとか決めるというわけには行きませんので、今後の活用については引き続き所管課ともきちんと協議・調整をしながら進めていきたいと考えております。","id":"exchange-016"},{"speaker":"西本委員","kind":"意見","question":"委託というやり方もいいのかどうかも含めて、議論していただいたほうがいいのではないか、品川区にとってどうなのだろうか。でも、企画経営部長も副区長もいらっしゃいますので、全体的に考えるべきことなのかなと思いますが、答えられる範囲でお願いしますとの意見を述べました。","respondent":"長尾施設整備課長","answer":"大規模改修であるとか、そういったことに取り組んでおりますので、こういった中で定められているものと捉えております。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"このご時世のことですから、長寿命化という話でいろいろと考えていってというなるべく長く使おうよという動きは分からないではないのです。大胆に方向性を見直してもいいのではないかなと思いますので、ぜひ今後、議論の中に入れていただければなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"須貝委員","kind":"質問・要望","question":"それに共同企業体というのは必要になるのですか。１社で十分賄えるように思うのですが、マスミ電設は確かに電気工事の専門だと思うのですけれども、それだけ理由を説明を求めました。","respondent":"佐藤経理課長","answer":"共同企業体に関してということだと思いますが、こちらに関しては施工能力もそうですし、あとは区内の事業者の育成というところもありますし、区内事業者への受注機会の確保というところもありまして、一定の基準に沿って設定しているというものです。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"だから、それが不思議な組合わせだと私は思いますので、今後、何か対応を私は考えてほしいと求めました。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"お忙しい中、ありがとうあります。多くの事業者が大変だというようなご意見がいっぱい来ているのかなと想像したのですけれども、ちょっと違っていましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"西本委員","kind":"確認","question":"毎回毎回聞かせていただいておりますが、「秀」の件はどこまで動いていますか。それだけ確認をさせてください。","respondent":"勝亦総務課長","answer":"国際友好協会の関係ですので、現在、国際友好協会と持ち主の方との間で賃貸借に向けて協議、それからその受入れのための準備をしているという状況だと聞いております。","id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"前回の委員会のときと同じご答弁なのですけれども、進展はないという、継続してお話合いが進んでいますという段階なのか尋ねました。","respondent":"勝亦総務課長","answer":"契約が必要になってまいりますので、契約の準備をしているという状況でございまして、継続的に協議、準備をしているです。","id":"exchange-023"}]},{"id":"topic-05","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"こしば委員長","kind":"提案","question":"どういう視点を持って調査をしていきたいのかということを先方に聞いて確認したいかなどを各委員、ご意見や質問事項を出してほしいと求めました。現時点において視察先で特に質問や確認したい事項、ご要望等がございましたら、ご発言を願いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"松本委員","kind":"確認","question":"もう数年やられていると思うのですけれども、この成果についてどういうふうに評価されているのかというところはお伺いしたいかなと思います。しながわ」は今年の３月３１日か尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"西本委員","kind":"意見","question":"長野市が取り組む前、シティプロモーションをやっていたのかな、どうなのかなという。取り組んでいればの話ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"西本委員","kind":"意見","question":"だから、１０月の末で実際、１２月ですね。載せてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/837879?Template=document&Id=6833#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":24231,"voices":85}},{"id":"r06-20240926-14","meetingId":"r06-cm09","date":"2024年9月26日","dateIso":"2024-09-26","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 ２時００分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を71件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"今、説明の前段で、区民アンケートのどういうご意見を基にテーマとして取り上げたのか。どうしてこのテーマを選ばれたのか、区民の関心がどこにあったのか、そもそも論で説明を求めました。","respondent":"吉岡政策推進担当課長","answer":"今後も残してほしいイベント、こういった催しのところで、祭りが挙げられたところです。どういった支援を行っていくかというところで、今回、分野とさせていただきました。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問","question":"最近では宿場まつり等もこれから開催されますけれども、そういったイベントとしての祭礼、祭りということは分かりました。ご説明の中であった商店街というところへの区民の関心、アンケート等で何か読み取れるところがあったのか、そこについてもう一度説明を求めました。","respondent":"吉岡政策推進担当課長","answer":"しかしながら、地域でいわゆるステークホルダーとしてご活躍していただいている団体の連携を促していくことが重要というところもあります。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"９月１０日ですから、またこれから決算特別委員会等でそれは披露されるのかなとも思うのですが、最後に少し伺いたい。有識者とか、また地域の区民の委員の方から、どういった意見が出たのか、代表的なものを最後に説明を求めました。","respondent":"吉岡政策推進担当課長","answer":"１つご紹介しますと、町会や自治会が何をしているか分からない、こういったものを知っていただく必要があるのではないかという核心に迫るようなご発言をいただいたというところが主な意見です。","id":"exchange-003"},{"speaker":"筒井委員","kind":"質問","question":"私からも伺いますけれど、令和５年度は防災強靱化、そして環境ということだったと思います。それとも、その時々の区民のお声の大きさなどから適宜判断していくのか、どういった判断基準でこうした評価対象分野を決めているのか説明を求めました。","respondent":"吉岡政策推進担当課長","answer":"品川区において、まさに二重の評価になってしまう部分もありますので、そういったところが重ならないよう配慮が必要というふうに考えてあります。こういった分野を回していこうという考えは、検討中でございまして、１つ考え方として示させていただいたところです。","id":"exchange-004"},{"speaker":"山本委員","kind":"質問","question":"１点目が、定量的な目標設定が妥当かどうかの判断は、誰がどのようにされているのでしょうかというところがまず１つです。それから、事務事業評価の客観性と専門性を高めるために、外部の専門家による評価を導入する予定がありますでしょうか、これです。","respondent":"吉岡政策推進担当課長","answer":"これを１から事業を説明して評価をしていただくことは現実的ではないというふうに考えております。こういった事業をご説明させていただいて、そういったご提言もいただいておりますので、少しかなえているのかなというふうに考えてあります。","id":"exchange-005"},{"speaker":"山本委員","kind":"質問・要望","question":"効果をさらに高めるために、さらに改善を進めてほしいというふうに思っております。それから、区民の皆様へも分かりやすく説明するための工夫も検討を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"事務事業評価シート、６６９事業に及ぶそれぞれ１つ１つの事業を確認していただいて、まとめていただいております。１年目につくられたこと、２回目ということで、その流れがどういうふうに生かされているのかというところを少し教えてほしいと求めました。","respondent":"吉岡政策推進担当課長","answer":"この事務事業評価の前年度からの変更と申し上げますが、この事務事業評価シートをご覧いただくと、あまり大きな変更点はないというところが。説明会を通しながら、そういったものもしながら、記載の仕方が各部でまとまってきたというところがあります。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"３回、ほかにも商店街やＮＰＯですか、どういった議論がされたのかというところを伺いたいと思います。今回こうした行政評価を行っていく中で、そうした福祉を削るようなことがないようにしていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"どのような活動をされているのかとか、地域の中でどういった連携ができるのかとか、そういった結びつきについての意見が出たというところがあります。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひそうしていただきたいと思うのですけれども、予算特別委員会か、それが品川区だけ２３区の中でやられていないということを紹介されました。そうした福祉の切り捨てがないように、これは改めて強く求めておきたいと思いますので、さらにご答弁があれば伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"そういったところで必要な財源、あるいは人的コスト、そういったものを確保していくというようなところです。あるいは補正のところでもいろいろ対応させていただいてありますので、そういったものを確保しながら実施していきたいというふうに考えてあります。","id":"exchange-009"},{"speaker":"せらく委員","kind":"確認","question":"もう１点、政策評価委員の公募を行っていらっしゃることをホームページで確認したのですけれども、任期が１年というふうに書いてあります。お願いします。","respondent":"吉岡政策推進担当課長","answer":"今後の品川区を背負っていく、あるいは日本社会を背負っていく若い方からも今のお考えを聞きたいということで、これが２名お願いをしています。全５回なのですけれども、この５回だけに限らず、任期を１年と定めてあります。","id":"exchange-010"},{"speaker":"新妻委員","kind":"確認","question":"今、２人の委員から、評価委員会の委員について確認がありましたので、１点、確認します。公募区民の方が３名から２名になっているというところで、より多くの声を聞いていただくには、今回減った理由だけ教えていただけますか。","respondent":"吉岡政策推進担当課長","answer":"委員会の進行、進め方というところで、委員総数自体をなかなか増やすことは難しいというお話があったというところが１点です。実施するときにおきましても、次年度、どういったメンバーでやっていくのかというところは改めて検討していきたいというふうに考えてあります。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"１人、２人の増員というところも、公募区民の方もしっかりと人数は確保してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"つる委員","kind":"確認","question":"総務委員会でいろいろ審議させていただいたときの質疑を改めて確認して、令和８年度ぐらいの予算編成で、そこが見えてくるでしょう。今走っている令和６年度の中に、事務事業評価をやった、まさに成果、評価として反映されたものがあるということがあれば、説明を求めました。","respondent":"吉岡政策推進担当課長","answer":"この事務事業評価、本格実施は今年度２年目です。あるいは、それに向けた新たな事業ができてくる、そういった考え方は各所管で持っていらっしゃるのかなというふうに考えてあります。","id":"exchange-013"},{"speaker":"つる委員","kind":"提案","question":"施策展開、職員提案制度などで今年度もいろいろな事業の提案が出てきているとは思うのですけれども、考え方として浸透させていくことが必要なのかと。","respondent":"吉岡政策推進担当課長","answer":"事務事業評価においての説明会を通して、こういった部分についてご説明を、庁内で共有を図ってきたところです。そういった新しい手法の取り入れ方、運営の仕方、こういったものが出てくるのだろうなというふうに捉えているところです。","id":"exchange-014"},{"speaker":"つる委員","kind":"確認","question":"最後に確認で、１つの事業をぐっと見ていくわけですけれども、その事業だけが単独で何か１つ課題に対して事業を行っているわけではないですよね。要は、事業間の関連性や関係性だとかということは、どういうふうにしてこのシートにまとめられているのか説明を求めました。","respondent":"吉岡政策推進担当課長","answer":"まず、１事業に対してのというところになってきますので、なかなかこれをもって連動させていくということは難しいかなというふうに考えております。","id":"exchange-015"},{"speaker":"つる委員","kind":"質問・要望","question":"今言っていただいた事業、施策、政策と１つ大きなカテゴリーがあるわけです。なので、先ほどご答弁いただいたとおりなのですが、引き続き、よりよいものにしていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"西村委員","kind":"質問・要望","question":"私も集まりやすくしていただきたいなと思いますので、お考えがあれば、お聞かせほしいと求めました。","respondent":"吉岡政策推進担当課長","answer":"公表いたしまして、特段、何か区民の皆様から行政評価についての質問ですとかお尋ねがあったということはございません。分かりやすい資料、知っていただくための機会、こういったものは設けていく必要があるのだろうというふうに捉えているところです。","id":"exchange-017"},{"speaker":"筒井委員","kind":"提案","question":"政策評価について、地域社会が今回テーマに選ばれました。先ほども新妻委員からもご提案がありましたけれど、政策、その辺りのお考えをまず説明を求めました。","respondent":"吉岡政策推進担当課長","answer":"大学生の方に入っていただいたのですけれども、やはり行政が行っていることは、あまり知られていない部分も多いなということを肌で感じたところです。こういったものについては、より広報、周知の工夫が必要であると再認識しています。","id":"exchange-018"},{"speaker":"筒井委員","kind":"質問・要望","question":"これは要望で終わります。令和４年度の行政評価シートについてになるのですけれど、分かれば教えていただきたいことと、それについてのご所見について伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"「Ｃ」評価につきましては、そのうちの３２４事業が「Ｃ」評価というところで、全体の割合から申し上げると４８.７％、約５割でした。しっかりと見させていただきながら評価をつけていくということで、昨年度同様、今年度もやっていきたいと考えています。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問・要望","question":"「Ｃ」評価をつけられた後は、適宜、担当の所管課と連絡しながら、きちんとチェックをされているというようなイメージでよろしいのでしょうか。仕方を教えていただきたいのと、それはもう完全に事業の廃止ということで、そうした見方でよろしいのか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"それに向けた検討を行っていくというところも「Ｄ」評価に含まれますので、あるいは、廃止を検討するものと幾つかパターンがあります。そういったところで「Ｄ」評価をつけているです。","id":"exchange-020"},{"speaker":"筒井委員","kind":"質問・要望","question":"今のご答弁を伺いますと、私のイメージに違いがあったら、それは教えていただきたいのですけれども。所管評価が「Ａ」で、最終評価が「Ｃ」のものもあるのですけれども、そうした場合は、所管課との調整はどうやっているのか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"まず、こういった改善をする、課題を解決していく必要があるのではないかというところで「Ｃ」をつけるものはあるかと思います。","id":"exchange-021"},{"speaker":"筒井委員","kind":"質問・要望","question":"お答えにくいこともあるかと思いますけれども、引き続き、ぜひこの事務事業評価を進めていっていただきたいと存じます。区民向けにもっと広報を強化していっていただきたいのですけれども、その辺り、どうお考えか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"区民への見せ方やお示しの仕方については、時期、効果、そういったものもきちんと考えながら実施していきたいと考えています。","id":"exchange-022"}]},{"id":"topic-02","title":"人材育成に関すること","agenda":"人材育成に関すること","exchanges":[{"speaker":"あくつ委員","kind":"提案","question":"職員提案制度についてなのですけれども、今年度も何件か職員提案ということでプレス発表に載っています。提案事業が具体的な形で実現化される機会を設けることにより職員のやりがいや仕事に対してのモチベーションの向上を図るとの意見を述べました。","respondent":"田口人材育成担当課長、勝亦総務課長","answer":"それに対応しまして、基本的な中身の本質としては大きく変わっているものではないのですが、アプローチなどを変えております。これまでもクレーム対応研修は実施しておりましたが、組織力・連携力向上研修なども… 各所管で今年度実施しているもの、あくつ委員からご紹介いただいたカプセルトイですとか、そういったものを進めているところです。","id":"exchange-023"},{"speaker":"あくつ委員","kind":"質問","question":"どういった感想が聞かれるのか、それとも、そういう声はあまり聞かれないのか。そういったことについて、何か情報を把握しているものがあれば、説明を求めました。","respondent":"田口人材育成担当課長","answer":"まず、私が先ほどご説明したハードクレーム対応研修と組織力・連携力向上研修はこれから実施するものでして、新人を対象に実施した研修としましては。今年度末ぐらいに職員案内の冊子などは完成する予定です。","id":"exchange-024"},{"speaker":"あくつ委員","kind":"確認","question":"先ほど言及がありましたけれども、そういったところについての皆様のご感想というか、これは新人のみなのですか。私は、新人だけではなくて、そこも大事だと思っているのですけれども、そういったところを確認させてください。","respondent":"田口人材育成担当課長","answer":"そのほかの実施した研修につきましてですが、理論を学ぶという１日目の講義につきましては、全職員対象ということで実施をしております。これまでの取り組みなどを可視化していくというようなことと、職員ですとか、実際にそういうような課題もあって実施したものです。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"提案","question":"職員提案制度については、職員が提案したものであろうとなかろうと、総務課長のご答弁もありました。我々も議会の中で様々な提案をさせていただいて、採用されるものもあれば、採用されないものも当然あるとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"山本委員","kind":"確認","question":"Mission、Vision、Valueが職員一人一人の方にどの程度浸透しているかということを確認しておりますでしょうか。そして３つ目が、ＯＪＴやメンタリングなど、どのようなその後の支援体制が整っているでしょうかということで教えてほしいと求めました。","respondent":"田口人材育成担当課長","answer":"どれぐらい浸透しているかなども含めて測定をする予定がありますので、１年に一度、そのような測定の機会を考えております。研修で実施した内容をさらに実践するためのＯＪＴですとか、それぞれ研修を実施してございまして、その中で対応しています。","id":"exchange-027"},{"speaker":"山本委員","kind":"提案","question":"研修前後の状況についてもアンケート等でご確認いただいているというところで、確認ができてよかったですし、翌年度以降。職員提案制度については、制度のさらなる活性化のために、提案者に対して適切なフォローアップや支援を行うことを要望いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"新妻委員","kind":"提案","question":"それと最後に、３点目の職員提案制度についてです。９件全部が分からなくて教えていただきたいのですが、あと３件、実行されているのかというところを教えてほしいと求めました。","respondent":"田口人材育成担当課長、勝亦総務課長","answer":"採用２年目、３年目ですとか、人材育成・確保基本方針の内容について説明する機会を設けております。週に１回発行している庁内の広報の中でも、Valueの考え方について、毎週少しずつ説明をするということを行っております。それから、Ｚｏｏｍを活用した不妊・不育相談の実施ということで、こちらは８月から実施しています。","id":"exchange-029"},{"speaker":"新妻委員","kind":"提案","question":"職員提案制度につきましては、ありがとうございました。職員の方からの職務に根差したといいますか、そういうお声もたくさんあるかと思いますので、これも継続してぜひ行ってほしいと求めました。","respondent":"田口人材育成担当課長","answer":"私からは、研修について、今後の展望ということでお答えいたします。実施後のアンケートの結果を踏まえまして、心理的安全性は講演会という形で実施しましたが、また検討をこれから進めていくところです。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"私からは、まず、職員研修についてお伺いいたします。それはどこなのか、委託したならば、その辺りを説明を求めました。","respondent":"田口人材育成担当課長","answer":"では、私からは、基本方針をどのように策定したかということについてお答えいたします。昨年度、庁内にプロジェクトチームを公募で募集して結成しまして、その中で検討を重ねて生み出したものです。","id":"exchange-031"},{"speaker":"筒井委員","kind":"提案","question":"続いて、職員提案制度についてお伺いいたしますけれど、様々斬新なアイデアが出てきたかなと考えています。提案されている職員の方の年齢層、あと男女の比率とかを、分かれば説明を求めました。","respondent":"勝亦総務課長","answer":"やはり中堅以上の方、実務経験を積まれた方が多かったのかなという部分と、比較的若い方からの提案もいただいております。男女比につきましては、男性からのご提案が中心になっておりまして、ご提案いただいた方は、皆さん、男性職員からのご提案という形になってあります。","id":"exchange-032"},{"speaker":"筒井委員","kind":"提案","question":"もともと職員の比率とかもあるかと思うのですけれども、女性からのアイデアもぜひ積極的に取り入れていってほしいと求めました。この職員提案制度、非常によい制度だなと考えていますので、引き続きぜひとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"松永委員","kind":"提案","question":"もう１つ、賞状とか、何かそういったものはいただけるのでしょうか。その辺、２点についてお伺いしますとの意見を述べました。","respondent":"勝亦総務課長","answer":"もう１点、報奨ですとか表彰、そういったものは今のところは具体的には設定されてございません。モチベーション、そういったものが現状ではインセンティブになっているのかなというふうに考えております。","id":"exchange-034"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひとも文書だけでなく、直接その方とお話しする機会もあってもよいのかなというふうには思います。もう１つが、ぜひ賞状のようなものを取り入れていただきたいというふうに、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"のだて委員","kind":"提案","question":"答弁はなかったように思うのですが、その中身、どのようなことがやられたのかということを伺いたいと思います。職員提案制度のところでは、今年度５件が採用されたということで、どういった内容なのかというところを伺いたいと思いますとの意見を述べました。","respondent":"田口人材育成担当課長、勝亦総務課長","answer":"こちらは５日間にわたって実施した研修でございまして、それを持ち寄って、それに対する講評を受けるというような実践型の研修で実施いたしました。その後ろで残りの５名が聞いているという形で… ５件採用、来年度の実施に向けて、事業計画ですとか予算等を検討しています。まだ、事業計画、計画段階、予算要求作成段階ですので、具体的な内容については、予算等々が決まった後ということでご容赦いただければと思います。","id":"exchange-036"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ進めていっていただきたいというふうに思います。今もやられているかどうかも含めてお聞きしたいのですが、そういった文言が入っていない理由はどういうことなのか伺いたいと思います。","respondent":"田口人材育成担当課長","answer":"新任の研修でも実施しておりまして、あとは係長に昇任したときなども実施しておりますので、現在も行っているところです。全公務員が守らなければならないところであるというところは共通の認識として既にあるだろうというところで、現在のような形になったものです。","id":"exchange-037"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり一人一人の人権を守って、区民に寄り添う職員を育成していっていただきたいなというふうに思うのですけれども、いかがでしょうか。それを伸ばしていけるように、人材育成を強化していくということでやっていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"田口人材育成担当課長","answer":"先ほどの質問で回答が漏れており、申し訳ございません。進めている中で、より進めていけるように、体制を整えているところです。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問・要望","question":"その点を区はどう考えているかということも伺いたいのですけれども、実際に採用した人数が分かれば伺いたいのですけれども、様々な業務で。何か実施されたことがあって、効果などが出ているところがありましたら、伺いたいと思います。","respondent":"田口人材育成担当課長","answer":"ホームページの見直しですとか、採用案内の見直しを進めているところですので、１２月ぐらいには採用案内なども完成する予定です。専門職なども２０名ちょっと集まって実施をしているものですので、いろいろな層の職種の職員が集まって、６回に分けて実施をしておりますので。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問・要望","question":"あると思いますので、そうした中で獲得していけていないということも１つの要因としてあると思うのですけれども、この点を伺いたいと思います。そして、専門性をしっかり生かせるように、支援もしながら育成をしていっていただきたいということを、これは要望しておきたいと思います。","respondent":"田口人材育成担当課長","answer":"先ほどの初任給という部分につきましては、人事委員会などで行っていることです。私の人材育成というところとは少し異なりますが、そのようなご意見ということで承って持ち帰りたいと考えています。","id":"exchange-040"},{"speaker":"せらく委員","kind":"質問","question":"職員のもともと持っている個性だったり、強みを伸ばすというか、そういったところはどういうふうにやっているかということをお聞きしたいです。例えば、診断ツールを使うなど、もしありましたら、説明を求めました。","respondent":"田口人材育成担当課長","answer":"ただいまの職員の能力向上に関係して、強みなどをどのように把握しているかですが、診断ツールというものは、現在、使用はしていないところです。採用４年目にやる研修などでは、班で一緒に意見交換をしながら、そのような中で自分の強みを振り返れるようにしています。","id":"exchange-041"},{"speaker":"せらく委員","kind":"提案","question":"やはりそういった上司がどういうふうにコミュニケーションをとったら、提案というか、お話をさせていただきました。もしご所感を伺えればと思いますとの意見を述べました。","respondent":"田口人材育成担当課長","answer":"ただいまの診断ツールの件について、貴重なご意見ありがとうあります。先ほどご説明したカオナビ上でも似たような性格診断ツールなども用意がありまして、品川区の導入については慎重に考えていきたいと考えています。","id":"exchange-042"},{"speaker":"つる委員","kind":"提案","question":"先に、職員提案制度なのですが、もともと品川区は、２０１７年から職員提案制度があったのです。これまでのものと、今やっているものの大きな違いはどういうところなのか尋ねました。","respondent":"勝亦総務課長","answer":"関係する所管の部長等々の前でプレゼンを行い、そこで判断をしていくというような形は、新しい形としてやっているのかなというふうに考えております。","id":"exchange-043"},{"speaker":"つる委員","kind":"提案","question":"６月のこの委員会でも新妻委員から確認があって、たしか延長したのですよね、次年度に向けてということで。それぞれの提案してきている事業は、そもそもそんな何億円とかという提案じゃないんだよね」と、その辺はどういう仕組みになっているか尋ねました。","respondent":"勝亦総務課長","answer":"具体的には設定をしておりませんで、ご提案いただいた事業の中でも、金額の小さいものから大きなものまで様々あります。具体的には、予算枠等は設定していないような状況です。","id":"exchange-044"},{"speaker":"つる委員","kind":"提案","question":"私もいろいろな委員会のときに確認させていただいて、自ら処していかなければいけないところがあるわけですから、育てる側というか。それは同じ空間のテーブルのところにいるわけですから、今のどうだったのではないかな、やはりチームがあったのですよねとの意見を述べました。","respondent":"田口人材育成担当課長","answer":"研修で実施しているのは、丸１日かけて、区職員としての接遇の在り方についてロールプレイを交えて行っているところです。あまりよくない対応をした場合は、意見をもらって変えていくというような、そのようなやり方で改善を図れないかというところで進めてあります。","id":"exchange-045"},{"speaker":"つる委員","kind":"質問・要望","question":"無表情で、こちらが挨拶をしていく、廊下で擦れ違うのだったらよいではないですか。表情が変わったな、生き生きとしているな、もちろん職員のＥＳも上がったなというような形でぜひ進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"西村委員","kind":"提案","question":"職員提案制度なのですけれども、これもご提案というか、お考えをお聞かせほしいと求めました。提案を出すことで職員のやりがいですとかモチベーションにつなげるためにも、現在どのように運用しているのかも併せて伺えればと思いますとの意見を述べました。","respondent":"田口人材育成担当課長、勝亦総務課長","answer":"ただいまの委員のハードクレーム対応研修における組織的な対応という部分についてお答えいたします。クレームを対応するときには、そのような後方支援を行えるようにするという形で… こういった施策を進めていく中で、軌道修正をしたり、様々工夫をしていくものは例年必要かなというふうに考えてあります。人事課で、一定程度、ご自身の関心のある業務分野に異動を希望していくというものは制度としてはあります。","id":"exchange-047"},{"speaker":"西村委員","kind":"提案","question":"ハードクレームに関しては、職員の皆様を守る観点からも、ぜひとも全庁的な取組としてお願いしたいと思います。提案もどんどん上がってくると思いますので、提案した職員の方が何かしらの形で関われるような体制をぜひともご検討ほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"}]},{"id":"topic-03","title":"旧荏原第四中学校整備基本計画に係る検討状況","agenda":"旧荏原第四中学校整備基本計画に係る検討状況","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"この時期が同じぐらいの１０月１２日辺りでやられるのかということを伺いたいと思います。教室型の説明会も、理解を深めるという意味でもぜひやっていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"高校生向けのものを１回、大学生向けのものを１回ということで、計３回実施する予定です。パブコメの前の次期のオープンハウス説明会についてですけれども、見に来ていただいた方に説明する手法というところで、検討しています。","id":"exchange-049"},{"speaker":"のだて委員","kind":"質問・要望","question":"教室型の説明会、実施をしていただきたいと思うのですけれども、改めて伺います。","respondent":"吉岡政策推進担当課長","answer":"オープンハウス方式の説明会、年明けの３月には住民説明会ということで、このような形で進めていきたいというふうに考えてあります。","id":"exchange-050"},{"speaker":"あくつ委員","kind":"質問・要望","question":"経過の報告、ありがとうあります。そのたびにいろいろ要望とかを出させていただいているのですけれども、この先進的な大型複合施設というのは、どこを指しているのか説明を求めました。","respondent":"吉岡政策推進担当課長","answer":"１つご紹介をしますと、視察に行ってまいりましたが、広島県の廿日市市にあります「まるくる大野」という施設があります。品川区が進めていくような施設の考え方と一致するようなところがあるのかなということで、庁内検討会のほうでも共有を図らせていただいたところです。","id":"exchange-051"},{"speaker":"あくつ委員","kind":"質問","question":"いずれも図書館機能を中心にという施設になっております。ここについては、やはりそういう図書館機能を備えるという方向性で、庁内検討が進んでいるという認識でよろしいのか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"そういったものが少ないというよりは、一定程度ご用意するというところを鑑みますと、図書館機能というようなところになろうかと思います。図書館がありますので、そういった施設の在り方については、併せて考えていく必要があろうかというふうに認識しております。","id":"exchange-052"},{"speaker":"あくつ委員","kind":"意見","question":"近くの近隣施設の図書館は、私、個人的に利用させていただいているので、今後、在り方を検討していく中で、そういったものが統廃合されていくのは少し寂しいなという気持ちはありますけれども、そういったものも含めて、これから検討が進むのかなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"},{"speaker":"山本委員","kind":"質問","question":"私から、１点、質問させてください。これはどのような工法を比較検討したのかということと、また、どのような意見や議論があったのかということをお教えください。","respondent":"吉岡政策推進担当課長","answer":"そういった様々な考え方がありますので、そういったものを検討会内で共有を、こういった手法があるということで共有させていただいたです。検討会では、様々な情報を共有する中で、委員会内でしっかりとした整備内容を案として出していけたらなと考えているところです。","id":"exchange-054"},{"speaker":"山本委員","kind":"質問・要望","question":"状況について理解いたしました。いろいろと知っていただいた上でご検討いただきたいということと、検討状況を知っていただいて、しっかりと検討を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"あくつ委員","kind":"質問","question":"事例としているところが３か所、その全てが図書館機能を中心として居場所づくりをしているというところが紹介されていた。これは１つの事業者に、１つの事業者にお任せするということなのか、現段階での検討状況を説明を求めました。","respondent":"吉岡政策推進担当課長","answer":"こちらについては、委員からもお話のとおり、検討中というところなので、何か決まっているというところではございません。会社を設立していただいて、そういった幅広い手法の検討を進めていきたいというふうに考えているところです。","id":"exchange-056"},{"speaker":"あくつ委員","kind":"質問","question":"ありがとうございました。参考にお伺いしたいのですが、どういう形で運営をされていたのか、参考に説明を求めました。","respondent":"吉岡政策推進担当課長","answer":"こちらの「まるくる大野」については、ＰＦＩ事業でというところで、ＳＰＣに近い形でそういった様々な事業者を１つの事業者が束ねて運営をしているというような手法で運用しております。","id":"exchange-057"},{"speaker":"新妻委員","kind":"質問・要望","question":"それともう１点が、主な意見の中で、屋内で子どもが遊べるスペースというご要望が上がっております。この屋内で子どもが遊べる施設というのは、この屋内運動場とは別に検討がされているのかどうか、まずそこを確認させてほしいと求めました。","respondent":"吉岡政策推進担当課長","answer":"庁内検討会の中で出てきた子どもが遊べるような屋内スペースですけれども、出てきた意見でいうと、屋内運動場とはまた別のところで出てきた意見です。いわゆるプレイルームというような表現が正しいのでしょうか、そういったことで出てきた意見です。","id":"exchange-058"},{"speaker":"新妻委員","kind":"質問・要望","question":"この全天候型の子どもが遊べる施設というか、そういうところがすごくこれから求められてくるのではないかなと思っています。であれば、少しでも広く、そういう視点が反映されていけるのかどうかというところをお答えほしいと求めました。","respondent":"吉岡政策推進担当課長","answer":"子どもたち、あるいは子育て世代の方が集える施設が必要だという意見の中で、こういった屋内スペースも必要なのではないかと意見が出たところです。主な整備予定機能というところで、面積の余剰があれば、こちらもしっかりと検討を進めていきたいというふうに思ってあります。","id":"exchange-059"},{"speaker":"つる委員","kind":"提案","question":"会派としても、いろいろ提案とかもあったかと思います。品川区では、例えば、多世代交流施設とかいろいろな施設があるわけですけれども、新たな施設という、そういうカテゴリーになるということか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"この施設の検討の経緯からも含めましても、交流拠点という形になりますので、今までの多世代交流、いわゆる「ゆうゆう」とか、そういったものではなくて、新しい施設になるというふうに捉えているところです。","id":"exchange-060"},{"speaker":"つる委員","kind":"提案","question":"先ほど、新妻委員からもあったように、屋内遊戯場とか、この十数年の中でもいろいろな意見とか提案があったと思います。委員会の資料などで確認すると、このエリアには、戸越公園や、それから文庫の森、エコルとごしがあって、回遊性をとあるのですとの意見を述べました。","respondent":"吉岡政策推進担当課長","answer":"あるいは広場、そういった空間のところで、面積的にはそこで使っていくような形になるのだろうなというふうに思っています。来やすい工夫、そういったものについては、しっかりと検討していきたいというふうに考えております。","id":"exchange-061"},{"speaker":"つる委員","kind":"質問・要望","question":"こうしたアクセスや設備についても、引き続き、地域の皆さんの声を第一としながらやってほしいと求めました。車両動線というのか、そこの辺りについては、どういう経緯なのか説明を求めました。","respondent":"吉岡政策推進担当課長","answer":"やはり蔵書の関係のところで、施設内から駐車場への動線のアクセスのよさ、こういったものは求められてくるのだろうなというふうに思っています。体育館以外のスペースについても、そういった災害時に転用できる、こういった考え方で整備に取り組んでいるというようなところです。","id":"exchange-062"},{"speaker":"つる委員","kind":"意見","question":"２６号線の１本で行けるので、いろいろなアクセスという部分では、スローモビリティとかいろいろありますよね。いろいろな形でここが生かされるように、サードプレイスというところもそうです、ぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"筒井委員","kind":"質問","question":"それは区民の公募で、どういうふうに募集していくのか。その辺り、現時点でどのように検討されているのかをお聞きしたいと思います。","respondent":"吉岡政策推進担当課長","answer":"地域の方、品川区の区民の皆様に愛される名称というのは非常に重要だというふうに考えておりますけれども、こういった具体的なやり方については、これからまた検討していくような内容です。","id":"exchange-064"},{"speaker":"筒井委員","kind":"質問・要望","question":"活用方針の２６ページとかを見ると、図書館の位置が、これは避難所になるのですか。広大な避難スペースにしていくのか、どのようにしていくのか、これも現時点で分かる範囲で説明を求めました。","respondent":"吉岡政策推進担当課長","answer":"区民交流スペース、多目的ホールスペース、こういったところは比較的被災時に避難所に転用できるのかなというところで考えているところです。そういったスペースはしっかりと見つけて、区民避難所として機能できるように、しっかりと検討していくです。","id":"exchange-065"},{"speaker":"のだて委員","kind":"質問","question":"そして、この標準化、１８業務されていくということですけれども、これまで整理して、それぞれ変更になる部分はあるのかどうか伺いたいと思います。どの程度発生しているのか、現状で金額が出せるところがあれば、伺いたいと思います。","respondent":"横田デジタル推進課長","answer":"では、細かいところで申し上げますと、ＥＵＣ（エンド・ユーザー・コンピューティング）の機能の仕様などが変更になったというところになります。令和５年度は６億円程度になっておりまして、令和７年度以降は、未定という扱いになります。","id":"exchange-066"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、大体三十二、三億円かかってきたということでいいのかというところも確認させていただきたいのですが。全て国が負担するということになっているのかどうかというところも確認させていただきたいのですが、その変更にもしなって、いかがか尋ねました。","respondent":"横田デジタル推進課長","answer":"システム標準化事業で品川区に入る補助金の予定が、約２５億円になりまして、１００％には大きく満たないという状況になります。いわゆるベンダーロックインが解消されて価格競争が発生するですとか、そういった形でメリットが出てくるということが考えられております。","id":"exchange-067"},{"speaker":"のだて委員","kind":"質問","question":"６０秒で完了するということはかけ離れているなというふうに思うのですけれども、６０秒で手続完了するようになるのかどうか伺いたいと思います。民間が関わってくることで、そのデータが民間に集積されて、そうした危険性はないのかどうかというところも伺いたいと思います。","respondent":"横田デジタル推進課長","answer":"高齢者地域支援課の範疇になってしまうのですが、スマホ教室などの実施によりまして、誰一人取り残されないという側面から支援を行う一方で。両輪にいたしまして、引き続き、ＤＸに邁進してまいりたいと考えております。","id":"exchange-068"},{"speaker":"のだて委員","kind":"質問・要望","question":"推定６０億円ぐらいかかるという中で、２５億円しか国からもお金が出てこないということでやっていくということもおかしな制度だと思いますので、標準化はやめるべきだということは述べておきたいと思います。","respondent":"横田デジタル推進課長","answer":"システム標準化につきましては、システム標準化法に基づいて進めておりますので、法令にのっとりまして着実に進めてまいりたいと考えております。","id":"exchange-069"},{"speaker":"筒井委員","kind":"質問","question":"ほかの特別区も同じような状況なのか、また、国の補助金２５億円というのは、さらに追加して国からもらえるということはないのでしょうか。その３点、お伺いいたしたいと思います。","respondent":"横田デジタル推進課長","answer":"その分、コストは安くなっているというところがありますので、他の区はもう少し厳しいのかなというふうに考えております。追加の補助金はない予定ですが、東京都とほかの自治体と組んで、国にさらなる補助金を要求しています。","id":"exchange-070"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひ国に対して要求をしていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/118715?Template=document&Id=6835#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":60502,"voices":159}},{"id":"r06-20240927-19","meetingId":"r06-cm09","date":"2024年9月27日","dateIso":"2024-09-27","committee":"災害・環境対策特別委員会","time":"午前１０時００分～午後 ０時００分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件整理しています。","topics":[{"id":"topic-01","title":"エコルフェス－２０２４ ＡＵＴＵＭＮ－の開催","agenda":"エコルフェス－２０２４ ＡＵＴＵＭＮ－の開催","exchanges":[{"speaker":"まつざわ委員","kind":"意見","question":"１点だけ、何かいつも青稜かなという勝手なイメージがあるのですが、そこら辺の何か説明があればとの意見を述べました。","respondent":"中西環境課長","answer":"エコルとごし、それから環境課としましても、様々な学校とつながれればと思ってあります。学生さんとうまく連携できたらと思ってありますので、引き続きそういった枠の拡大というものは考えてまいりたいと考えています。","id":"exchange-001"},{"speaker":"吉田委員","kind":"質問","question":"４月に行われたエコルフェスにも参加させていただいて、すごく人気があったのですが、そのような場もあると考えてよろしいか尋ねました。","respondent":"中西環境課長","answer":"今回も、「無垢の積み木で遊ぼう！」というコーナーで同様に、たしか多目的室だったと思うのですが、紙製人工芝を敷設させてただいて、木材に触れるというブースは設ける予定です。","id":"exchange-002"},{"speaker":"吉田委員","kind":"意見","question":"すごくうれしかったのですが、引き続き、環境の視点で言うとそういうイベントも行われるということでよろしいですよねとの意見を述べました。","respondent":"中西環境課長","answer":"今お話のございました紙製人工芝ですが、なかなか業者とお話をしましても、まだ外での利用というのは相当難しいというお話を聞いてあります。私どもとしても非常にいい素材であると思ってありますので、今後も展開については検討してまいりたいと思ってあります。","id":"exchange-003"}]},{"id":"topic-02","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"まつざわ委員","kind":"質問・要望","question":"区がどういうふうに情報を発信しているのかというのを教えていただきたいのが１点と、平時からの顔が見える関係の構築、これも十分分かっております。何というのですか、共助でも難しいという中で、区がどこまで中に介入できるのかなというのが２点目。","respondent":"羽鳥防災体制整備担当課長、平原防災課長","answer":"私からは、最初のご質問にありました区からの情報発信についてご回答します。台風につきましては、３日ほど前から区の中でも体制を取りまして方針を決定し、状況によっては自主避難施設の開設などを検討した上で。ただ、具体的にどのように活用するのかについては課題があると認識しているところは、個別に相談いただきながら進めさせていただいているところです。","id":"exchange-004"},{"speaker":"まつざわ委員","kind":"確認","question":"感覚を教えてほしいのと、情報拠点の中で安否確認というのはいろいろやりますけれども、情報の確認というのですかね。何というのですか、そういう訓練というのは全くないので、例えばそういう現状を区が把握しているのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"その部分は、もっと町会と密に連携していただきたいと。最後に確認したいのですが、５の在宅避難者の把握、それだけ最後に説明を求めました。","respondent":"平原防災課長","answer":"結論から申し上げますと、ものとしては別ですが、ただし別々で運用するのではなくて、別のシステムをこのポータルサイト・アプリに連動させていくような形で、運用としては一本の運用でできるように、今現在検討しています。","id":"exchange-006"},{"speaker":"まつざわ委員","kind":"質問","question":"ああいうやつですか。ああいうものがあって、それにこうやって新しいものが入ってくると。","respondent":"平原防災課長","answer":"ＳＮＳアプリのＬＩＮＥなどを活用できたらと考えていますし、これはまだ国段階で検討中ですが、マイナポータルなどの連動も考えているところです。そういういろいろなところから入ってきた情報を、最終的にはこのスマホアプリで情報集約できればと、今、構築を検討しています。","id":"exchange-007"},{"speaker":"ひがし委員","kind":"質問・要望","question":"やはり自治体が発信する情報は正しくて、区民の方々の安心感にもつながるし、混乱も避けることができるというお話をいただきました。ただ、ぜひそういうところも注視しながら進めていただきたいなと思うのですが、分かる範囲でいいので教えてほしいと求めました。","respondent":"平原防災課長","answer":"障害をお持ちの方に、どう障害特性に応じた形でそこを届けるかというところの検討は、現在はまだそこまでは入ってございません。やはり情報を一番届けなければならない方、引き続き重要な課題だと考えていますので、そこは並行しながら考えていきたいと考えています。","id":"exchange-008"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ご高齢の方々も分かりやすいデザインがいいというお声だったり、障害にも適用されているようなものがいいだったり、多言語化がというご要望もいただいていますので、ぜひ、重要だとおっしゃっていただきましたので、引き続き取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"塚本委員","kind":"質問","question":"２番の避難所開設・運営のところから、結構大きな変更かなと思うのです、当初の避難所の在り方からすると。そういうところを今現在どう進めているのかと、今後、どういうふうに進めているのかということを最初にお伺いしたいと思います。","respondent":"平原防災課長","answer":"以前の委員会でも出ましたが避難行動要支援者の安否確認、弁護士３会との間で協定を締結させていただきまして、学校にお願いしています。極力何か負担が増えるということがないように、公助の支援という形を充実させていければと、今検討を進めさせていただいているところです。","id":"exchange-010"},{"speaker":"塚本委員","kind":"質問・要望","question":"建前としてのお話は承っているということは承知しているみたいですが、では現実問題どうするか。そういうことも含めて、やはり重々支援をしていっていただきたいなとも思いますが、改めてご答弁をお願いします。","respondent":"平原防災課長","answer":"公助の支援ですが、これまでも委員会にてご説明させていただきましたけれども、この場合の支援というのは２種類あるかなと思ってあります。体制をしっかり考えて準備しておくという意味での支援、それから災害時の対応、両面を考えながら対応してまいりたいと考えています。","id":"exchange-011"},{"speaker":"塚本委員","kind":"質問・要望","question":"際限なくいろいろな要望というか、前もって備えられる部分と、いざ発災時に発生してくる様々な現場での対応というところにどこまで対応できるかと。どれぐらい今、設置が進んでいるのかというのが、ある程度分かれば教えていただきたいのですが、今の配布の状況というのはどんな感じか尋ねました。","respondent":"平原防災課長","answer":"エレベーター用防災チェアですけれども、現在、まだお話をいただいて最終的に詰めている段階で、具体的な数としてはまだ発生してございませんが、引き合いといいましょうか、お声は結構多数いただいているところです。","id":"exchange-012"},{"speaker":"塚本委員","kind":"質問・要望","question":"これは以前にも少し質問で取り上げたことがあるのですが、閉じ込めが起こったときに、なかなかすぐには来てもらえない。求められているマンションがあれば、希望に応じて講習みたいなことをやっていただく、こういうことについてはどのようにお考えか尋ねました。","respondent":"平原防災課長","answer":"最後の手段としてという考えで、あるいは、住民の皆様で平素から考えていただくことが大事かなと思います。状況のご理解を進めていただくのが大事かなと思いますので、申し訳ございませんが、逆に対応しないほうがいいのかなとは考えてあります。","id":"exchange-013"},{"speaker":"塚本委員","kind":"意見","question":"分かりました。特にエレベーターのことについてのいろいろな対策も考えていらっしゃるということは分かりましたので、今後ともよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"えのした委員","kind":"質問","question":"場所がないマンションというのが大きい、小さい、あると思うのです。煙体験、１階のホールなどでもできるかとは思うのですが、そういうことというのはお考えがあるのかどうかというのを聞かせ願えますか尋ねました。","respondent":"平原防災課長","answer":"そういうところを使わせていただくことが多うありますが、もしないようでしたら、そういうところは柔軟に対応させていただければと思ってあります。","id":"exchange-015"},{"speaker":"えのした委員","kind":"質問","question":"本当に防災体験館などを活用していただければいいなとは思っているのですが、まだこれからの取組なので、応募というのは来ているか、状況は分かりませんが、もしそういうお声があれば、どのぐらいご連絡が来ているかというのをお知らせ願えますか尋ねました。","respondent":"平原防災課長","answer":"区内３,２００棟を対象としていますが、今でいくと１０階以上のマンションの、実はそういうところが中心となっています。ただ、あるいは訓練まで行くというのが１０件以上の単位でやらせていただいておりますので、そういう対策を進めさせていただければと思ってあります。","id":"exchange-016"},{"speaker":"鈴木委員","kind":"質問","question":"そして、ここの１ページのところにも、これは区としても在宅避難者用の備蓄をされているということなのでしょうか。どんなものをどういうふうに備蓄しているのか、在宅避難者のための備蓄についての区としての考え方と実際を教えていただけたらと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"物資についてのご質問ですので、私から回答します。災害時に関しましては、想定を上回る在宅避難の方から要求があった場合には、そういう物資を提供していくという形で考えているところです。","id":"exchange-017"},{"speaker":"鈴木委員","kind":"質問","question":"その８万７,０００人という本来であれば避難所に来る人が、在宅避難という考え方なのでしょうか。でも、８万７,０００人は避難所に来て、その在宅避難の方の分というのはどれぐらいの備蓄ということで想定されているのかを伺いたいなと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"７日間を過ぎますと、国などから支援物資がプル型で届いてまいりますし、４日目以降であればプッシュ型でも支援物資というのは届いてまいります。","id":"exchange-018"},{"speaker":"鈴木委員","kind":"質問","question":"そのときに、多分今度、しながわ防災ハンドブックが携帯用のトイレと一緒に配られるということになりますよね。その点も伺いたいのと、それも委員会でもご報告いただけたらなと思うのですが、その点も伺います。","respondent":"平原防災課長","answer":"その中にローリングストックの考え方、日常食べているような非冷蔵性のもの、一般的な缶詰類とかレトルト食品みたいなものを推奨するものです。準備ができましたら、区議会の皆様にもぜひご覧いただくような形を取らせていただければと、現在検討させていただいているところです。","id":"exchange-019"},{"speaker":"鈴木委員","kind":"質問・要望","question":"２ページのところの、それぞれ立てられていると思うのですが、そこの人数というのがもし分かったら教えてほしいと求めました。割と避難所に避難する方は、どんな方が支援者になっているのかなと常々思っているのですが、その点も分かったら教えてほしいと求めました。","respondent":"平原防災課長","answer":"避難行動要支援者の個別避難計画における人数については、現在７,０００件レベルか、今年度もさらに進めていると聞いてあります。ですので、福祉的にどのようなところを受入れ施設として用意していくのかというのは、また併せて私どもでも検討させていただいているところです。","id":"exchange-020"},{"speaker":"鈴木委員","kind":"質問","question":"具体的に伺っているのですが、どうしたらいいのだろうという声をいただいているのですが、その点を伺いたいと思います。個別避難計画をどうするかとか新たに出てきている部分も、これを見直して改訂版をつくる計画はあるのか、その点についても説明を求めました。","respondent":"平原防災課長、滝澤災害対策担当部長","answer":"現在、私ども防災課では考えてありますので、行く行くはきちんと割り当てられるようなところが計画の完成形だと認識しております。まず、避難行動要支援者一人一人についての先ほど言いました個別避難計画については… 実は福祉部とはもう４年にわたり、災害対応検討委員会というのを立ち上げまして、今ずっと検討を進めているところです。","id":"exchange-021"},{"speaker":"鈴木委員","kind":"質問","question":"その計画を立てるに当たっても障害者の方々のご意見を伺っていただいて、そういう声を聞いていただいて、その点を伺いたいと思います。この品川区の要配慮者支援の計画については、来年度中には出来上がるみたいなスケジュール感で考えていいのか、その点も説明を求めました。","respondent":"平原防災課長","answer":"避難行動要支援者の全体計画につきましては、今年度中に改訂いたします。というよりも、もう作業としてはほぼ完了状態という段階です。","id":"exchange-022"},{"speaker":"鈴木委員","kind":"質問・要望","question":"障害者の、当事者の声もぜひ聞いていただきたいなと思うのですが、その点はいかがか尋ねました。","respondent":"平原防災課長","answer":"今お話ししましたとおり、計画そのものという形ではもうほぼ作業が終了しておりますので、今後、実際にそこを運用していく中で、いろいろなお声を聞ければと考えていますので、そういうところはしっかりやらせていただければと思ってあります。","id":"exchange-023"},{"speaker":"鈴木委員","kind":"質問・要望","question":"多分その計画も、何というのですかね、見直して、またよりいいものにというところにもなっていくかと思いますので、そういうところどころでぜひ当事者の声も入れていただきたいということで、要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"確認をさせていただきたいのが、親があって子局がありますよね。子局が今４０４あって、屋外の子局が１５５局だと思うのですけれども、それでよろしいのか、確認をさせてください。","respondent":"羽鳥防災体制整備担当課長","answer":"防災行政無線の件につきましてなので、私から回答します。数に関しては委員のおっしゃるとおりです。","id":"exchange-025"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"１人で暮らしている方で、地域によって聞こえる、聞こえないというのが結構私の地域でもお声があります。そういういろいろなお声があると思うのですけれども、その辺についてどういう声があるのか、お聞かせほしいと求めました。","respondent":"羽鳥防災体制整備担当課長","answer":"そういうお声をいただいた際は、職員が現地にきちんと出向いて、状況を確認して、音量の調整ですとか、あとラッパの方向の修正などは検討しています。そういう聞こえづらいというお声がありますので、様々な形で対応しています。","id":"exchange-026"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"どうもありがとうあります。アナウンスの仕方を含めて、今後も含めてやってほしいと求めましたので、これは要望として。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"こんの委員","kind":"質問","question":"医療品、医薬品、こうした面についてはどういうふうにお考えでしょうかというところが１点気になっているところです。この医療面、生活での体調不良に関する在宅避難の方への支援というのはどんなふうにお考えなのか、説明を求めました。","respondent":"平原防災課長","answer":"後ほどご説明しますが、どのぐらいの分量かというところを、ぜひ考えていただくきっかけにしていただければと思います。そういうところはいろいろパターンとして考えられるかなと思いますけれども、平素からの備えをもっと私どもも強化してまいりたいと考えています。","id":"exchange-028"},{"speaker":"こんの委員","kind":"質問","question":"避難所の体制として関わることが増えていくのではないですかということもそうですが、そういう相談体制ということが必要ではないかと思うところです。在宅避難を推奨するならば、そうしたところもきちんと体制を整えておかないといけないのかなという思いなので、その辺についてはいかがか尋ねました。","respondent":"平原防災課長","answer":"超急性期を過ぎた次の段階から、こちらは避難所の運営とは全く別組織で運営する形になりまして、区内１３か所を指定しています。それから、その中からさらにＤＭＡＴ等の支援をいただきながら広げていくような形になろうかと思いますので、そういう体制の中で。","id":"exchange-029"},{"speaker":"こんの委員","kind":"質問","question":"何でしょうかね、どう説明したらいいのでしょうかね、そうしたものも考えとして持って体制をつくっておくことが必要かなと。できますよということですけれども、どうかお願いしたいと思いますが、いま一度ご答弁をいただけますか尋ねました。","respondent":"平原防災課長","answer":"改めて再検証を進めていると聞いてありますので、またそういうところとも連携しながら、つなげてまいりたいと考えています。避難所避難のところでご説明させていただきましたが、そういうところは私どもも柔軟に対応してまいりたいと考えていますので。","id":"exchange-030"},{"speaker":"こんの委員","kind":"質問・要望","question":"何かの助けを求めたいというときに、助けを求められる体制がいつでもこうしてありますよ、そうした意味も含めて。そうしたところの健康状況というのでしょうか、何かもう一つお考えであれば、そのお考えをお聞かせほしいと求めました。","respondent":"平原防災課長","answer":"すみません、検討段階ですが、そういう方向で考えてあります。一律に考えて、あるいはどこにいるのかも把握されていないと、そういうことにならないようにはしっかりと対応させていただきたいと思います。","id":"exchange-031"},{"speaker":"こんの委員","kind":"質問","question":"在宅避難を推奨していくからには、その在宅の方々の支援策の体制をきちんと取っておくことが大事だというところで、質問をさせていただきました。個々に備蓄なり取っていただきますが、そこを可能とするような公助の体制の整備を、これからもお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"須貝委員","kind":"質問・要望","question":"これは何年か前に質問したことがあったと思うのですが、自動的につく装置というのは、区は考えられているのでしょうか。だから、これを何とか早くできるような方策を私は考えていただきたいと思うのですが、その辺はいかがか尋ねました。","respondent":"溝口防災まちづくり部長、平原防災課長","answer":"区内全域で３２８キロメートルぐらい、皆さん、どういう形で避難されるのか分からないので対応していかなければいけないところもありますので。少なくとも避難する場所とか目的になる場所、広域避難場所についても… 先ほどもございましたが、そういうところについて、やれる範囲のところをしっかりとご支援させていただければと思います。","id":"exchange-033"},{"speaker":"須貝委員","kind":"質問・要望","question":"災害に対してどう対応しようかということを考えられていくし、１０年前までずっとそういうふうに我々、地域でも発信していました。どうしても家から離れられない人もいらっしゃるし、そういう意味で、ぜひ今後も普及啓発に私は頑張って推進してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"ゆきた副委員長","kind":"確認","question":"聞きながら、自助の取組の啓発、あとマンション居住者と地域住民との間の共助の啓発について、区として進められているのを確認させていただきました。もちろん所管が違い環境課になると思うのですが、所管を超えての連携での在宅避難対策として、区のお考えがあればお聞きできればと思います。","respondent":"平原防災課長","answer":"災害対策を進める上では、電気以外にも、先ほど須貝委員からもご指摘がございましたとおり、様々な部門と連携していかなければならないことも多うありますので、当然そういうところにつきましても、環境課と連携させていただきながら進めさせていただければと考えています。","id":"exchange-035"},{"speaker":"ゆきた副委員長","kind":"確認","question":"私も確認させていただきまして、「クーラーが使えないことを想定し、夏場は冷却シートを準備する」とは記載されています。所管を超えて区民に有益な情報を提供して、より一層周知してほしいと求めましたが、改めてお考えをお聞きできればと思います。","respondent":"平原防災課長","answer":"あるいは東京都の部局によっては町会・自治会という形で客体が異なっておりますけれども、そういう必要とされる方のところにきちんと届きますように、しっかりと発信はしてまいりたいと考えています。","id":"exchange-036"}]},{"id":"topic-03","title":"携帯トイレ全区民配布","agenda":"携帯トイレ全区民配布","exchanges":[{"speaker":"こんの委員","kind":"質問・要望","question":"赤ちゃんの分も配布があるのですかというご質問いただいているので、その点はどうなっているのか、まず確認します。２点目が、時間帯をもう１回確認させていただきたいのと、コールセンターは何台体制でいくのかも確認をさせてください。","respondent":"平原防災課長","answer":"それ以外の時間帯はＡＩのオペレーターが対応するということと、メールでの対応も受け付けてありますので、そういうところのご案内もする予定です。配布の考え方ですが、配送事業者の配送計画ではこれが一番合理的だということで、そういう中でこの形になっていったところです。","id":"exchange-037"},{"speaker":"こんの委員","kind":"質問・要望","question":"３人の体制をしてくださるということですが、そうしたことへの対応も加味しての体制を取られているのかを確認させてほしいと求めました。その辺が少し懸念されるところで、それにまつわる防災の関連の質問だったりを聞いてくることがあると思うので、いかがか尋ねました。","respondent":"平原防災課長","answer":"この事業内容についてはしっかりお答えしますが、当然そこで全ての区の事業についてお答えするような委託は考えてございません。しっかり私どもで対応させていただければと考えています。","id":"exchange-038"},{"speaker":"こんの委員","kind":"質問","question":"質問内容が多岐にわたってそれが掘り下げられた質問になってくると、答えられないという状況もあると思いますので、そこは柔軟に対応をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/949666?Template=document&Id=6837#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":41171,"voices":106}},{"id":"r06-20241002-4","meetingId":"r06-c-settlement","date":"2024年10月2日","dateIso":"2024-10-02","committee":"決算特別委員会","time":"午前 ９時３０分～午後 ５時２５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を165件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"澤田副委員長","kind":"質問","question":"１人当たりの質問時間は、２０分のいずれかとし、答弁時間も含めて１日につき１０分となります。残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"田中委員","kind":"質問・要望","question":"その間、「民生費は幾らですか」という、それは特に総括の中ではそぐわないのでやめなさいということで申し合わせ確認事項に記載されていると。１つの質問をして答弁を求めて、本会議の在り方自体もそういう方向で変えていくべきだという、一般的な全国的な風潮があると思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]},{"id":"topic-02","title":"以上で、決算統計上の数値および、財政健全化法に基づく各指標についての説明が終わりました。 それでは、令和５年度品川区一般会計歳入歳出決算","agenda":"以上で、決算統計上の数値および、財政健全化法に基づく各指標についての説明が終わりました。 それでは、令和５年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"西村委員","kind":"質問","question":"は１６９ページ、学校改築から、プールについてお伺いしてまいりたいと思います。少なくとも年１０時間の水泳授業の機会を担保していく取組をお願いしたく、様々プールの課題は顕在化しておりますので、伺ってまいりたいと思います。","respondent":"荒木学校施設担当課長","answer":"現状、屋内温水プールが５校、開閉屋根式のプールが設計中の改築を含めて４校、それ以外は屋外プールです。最大想定クラス数がおおむね３０学級以上となる場合は、授業を効率的に回せるよう、開閉屋根式プールを選択しています。","id":"exchange-003"},{"speaker":"西村委員","kind":"質問・要望","question":"昨年の一般質問で、まつざわ議員から質問いたしましたが、改築予定の学校プールの屋根もしくは屋根に代わる設備の検討を要望させていただいています。担当課が考える現状のプールの考え方、課題、方向性をお聞かせほしいと求めました。","respondent":"荒木学校施設担当課長","answer":"児童・生徒数が増加傾向にあること、あとは学校間で施設格差をつくらないようにする観点から、各学校においてプールを整備する考えで進めております。","id":"exchange-004"},{"speaker":"西村委員","kind":"質問","question":"全ての子どもができる限り泳げるようになり、水難事故から自衛する能力を身につけるという、とても大切な意義についても伺ってまいりたいと思います。熱中症対策やプールの機会担保、学校間の差が生まれないようにどのような方策を取るのか、実施しているのかについて伺います。","respondent":"荒木学校施設担当課長","answer":"プール授業の実施に当たりましては、気温以外にも、プールの水温管理、特に温度上昇を防ぐということが重要かと考えています。今後、各校の授業実施状況や費用対効果を十分に検証した上で、設置を検討してまいりたいと思います。","id":"exchange-005"},{"speaker":"西村委員","kind":"提案","question":"そして、具体的な施策についても伺ってまいりたいと思うのですが、ソフト面の年間１０時間を確保する取組について伺ってまいります。このように、運用面で実際に工夫していただいていることもあると思いますので、ソフト的な取組について区の方針を伺いたいと思いますとの意見を述べました。","respondent":"丸谷教育総合支援センター長","answer":"天候不順等により計画どおり実施できなかった学校であっても、ほとんどの学校で２コマ続きの授業が１回できなかった程度で収めることができました。こういったことからも、現状の取組を、何とか授業のやりくり等で、時数の確保に努めてまいりたいと考えております。","id":"exchange-006"},{"speaker":"西村委員","kind":"質問","question":"指導者を外部に委託するべきではないというようなお考えがございましたが、全校生徒が入れているという学校もあると伺っております。水泳授業が難しいという課題も区内で様々あると思いますので、新しい取組を検討できないかというのを併せて伺えればと思います。","respondent":"丸谷教育総合支援センター長","answer":"改築中の学校における外部委託につきましては、１つの方策だと捉えております。周辺の立地などといった状況を見ながら、適切な対応ができればと考えております。","id":"exchange-007"},{"speaker":"西村委員","kind":"提案","question":"今ご提案させていただいた、建て替え中の学校ですけれども、そこだけではなくて、夏休みのプールの水泳授業の実施が難しいというのが、今、区内の中であるかと思うのですが、現状はどのような感じか、お聞かせいただけますか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"今年度の夏季休業中の水泳指導についてですけれども、やはり暑さの影響でかなりの学校が中止せざるを得ない状況にございました。","id":"exchange-008"},{"speaker":"西村委員","kind":"質問・要望","question":"今のプールの管理や維持負担の課題を訴えている自治体もあるのですけれども、今、品川区内では現状その点はいかがでしょうか。伺います。","respondent":"荒木学校施設担当課長","answer":"定期的に清掃を実施するほか、それからプールの水槽自体を取り替えるといったようなことで、児童・生徒が安全に安心してプール授業が実施できるような環境を整えているところです。","id":"exchange-009"},{"speaker":"西村委員","kind":"質問・要望","question":"よく言われておりますけれども、泳げないがゆえに多くの児童が亡くなってしまったことが、学校のプール普及の背中を押したとも言われております。この水泳授業の必要性は大変痛感しておりますので、ぜひハード面とソフト面両方でご検証を重ねてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問","question":"私からは、１０８ページ、学校保健特別対策事業費補助金に関連して、登下校中の熱中症対策と黄色い帽子についてお伺いします。登下校時における熱中症対策として、品川区での現状と対策についてお聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"登下校中の飲料ということも許可しておりまして、自分で自分の身を守るという指導を行っております。近隣の区有施設等に一時的に避難して涼むということも認めておりますので、そういったところで熱中症対策を進めているところです。","id":"exchange-011"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"昨年の７月に市内全児童に配付されましたが、帰りに冷たくなくなるとの声を受け、市内全１６校に冷凍庫が配備されました。他自治体よりも先んじた、一歩踏み込んだ熱中症対策が、今後さらに求められていくのではないかと思われますが、区の見解をお聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"これは、今後こうした暑さ対策の一つとして学校からも声かけできるように、こちらからも声かけをしていきたいと考えます。冷却グッズの利用についても併せて検討してまいります。","id":"exchange-012"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"今後さらに、そういった熱中症対策が求められていくのではないかと思われますので、さらに前向きに進めてほしいと求めました。子どもの安全を守る観点で配慮をお願いし、要望したいと思いますが、区の見解をお聞きできればと思います。","respondent":"山下交通安全担当課長","answer":"各関係部署との調整も必要になってくると思いますけれども、そういった選択制にできるかどうかについて検討してまいりたいと考えているところです。","id":"exchange-013"},{"speaker":"ひがし委員","kind":"確認","question":"根本的な確認となりますが、保育所等利用多子世帯負担軽減事業により、１０月からは東京都の補助金を受けたという認識でよろしいでしょうか。１年間の予算として上げられていたと思いますので、その点について、どのような金額の行方になっているのかも併せて、答えるよう求めました。","respondent":"芝野保育入園調整課長","answer":"今、まず４月から９月までは区の財源で実施したかというご質問ですが、区独自の施策として保育園保育料第２子無償化を実施し。財源につきましてはお見込みのとおりで、４月から９月までは区の財源、そして１０月からは東京都の補助金を頂戴しております。","id":"exchange-014"},{"speaker":"ひがし委員","kind":"確認","question":"同じような質問がありまして、実際にどのような使い方になったのかというところで確認させていただきました。現在の都議会の動きを見まして、第１子無償化となった場合、品川区の対象児童数および予算額はどのぐらいになるのか尋ねました。","respondent":"芝野保育入園調整課長","answer":"第１子無償化がなされた場合の対象人数と金額についてのご質問ですが、現時点での試算になりますが、令和７年４月から実施した場合、対象人数は延べ２万７,０００人、金額、保護者の負担軽減額は約１１億５,０００万円と試算しております。","id":"exchange-015"},{"speaker":"ひがし委員","kind":"意見","question":"いつから無償化を第１子についても考えているのかなど、もし今、現状でお答えできる範囲でいいのでお答えほしいと求めました。ぜひ品川区として、子育て世帯の負担軽減のために、これからどんどん展望を広げていければと思いますので、説明を求めました。","respondent":"芝野保育入園調整課長","answer":"第１子無償化に係る今後の考え方についてのご質問ですが、都と情報交換を密にし、検討を進めていきたいと考えています。今後の区の保育施策については、これからも子育て世代の皆様の視点に立ち、しっかりと着実に推進していきたいと考えております。","id":"exchange-016"},{"speaker":"ひがし委員","kind":"質問・要望","question":"その点は要望に留めておきますが、ぜひ前向きに検討を進めてほしいと求めました。次に、１２９ページの０歳児見守り・子育てサポート事業、おむつ宅配についてお伺いします。","respondent":"石橋品川保健センター所長","answer":"私からは、０歳児見守り・子育てサポート事業についてご回答いたします。利用率の７２.７％という件ですが、実施は５か月という期間でしたが、決して低い利用率ではないと評価しております。","id":"exchange-017"},{"speaker":"ひがし委員","kind":"意見","question":"区のホームページを見ると、８月に更新されていて、利用の仕方のところが少し変わっているのかと思いました。どういうことなのか分かりづらい点があったので、また運営事業者と随時、どのようなタイミングでされているのかというのも説明を求めました。","respondent":"石橋品川保健センター所長","answer":"その中で、受託者の方と毎月１回の見守りの定期報告会や見直しの会を実施しておりますので、こちらの時間枠を縮小させていただきました。支援員を待つ時間を短くすることで、養育者の負担を軽減するということにつながったと考えております。","id":"exchange-018"},{"speaker":"ひがし委員","kind":"質問","question":"４時間ずつで区切られていたものが、もっと細かく、いつ来るというのが分かるようになったという認識だと考えています。予約の時間というところも指定できて、分かるといいのかと思いますが、いかがか尋ねました。","respondent":"石橋品川保健センター所長","answer":"ルートを設定して、近隣の地区を集めて回っている関係上、なかなか時間指定というところまでは現状、難しい状態です。しばらくは２時間枠で様子を見ながら、実施を進めてまいりたいと考えています。","id":"exchange-019"},{"speaker":"ひがし委員","kind":"質問・要望","question":"逆に、利用していない２７.３％の方々への支援というのはどのようにしているのでしょうか。見守りにつながるような取組などがありましたら、教えてほしいと求めました。","respondent":"石橋品川保健センター所長","answer":"支援が必要とされているご家庭に関しては、こちらの事業の実施を促しておりましたり、状況等の確認をさせていただいているところです。今後、利用していない人の把握やアプローチ方法は、課題として捉えて検討してまいりたいと考えています。","id":"exchange-020"},{"speaker":"ひがし委員","kind":"質問・要望","question":"最後に１点だけ、こちらは要望だけですけれども、「しながわこどもぽけっと」というところにいろいろな子どもの情報が載っていると思います。ぜひこの中に入れていただきたいというのと、そちらに直接飛べるような形にしてほしいと求めましたので、その点については要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いたいと思いますが、このペースでは到底、解体のピークに対応できるとは思えませんが、いかがでしょうか。新たな補助制度を設けるなど、国に求めるべきだと思いますけれども、いかがか尋ねました。","respondent":"中西環境課長","answer":"今、現状、委員にご紹介いただきましたとおりの制度となっています。私ども環境課としましても、２３区と共に、国にはアスベスト対策事業に関する要望等はさせていただいているような状況です。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"１つは、現行の調査・除却助成を、新たに調査拡大対象になったレベル３建材にも拡大することを求めますけれども、いかがでしょうか。ここも踏まえた新たな助成制度や対象拡大の検討をしてほしいと求めましたけれども、いかがか尋ねました。","respondent":"中西環境課長","answer":"こちらに関しましても他区の動向等を注視しながら、拡大についても検討してまいりたいと考えています。引き続き、より効果的に使っていただけるような助成制度というものは検討してまいりたいと考えています。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"産廃費用の問題についても伺ったので、もう一回、その辺をお伺いします。","respondent":"中西環境課長","answer":"産廃費用についてです。その辺りに関しましても、清掃事務所とも調整しながら、どのような形が取れるかというのは検討してまいりたいと考えています。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いますけれども、最終的に当該地区への補助金投入総額は幾らになるのでしょうか。こちらを確認させてください。","respondent":"中道都市開発課長","answer":"そうした中で総額は２２５億円になる予定です。区が支出している費用につきましては、都市計画交付金または財政調整交付金等で充当するものになります。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"もう一度お伺いしたいのですが、３分の１ずつというのですが、国が３分の１、東京都が３分の１、区が３分の１ということでしょうか。伺いたいと思います。","respondent":"中道都市開発課長","answer":"それの３分の１が国、また３分の１が区、３分の１が事業者が負担するというところになります。それで、区が負担する額といたしましては、７７億５,３２７万８,０００円というところになります。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"ところが渋谷区を見ますと、その時点で１３０億円にすぎず、品川区の１０分の１しか入っていないのです。伺いますけれども、なぜ品川区は、新宿区や千代田区、渋谷区などに比べて、これほど税金を入れて再開発を進めるのか、率直に伺いたいと思います。","respondent":"中道都市開発課長","answer":"再開発につきましては、駅前に空間をもたらす歩行者動線、または防災上の観点といったことを進めていくといったところになります。法令等またはそういった手順に従って補助金を算出しているものですので、区としては適正に補助をしている、支援をしているです。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"では、ほかの区は申請していないということなのですか。品川区はなぜそんなに申請するのか尋ねました。","respondent":"中道都市開発課長","answer":"基本的には、補助金といったものは、最後に埋めるピースというような考えです。品川区の床というのは価格的に見ると低い傾向にありますので、そういった部分を品川区としては補助金で補っている部分もあります。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"そういうことをやっているということが、今の答弁でもう完全にはっきりしたのではないかと思うので、私はこれはどうなのかと。財産権も居住権も奪われて苦しんでいるのですから、もうぜひ正していく必要があると、区民のための税金の使い方をしてほしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"７９ページ、１４８ページ、ふるさと納税寄附金についてお伺いいたします。その辺りを説明を求めました。","respondent":"築山戸籍住民課長","answer":"そういった中で、現在、稼働率が低下している、なぎさ会館をどうするかということで、検討を進めているところです。今後の活用方法についてですが、こちらも併せて検討していく予定です。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"臨海斎場の状況に合わせてやっていかれるということかと思います。その辺り、区民の火葬場・式場について、どのようなお考えをされているのかをお聞きしたいと思います。","respondent":"築山戸籍住民課長","answer":"告別式が終わった後の移動を考えますと、車で移動する手間・コスト等を考えると、区民にとっては使いやすいというようなところです。そういったことを踏まえまして、検討も一緒に進めていきたいと考えております。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"区民の方にインパクトを与えるのかなと思いますので、この状況についての区民への説明や、またその予定というのは考えておられるのか尋ねました。","respondent":"築山戸籍住民課長","answer":"施設の特性上、なかなか周知が難しい施設であるというところは感じているところです。おくやみハンドブックの作成もしておりまして、今年度も改定する予定ですので、そういったところで周知を図っていきたいと考えております。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問","question":"続いて、公園占用料、ロケーション・写真撮影等についてお伺いいたします。そうしたことから、「しなロケ」、フィルムコミッション事業は今後どのように展開されていくのか、お知らせください。","respondent":"大森文化観光戦略課長","answer":"サイトも多くの閲覧者が引き続きいるので、サイトはそのまま残すといった形で運用を続けます。ロケ支援業務等は引き続き、引き続き、続けていくというような形です。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問","question":"つまり、今後、委託ではなくて、区の職員がきちんと運用していくということで、人件費コストをやはりメインに下げていくという理解でよろしいのか尋ねました。","respondent":"大森文化観光戦略課長","answer":"そちらの認識で結構です。","id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"そのバランスを取っていっていただきたいのですけれども、今後、公園占用料への影響というのはどのように考えていくのか。その辺りはどのように考えられているのか、お知らせください。","respondent":"大森文化観光戦略課長","answer":"ロケ支援につきましては、そちらにつきましては、特にフィルムコミッションと歳入の大きな関わりという部分はないかと思います。","id":"exchange-035"},{"speaker":"筒井委員","kind":"質問・要望","question":"抜本的な見直しをぜひ求めていっていただきたいと考えておりますけれども、一方、品川区としても寄附額の増加を図っていかなくてはいけない。積極的に仕掛けていくべきかと考えておるのですけれども、体験型返礼品の周知・広報というものをお考えなのか、お知らせください。","respondent":"吉野税務課長","answer":"今、委員ご指摘のとおり、こちらの流出額は５０.９億円ということで、年々上昇しております。興味のある方、ターゲット層をもう少し検討して、研究して広げていきたいと考えております。","id":"exchange-036"},{"speaker":"筒井委員","kind":"意見","question":"都市ブランディングということもありますので、品川区の魅力につながるようなものの開発というのを積極的に行っていってほしいと求めました。ぜひよろしくお願い申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"せらく委員","kind":"質問・要望","question":"たばこ税収については、前年度比でマイナス４.４％と、先ほど確認いたしました。東京都全体と比較した品川区の喫煙人口の割合も教えていただきたいです。","respondent":"若生健康課長","answer":"区では健康に関する意識調査を約５年置きに実施しておりまして、令和５年度に実施しておりまして、１８％となっておりまして。直近で申し上げますと、令和４年度の全国の喫煙率で申し上げますと１６.１％、それから東京都の令和４年度に関しましてが１３.５％となっています。","id":"exchange-038"},{"speaker":"せらく委員","kind":"確認","question":"品川区内で見ると、平成２９年と比べて令和５年は減少傾向にあるということが確認できました。その要因の分析と、課題解決に向けた取組を説明を求めました。","respondent":"若生健康課長","answer":"喫煙が体に与える影響につきまして、イベントや、あとは禁煙外来治療助成の制度を推進しているというところ。すくすく赤ちゃん訪問の際に、相談があったときにたばこの害について説明したチラシを配布するなどといったところで啓発に取り組んでいるところです。","id":"exchange-039"},{"speaker":"せらく委員","kind":"確認","question":"喫煙マナーのマナー啓発の多言語化について、本日、取組を確認したいと思います。過料の件数の中に外国人がいらっしゃったか、何件くらいか肌感覚でも構いませんので、お願いします。","respondent":"河合生活安全担当課長","answer":"その他の歩行喫煙のところにつきましては多言語対応になっていないところもありますので、今後、多言語対応の検討をしてまいりたいと考えております。","id":"exchange-040"},{"speaker":"せらく委員","kind":"質問・要望","question":"マナーアップについて多言語化の取組をお聞きしたのですけれども、喫煙所と路上喫煙禁止の地区は４か国語で対応しているとお聞きしました。こちらについて、見解を伺います。","respondent":"河合生活安全担当課長","answer":"委員がご指摘のとおり、表示物だけではなく口頭での指導を、外国語を話せない状況でも提示するような形でできるように、検討してまいりたいと考えております。","id":"exchange-041"},{"speaker":"せらく委員","kind":"質問","question":"では最後に、品川区民の喫煙ルールについての認知度がどの程度あるかということをお聞きしたいのですけれども、調査をしていらっしゃったら認知度について、所感を説明を求めました。","respondent":"河合生活安全担当課長","answer":"認知度についての調査というものは行っておりません。知らなかったということもありますけれども、そういったところは丁寧に説明する形で、周知徹底をしてまいっているところです。","id":"exchange-042"},{"speaker":"せらく委員","kind":"質問・要望","question":"マナーアップの点では、調査はぜひ行っていただきまして、調査を基に効果的な啓発方法を探していってほしいと求めました。議会費の質問をしたいと思っていたのですけれども、時間がありませんので、本日はこちらで質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"横山委員","kind":"質問","question":"私からは、６０ページ、特別区財政調整交付金、１４７ページ、児童相談所移管推進事業についてお伺いいたします。１点目に、児童相談所移管推進事業についてお伺いいたします。","respondent":"長谷川児童相談課長","answer":"児童相談所開設に向けた準備経費を主に計上させていただいておりまして、引継ぎに関する経費や研修に関する経費等を計上しています。","id":"exchange-044"},{"speaker":"横山委員","kind":"質問","question":"開設直後の児童相談所は軌道に乗るまで大変だというお話をお伺いいたしました。開設して１日ではありますが、１０月１日０時０分の様子や、職員の方々の現状について説明を求めました。","respondent":"長谷川児童相談課長、金子一時保護担当課長","answer":"１年前から引継ぎを開始いたしまして、約６,０００件の終結ケースを含めると、約６,５００件の引継ぎを完了したところです。この間、職員は、いわゆる困難ケースにも果敢に対応するなど、強い使命感と責任感でやり遂げてくれました。初めて対応した職員は、ほっとした、本当に胸をなでおろしたというような感想を述べていました。","id":"exchange-045"},{"speaker":"横山委員","kind":"質問・要望","question":"なぜ大切な人が、とても大切で身近な家族や子どもたちに暴力を振るわなければならないのでしょうか。トラウマケアを強化していただきたいと要望いたしますが、小・中学校、保健センターにおけるトラウマケアの現状をご説明ほしいと求めました。","respondent":"長谷川児童相談課長、加島財政課長、中島保育施設運営課長、三ツ橋荏原保健センター所長","answer":"組織的な導入を図っていきたいと考えておりまして、昨年度も外部の研修を多々受講させていただいて、今年度も引き続き受講する計画であります。例えば児童福祉法上の位置づけや、役割分担の変更に当たるかといった検討を行いました。こちらにつきましては、本年７月に１度… 保育園・幼稚園におけるトラウマケアについてですが、園児に寄り添った保育を行うとともに、専門家による育児相談を行っているところです。","id":"exchange-046"},{"speaker":"横山委員","kind":"質問・要望","question":"区長会、区立児童相談所の事務の財調上の位置付けに関する都区ＰＴやワーキンググループにおいて強く働きかけていただきたいと考えています。需要額に見合う財源の確保を、どうぞ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"こしば委員","kind":"質問","question":"私からは、８２ページ、衛生手数料に関連しまして、災害時の地域医療についてお聞きします。そこでお聞きいたしますが、地域医療連携課の発足の経緯についてと、またその役割、目的について教えていただけますか尋ねました。","respondent":"遠藤健康推進部次長","answer":"私からは地域医療連携課の設立経緯についてご説明します。コロナ禍の対応を総括する趣旨で検証しました、「新型コロナウイルス感染症対応の検証と健康危機管理体制の基盤整備検討報告書」におきまして。","id":"exchange-048"},{"speaker":"こしば委員","kind":"質問","question":"医療と行政のシーレーンが構築されなければ、危機は格段に押し迫ってまいります。まず前提のこととしてお聞きいたしますが、どのような対応、また運営をされるのか尋ねました。","respondent":"遠藤健康推進部次長","answer":"中等者・重症者につきましては、設置する病院でそれぞれ対応する。それで、適切な治療を受けられるように対応するものです。","id":"exchange-049"},{"speaker":"こしば委員","kind":"質問","question":"医療救護所の話をされたと思いますけれども、私が聞きたかったのは、まちなかに個人の病院がいろいろとたくさんありますが、例えば大震災が起きたときに個人の病院がどういった対応を、一律にされるのかどうかも含めて、その辺を教えてほしいと求めました。","respondent":"遠藤健康推進部次長","answer":"いわゆる、まちの診療所というところですけれども、透析など専門医療機関という部分を除いて、基本的には１週間程度、閉鎖するような扱いになります。","id":"exchange-050"},{"speaker":"こしば委員","kind":"質問","question":"今、次長がご答弁のとおり、近隣のまちなかの診療所が閉鎖されるということをお伺いいたしました。どの区民も最寄りの医療救護所を利用できるような、あらかじめの周知を徹底してもらいたいと考えますが、お考えを教えてもらえればと思います。","respondent":"遠藤健康推進部次長","answer":"今年から地域医療連携課ができたということで、定例会というのを医師会等と設けしています。ポスター作成について進めているところでございまして、恐らくは今年末か、あるいは来年早々にはお配りできるかと考えているところです。","id":"exchange-051"},{"speaker":"こしば委員","kind":"質問・要望","question":"ぜひ区内全域に展開してほしいと求めました。災害時の時間帯を分けた上での訓練も必要と考えますが、その辺りの取組、またお考えを教えてほしいと求めました。","respondent":"遠藤健康推進部次長","answer":"現在、区で災害に対しての医療救護所マニュアルの改定作業を進めております。徐々に関係の医師会なり歯科医師会、薬剤師会というところと訓練をできるだけ多くやりまして、進めていきたいと考えているところです。","id":"exchange-052"},{"speaker":"こしば委員","kind":"質問","question":"消毒液、食塩水、ガーゼなども必要となります。ローリングストックに向けた、区といいますか、医療救護所または学校救護所の取組や考えがありましたら説明を求めました。","respondent":"遠藤健康推進部次長","answer":"いわゆる災害拠点連携病院というところがあるのですけれども、これまで防災課の予算を用いまして、それぞれ配置していたところです。薬剤師会と話をしながら、今後また医師会とも話をしながら、ローリングストックについて進めていければと考えているところです。","id":"exchange-053"},{"speaker":"こしば委員","kind":"質問・要望","question":"ローリングストックについては、様々な機関で連携して、前に進めてほしいと求めました。今までどおりだと、そういったことも、ぜひ後方支援に取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"塚本委員","kind":"質問","question":"私からは、１１０ページ、障害者自立支援給付費、それから１３４ページの住宅・建築物耐震化補助金の２点を伺いたいと思います。選択するときに、どういった情報を参考に選んでいらっしゃるというようなことになっているのかという実態について、認識をお伺いしたいと思います。","respondent":"松山障害者支援課長","answer":"私からは、同行援護事業所の契約についてお答えいたします。比較的、ご自身が慣れた、同じ事業所を使っている例が多いと聞いております。","id":"exchange-055"},{"speaker":"塚本委員","kind":"質問・要望","question":"もう少し教えていただきたいことがあるのですけれども、例えば大体１回、どういうところから来る話なのかというのを確認したいのと。事業所はどういうところが利用できるのだというところについて、その点についてどのようにお考えか、説明を求めました。","respondent":"松山障害者支援課長","answer":"いわゆる安心して、この方に任せられるというところが、一番の大きな選ぶ観点だと聞いております。いずれにしろ、ご本人にとって選びやすいような情報を相談支援事業所が集めて、選択の範囲ができるような仕組みにはしていきたいと考えております。","id":"exchange-056"},{"speaker":"塚本委員","kind":"意見","question":"１３４ページ、あと浸水しやすい場所など、区内に幾つかあると思います。そういった地盤調査的なところで、ここのうちは地盤が弱いのでという話まで範疇に入っているのかというのを最初に説明を求めました。","respondent":"森建築課長","answer":"耐震診断の地盤面のところですけれども、現状は地盤のところまでは対象には入っていません。","id":"exchange-057"},{"speaker":"塚本委員","kind":"確認","question":"それは、義務なのか。まず確認したいのと、そういった地域というのは、区としては把握できているのかというところについてお伺いいたします。","respondent":"森建築課長","answer":"区で地盤が弱いところはどこかというところですけれども、東京都の方で、液状化の予測という資料があるのですけれども、埋立地のところです。海側の方が、地盤があまり、液状化の可能性がある地域ということは認識しています。","id":"exchange-058"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、そういう浸水被害があって、その辺についての建築基準法上の地盤調査なり改良の義務みたいなものは発生しないということでいいのか。そこについてお伺いします。","respondent":"森建築課長","answer":"建物を建てる際は、地盤に対してしっかりと支持しなければならないとなっておりますので、義務として地盤を調査した上で、それに見合うような基礎をつくるということになってあります。","id":"exchange-059"},{"speaker":"おぎの委員","kind":"質問","question":"１２８ページ、時間がありましたら１３９ページ、学校ＩＣＴ活用経費についてお伺いいたします。品川区へふるさと納税ができる方法がありますが、やはり間に業者を挟まないと、ダイレクトなふるさと納税は難しいのか尋ねました。","respondent":"吉野税務課長","answer":"今の、流入額ですけれども、２,４００万円なのですが、そちらの郵便局などといったところの内訳は、現在、持ち合わせておりません。","id":"exchange-060"},{"speaker":"おぎの委員","kind":"質問・要望","question":"先ほど筒井委員から、体験型の広報についての質問がありましたが、品川区のブランディング全般に関わることだと思います。今後の広報戦略について全般的にお聞かせいただけたらと思いますが、いかがか尋ねました。","respondent":"吉野税務課長","answer":"今後ですけれども、やはり体験型はどんどん増やしていきたいと考えております。そういったことも区民の方に知っていただかなければならないと考えておりますので、そういったところも含めてやっていきたいと考えております。","id":"exchange-061"},{"speaker":"おぎの委員","kind":"質問・要望","question":"続きまして、１２８ページの商店街活性化推進事業助成金についてお伺いいたします。商店街にぎわい創出事業や商店街活性化推進事業に充てられているようですが、こちらの事業の評価について説明を求めました。","respondent":"小林地域産業振興課長","answer":"そういったイベントや、あるいは地域のキャンペーンの事業、ミニイベントなども含めて応援しているものです。令和５年度以降、こういうところがにぎわい創出の１つの核になるのかと、我々は評価しています。","id":"exchange-062"},{"speaker":"おぎの委員","kind":"質問","question":"最後に、１３９ページ、学校ＩＣＴ活用経費から、現在、区立小・中学校に貸与しているタブレットについてお伺いします。こちらは、どちらのメーカーで、どういったサーバー委託を行っているのか尋ねました。","respondent":"柏木学務課長","answer":"申し訳ございません。後ろの部分の質問が聞こえなかったので、もう一度お願いします。","id":"exchange-063"},{"speaker":"おぎの委員","kind":"質問・要望","question":"本体がｉＰａｄで、サーバーがＮＴＴということで確認いたしました。子どもたちの個人情報の流出がないように、しっかりと守ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"山本委員","kind":"質問","question":"私からは、６８ページの公園運動施設使用料、９９ページのヤングケアラー支援事業について伺います。ヤングケアラー支援事業について伺います。","respondent":"染谷子ども家庭支援センター長","answer":"こちらは令和５年９月に実施しておりまして、小学校４年生から高校３年生の年齢を対象として実施しております。支援策を検討するということを目的としまして、また行政や周りの大人に求める支援などをお聞きしておりまして、中学生で５.２％。","id":"exchange-065"},{"speaker":"山本委員","kind":"意見","question":"さらにはピアサポートの開催が行われましたが、それぞれの成果と効果について、区のご見解をお教えください。令和６年度の新たな取組とその実績についてもお教えくださいとの意見を述べました。","respondent":"染谷子ども家庭支援センター長","answer":"それから私ども子ども家庭支援センターのケースワーカー、１００名に近いヤングケアラーの方と接点を持ち、相談支援を実施しています。配食支援につきましては３家庭・１６８食、学習支援１件、必要な支援を積極的に行ってまいりたいと考えております。","id":"exchange-066"},{"speaker":"山本委員","kind":"質問・要望","question":"で、小学校６年生の約１５人に１人、中学２年生の約１７人に１人がヤングケアラーであることが明らかになっています。区としてこの点についてどのような課題を認識しているか、説明を求めました。","respondent":"染谷子ども家庭支援センター長","answer":"ヤングケアラー支援における課題ですけれども、１つ、ケアの状況が表面化しにくいといったところが課題の一つと認識しております。そういった意味で、問題が表面化する前の予防的な関わりが重要であると今認識しておりまして、具体的には継続的な研修の実施や。","id":"exchange-067"},{"speaker":"山本委員","kind":"確認","question":"意識調査に加えて、回答後にすぐ正しい解説を確認できる形式とすることで、子どもたちがこの問題について理解を深めることが可能となります。ヤングケアラー支援の課題解決に向けて、この手法は非常に有効であると考えますが、区としてどのようにお考えか尋ねました。","respondent":"染谷子ども家庭支援センター長","answer":"効果的な支援を進める上で、アンケートの手法を活用することは非常に有効であると認識しております。令和５年度に実施いたしましたアンケート調査においても、ＳＮＳ相談など、必要な支援につなげていくというような取組を進めてまいりたいと思います。","id":"exchange-068"},{"speaker":"山本委員","kind":"質問・要望","question":"区が開催したパラスポーツチャレンジデーで当広場に伺いましたが、子どもたちが参加する「３Ｘ３」のイベントが開催され、大変盛り上がっていました。バスケットコートとグラウンドを分けて利用できる工夫があれば、区民の皆様も喜ばれると考えますが、いかがか尋ねました。","respondent":"大友公園課長","answer":"委員のご指摘のとおり、人工芝のグラウンドとトラック、またバスケットコートが一体となった整備となっているところです。ハード・ソフト面の両面から検討してまいりたいと考えているところです。","id":"exchange-069"},{"speaker":"山本委員","kind":"質問・要望","question":"ほかの公園においても、様々な工夫により多くの区民の皆様が有効に活用できる環境づくりを進めてほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"中塚委員","kind":"質問・要望","question":"６８ページ、７１ページ、それぞれ小・中学生の利用料無料化を求めて質問したいと思います。区民プールですが、令和５年度において小学生からは総額で幾ら、中学生からは総額で幾ら、それぞれ利用料を徴収したのか伺います。","respondent":"大森文化観光戦略課長、三井スポーツ推進課長","answer":"令和３年度の小・中学生の観覧料になりますが、合計で３万３,０００円の歳入実績となります。 区民公園の屋外プールの利用料につきましては、小学生が５０万円ほど、中学生が６万円ということで、合計５６万円ほど徴収しているところになります。","id":"exchange-071"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川歴史館について、全ての子どもを、どの子も分け隔てなく無料にすべきだと思いますが、いかがでしょうか。ぜひ無料化を実施してほしいと求めましたが、いかがか尋ねました。","respondent":"大森文化観光戦略課長、大友公園課長","answer":"４月２１日から歴史館がリニューアルオープンいたしまして、観覧料を改修以前と変えておらず、据置きというような形で運用しています。据置きが妥当であるということで認識はしているところではありますが、今後… 利用者が限られる施設におきましてですけれども、受益者負担の考えの下、使用料を設定させていただいているところです。","id":"exchange-072"},{"speaker":"中塚委員","kind":"質問・要望","question":"森澤区長はそのようには考えないのでしょうか。改めて、子どもから徴収している様々な事業について総点検をして、子どもの完全無償化を進めてほしいと求めましたが、いかがか尋ねました。","respondent":"大森文化観光戦略課長、大友公園課長","answer":"回答としては繰り返しとなりますが、あと諸費用がかかっているところに関しまして、現在の金額が妥当であると認識しております。品川区の歴史に、少しでも区内・区外の皆様に触れていただきますよう… 受益者負担の考えが基本となりますけれども、無用の予約が入り過ぎてしまうと、運用上の問題もあります。最低限のご負担という範囲内で、受益者負担の考えの下、使用料を徴収させていただいているところとなっています。","id":"exchange-073"},{"speaker":"中塚委員","kind":"質問・要望","question":"壊れているのではないか」との声を伺います。ロッカーの使用料は全員無料に、つまり返却式に変更してほしいと求めましたが、いかがか尋ねました。","respondent":"大友公園課長","answer":"入場者の上限であります予約数とロッカーの数が同じでありまして、１人の方が複数使用しますとロッカーが不足することになります。その点も防止する観点におきまして、最低金額ではありますけれども、１０円をご負担いただいているところになってあります。","id":"exchange-074"},{"speaker":"中塚委員","kind":"質問・要望","question":"歴史館やプールやロッカーの１０円についても、社会全体で子どもと子育てを支えるという視点で、ぜひ無償化を進めていただきたい。区長がおっしゃる本気度が、こうしたところにも現れてくると思いますので、重ねて要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"えのした委員","kind":"質問","question":"私からは、１６６ページの水族館運営費収入についてお伺いします。先日、私もその当時に子どもたちと家族でお世話になって以来、十数年ぶりに視察に伺いました。","respondent":"大友公園課長","answer":"飼育設備などの設置も検討しておりまして、活用を図ってまいりたいと考えているところです。公園利用者も含めて、誰もが利用しやすい運営形態にできないかなど、幅広い視点で検討してまいりたいと考えております。","id":"exchange-076"},{"speaker":"えのした委員","kind":"質問","question":"期間や季節限定メニューは、好奇心を満たしたり、お客様の満足度が向上するよい取組だと考えております。何々というのですか、特徴のある新しい、また展示と連携した常設のメニューの開発などはいかがか尋ねました。","respondent":"大友公園課長","answer":"品川区の水族館として地域の特性を活かした展示ができないか、現在、検討しています。レストランの常設メニューにつきましても、展示と関係する魚を食べることができるなど、特徴あるものにしていきたいと考えているところです。","id":"exchange-077"},{"speaker":"えのした委員","kind":"質問・要望","question":"こちら、しながわ水族館ならではの展示とメニューを楽しみに期待して、要望といたします。区民割引や、あとノベルティの特典なども考えていますが、いかがか尋ねました。","respondent":"大友公園課長","answer":"現在実施しておりますニジマスを使った期間限定メニューのような工夫を、これからも続けてまいりたいと考えているところです。リニューアル後のレストランにおける水族館入館者のレストラン割引などにつきましては、今後も検討してまいりたいと考えているところです。","id":"exchange-078"},{"speaker":"えのした委員","kind":"質問・要望","question":"実証実験の効果はこれからだと思いますが、水族館付近の区民公園にもキッチンカーが出店されていると伺いました。スペースの有効活用、にぎわいの創出には一定の効果があるのか尋ねました。","respondent":"大友公園課長","answer":"キッチンカーにつきましては、しながわ水族館だけではなく、しながわ区民公園の利用者の利便性の向上、また、にぎわいの創出を目的に、週末に設置しているところでございまして、一定の効果があると認識しております。","id":"exchange-079"},{"speaker":"えのした委員","kind":"質問・要望","question":"続いて、売店のマリンショップ「シーガル」についてお伺いいたします。水族館に入館されない方も利用できるつくりになっているのが特徴だと思いますが、現状の売店の年間売上げ、購買者数などをお伺いいたします。","respondent":"大友公園課長","answer":"令和５年の数字となりますけれども、年間売上げは約１億５,０００万円、正確には１億５,１００万円程度です。購買者数は９万７,０００人程度、年齢層につきましては水族館の客層と同様、また客単価につきましては１,５００円程度となっているところです。","id":"exchange-080"},{"speaker":"えのした委員","kind":"質問・要望","question":"確認が取れました。区民にゆかりのあるしながわ水族館づくりのために、ぜひ連携した取組を要望いたします。","respondent":"大友公園課長","answer":"しながわ区民公園に位置する水族館の利点を活かしまして、自然と調和した展示の演出手法や建物形状などを検討してまいりたいと考えています。リニューアルに合わせた周辺環境の整備につきましても、効果的な整備の視点で検討してまいりたいと考えているところです。","id":"exchange-081"},{"speaker":"えのした委員","kind":"質問","question":"ぜひ、自然と調和した取組を進めてほしいと求めました。江戸湾クルーズというのですか、あと今度１０月にはお笑い芸人のガイドによる特別船なども実施されますが、区のご見解をお伺いします。","respondent":"大友公園課長","answer":"リニューアル後の水族館におきましても、水族館に近接する桟橋を活用しまして、舟運と水族館を連携させ、より一層来館者に楽しんでいただけるよう、ソフト面の工夫も図ってまいりたいと考えています。","id":"exchange-082"},{"speaker":"えのした委員","kind":"質問・要望","question":"今後の展開にも期待して、要望として終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"私は８０ページの住民基本台帳証明手数料に関連してと、あと１１０ページの生活保護費について質問します。品川区の現状をお聞かせほしいと求めました。","respondent":"築山戸籍住民課長","answer":"区といたしましては、これまで当事者に寄り添うことができないかどうか、他自治体の状況を踏まえながら検討を進めてまいりました。そういったところで、現状は課題があるというところで認識しています。","id":"exchange-084"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"再考を求めるというところですけれども、具体的にどういった実務上の課題といいますか、問題が生じるおそれがあると通知されているのか尋ねました。","respondent":"築山戸籍住民課長","answer":"準婚としての各種社会保障の面では、法律上の夫婦と同じ扱いを受けている内縁の夫婦、いわゆる事実婚のみを表すものと解すべきとされております。","id":"exchange-085"},{"speaker":"やなぎさわ委員","kind":"質問","question":"神奈川県逗子市も、総務省が言うほど重大な懸念事項があるとは考えていないと。これに関してそれほど、総務省が懸念するようなトラブルや支障が起きるようには感じないのですけれども、その点を改めてお伺いできればと思います。","respondent":"築山戸籍住民課長","answer":"こちらにつきましては総務省から大村市への回答の中の、複数ある質問のうちの一つとして回答されたものです。このほか、国からは、住民基本台帳法の趣旨や目的、最高裁判決と異なるといったことを踏まえて、大村市に対して再考を求めているです。","id":"exchange-086"},{"speaker":"やなぎさわ委員","kind":"質問","question":"区長は東京都議会議員時代に、同性パートナーにも認めてほしいという声に真っすぐに答えてほしいと、繰り返し訴えてきましたとおっしゃられています。区長の思いを頂けたらと思うのですが、無理ならいいのですが、いかがか尋ねました。","respondent":"築山戸籍住民課長","answer":"こちらについてアナログで対応するという手法を取ったとしましても、誤った運用をしてしまうおそれがあり、法的な危険性があるです。それぞれ、国からは大村市に再考を求めているという状況ですので、品川区として同様の取組をするのは難しいと考えているところです。","id":"exchange-087"},{"speaker":"やなぎさわ委員","kind":"意見","question":"やはり、区長のお考えと少し区の方針が違うのかと思いますので、区長、ご答弁を頂ければと思いますとの意見を述べました。","respondent":"築山戸籍住民課長","answer":"国に対しましては、機会を捉えまして、住民基本台帳事務処理要領の改正について要望してまいりたいと考えております。","id":"exchange-088"},{"speaker":"こんの委員","kind":"質問","question":"１２０ページ、１４６ページ、この３点についてお伺いしたいと思います。実績としては６３万５,０００円といったところにとどまっているので、まず、この辺のところはどのような状況なのかをお聞きしたいと思います。","respondent":"樫村高齢者地域支援課長、山下交通安全担当課長、羽鳥防災体制整備担当課長","answer":"申込み状況ですが、令和５年度につきましては、２８８名の定員に対しまして３１８名の方のお申込みを頂いているところです。… それに比例した形で返還台数も減少しているものと認識しています。まだまだ放置自転車はありますので、引き続き放置自転車の減少に向けた対策を取ってまい… ３００万円を予定していたところ、やはり防災ラジオの機能も含めて、まだ認知されていないのかというところを課題として認識しています。","id":"exchange-089"},{"speaker":"こんの委員","kind":"提案","question":"今後その辺のところはどういうふうに考えていらっしゃるのか、いま一度確認させてほしいと求めました。こうしたところで販売されたらどうですかという提案を我が会派でしたことがあるのですが、どんな体制を取られたのか、その辺を伺いたいと思いますとの意見を述べました。","respondent":"樫村高齢者地域支援課長、山下交通安全担当課長、羽鳥防災体制整備担当課長","answer":"５会場、大井三丁目高齢者憩いの場、平塚橋ゆうゆうプラザの５会場で実施しています。受託事業者との兼ね合いもありますけれども… 当日の利用につきましては満車であることも多々あるということは認識していますが、当日と定期利用のバランスを柔軟に変更しながら対応していますし。… 限られた期間の中での対応ということで、東京都電気工事工業組合品川・目黒地区本部を受託者といたしまして契約いたしまして、実施しています。","id":"exchange-090"},{"speaker":"こんの委員","kind":"質問・要望","question":"先ほどお話しした９４歳のおばあさまは、その辺は満遍なく、できるだけ全域に少しずつ増やしていっていただけるとありがたいという要望です。今後防災ラジオの、一人でも多くの方が情報をきちんと災害時に受け取る体制をさらに進めてほしいと求めましたが、いかがか尋ねました。","respondent":"樫村高齢者地域支援課長、山下交通安全担当課長","answer":"「はじめてのスマホ教室」の会場のバランスについてのお尋ねです。区としましては、利用状況や地域バランスといったところを考慮しながら、多くの方に参加いただけるように事業を展開してまいりたいと考えています。 建物を変えるというよりは改修という形で進めさせていただいているのですが、委員からのご意見も踏まえながら、将来に向けていろいろ検討していきたいと考えているところです。","id":"exchange-091"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、１５４ページの奨学金貸付金返還金に関わって、給付型奨学金の実施を求めて質問します。伺います。","respondent":"飛田子育て応援課長","answer":"現在の返済の状況ですが、令和６年８月現在で１９３人の方が返済しております。返済の金額全体は約３,９００万円となっております。","id":"exchange-092"},{"speaker":"のだて委員","kind":"質問","question":"将来を担う若者が希望を持って生活できるように、全額または一部、免除すべきだと考えますけれども、いかがでしょうか。実際、今、返還されている方が１９３人いるわけですけれども、その中で滞納者は何人いらっしゃるのか、滞納している方の理由も伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"当初の予定より返済が遅れているということで、７８人ということで、こちらに上げております。滞ってしまっているというところは、就職がなかなか決まらなかったり、体調が悪いということで返済が遅れてしまうということは聞いております。","id":"exchange-093"},{"speaker":"のだて委員","kind":"質問","question":"免除が必要ではないかと思いますけれども、いかがでしょうか。高校時代から借金を負わせているということについて、将来の足かせになっていると思いますが、いかがか尋ねました。","respondent":"飛田子育て応援課長","answer":"しっかり最後まで完済している方がいらっしゃる中、不公平なく区としても対応すべきだと考えております。利用者の方と相談しまして、返済しやすいように計画の見直しをするなど、柔軟な対応を取っているところです。","id":"exchange-094"},{"speaker":"のだて委員","kind":"質問・要望","question":"高校では１０名、大学は７０名ということで、借りている方の半額を助成しています。なので、ぜひ支援を進めていくべき、してほしいと求めましたが、いかがか尋ねました。","respondent":"飛田子育て応援課長","answer":"他区の状況を我々も注視しているところです。そういうところの状況を見ながら、またこの先も注視していきたいと考えております。","id":"exchange-095"},{"speaker":"のだて委員","kind":"質問・要望","question":"若者の学ぶ権利が保障されて、未来に希望が持てるようにしていただきたいということで要望しておきたいと思います。給付型奨学金の実施を求めたところ、区独自の給付型奨学金の実施に踏み出してほしいと求めましたが、いかがか尋ねました。","respondent":"飛田子育て応援課長","answer":"今年度より多子世帯や私立・理工系の学生へも支援が拡大しております。今後とも、区が実施している様々な支援策の動向や区民ニーズなどを注視しまして、必要性を含めて検討を行ってまいりたいと考えております。","id":"exchange-096"},{"speaker":"のだて委員","kind":"質問","question":"必要性を含めて検討するということで、それは区独自の給付型奨学金の実施に向けて検討するということでしょうか。伺います。","respondent":"飛田子育て応援課長","answer":"様々な他区の状況も含めて、支援策、動向も必要かと思います。そういうところで区民ニーズなどを注視し、必要性を含めて検討を行ってまいりたいと考えております。","id":"exchange-097"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひこれは実施に向けて検討していってほしいと求めましたが、他区の状況を注視するということで、区も答弁してきました。２３区で給付型奨学金を実施している区はどこか、また他区の状況、ご存じのことをご説明ほしいと求めました。","respondent":"飛田子育て応援課長","answer":"他区の状況で、私どもとして捉えているところは、足立区と港区というところで今調査しているところです。それぞれ、そこのところでテストを行ったり、あと所得の制限というところも配慮しながら支給を行っていると伺っております。","id":"exchange-098"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ給付型奨学金を実施してほしいと求めました。経済的な格差が教育格差につながらないように、子どもたちを支援してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"石田（し）委員","kind":"質問","question":"私からは、５２ページ、区民税に関連してと、１５０ページ、財政調整基金、時間があれば１５２ページの諸収入についてお伺いします。お聞きしたいのが、どのようにお考えになっているのか、またその理由を説明を求めました。","respondent":"加島財政課長","answer":"それから中国における不動産市場の動向、停滞の継続というのが、日本経済に影響を与えているというような分析をされているところです。インフレの傾向は見られるけれども、デフレを完全に脱したわけではないという、一言で言うのは難しいような状況があります。","id":"exchange-100"},{"speaker":"石田（し）委員","kind":"意見","question":"例えば５００円でジュースを５本買えたのが、今だと同じ５００円でも３本しか買えない。そういったことを区として今回の令和５年度の決算としてどのように認識されて、来年度と向かっていくのか、お考えをお示しくださいとの意見を述べました。","respondent":"加島財政課長","answer":"令和５年度決算における動向というところですけれども、第２子保育料無償化、高校生までの医療費無償化などに取り組んでまいりました。今後の動きですけれども、現在、総合実施計画を策定しております。","id":"exchange-101"},{"speaker":"石田（し）委員","kind":"意見","question":"節約癖が、もうこの３０年間でついてしまって、思い切った財政出動をすることがなかなか難しい。区長をはじめ、マインドをみんなが変えて、改めてその辺のお考えをお知らせくださいとの意見を述べました。","respondent":"加島財政課長","answer":"品川区の区政として当初予算では１,９００億円余の規模を見込んでおりましたけれども、そして歳出につきましても１,９４１億円。子育て、教育で選ばれる品川区として、積極的な投資というのは区でも続けてまいりたいと考えております。","id":"exchange-102"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これは要望で終わります。主な減の中で、リサイクル資源売払収入が６,０００万円ちょっと減っているのですけれども、これの理由を説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"石田（し）委員","kind":"質問","question":"そうですか。何でここが急に減になったのかと思って、少し不安になって聞いたので、分かりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-104"},{"speaker":"高橋（伸）委員","kind":"質問","question":"１２７ページ、予防接種費、７１ページ、八潮北公園スケートボード場についてお伺いいたします。最初に、１２７ページ、予防接種費についてお伺いいたします。","respondent":"五十嵐保健予防課長","answer":"フルミストにつきましては、高い感染予防効果が期待できまして、血液内にも免疫を成立させることができるというようなものになります。鼻から噴霧するワクチンですので、お子さんにとりましては、針を刺すということがなく接種できるようなワクチンになってあります。","id":"exchange-105"},{"speaker":"高橋（伸）委員","kind":"質問","question":"令和５年３月１３日の予算特別委員会、衛生費款別審査で、元我が会派の鈴木博委員が詳細な質問を行っております。この秋からフルミストを使用できることになった今、区は区民に対してフルミストについてどのような情報提供をされているのか尋ねました。","respondent":"五十嵐保健予防課長","answer":"現在、特にフルミストについてということで区民の方に周知しているわけではございませんが、子どものインフルエンザワクチンにつきましては、今までのワクチンと同様に助成をすることにしております。","id":"exchange-106"},{"speaker":"高橋（伸）委員","kind":"意見","question":"区のホームページの子どものインフルエンザ予防接種の項目を見ても、フルミストに関しては、助成の対象という以外、詳しい情報提供が行われていないように見えるのですが、今後、区はどのような対応をされていくのか、説明を求めました。","respondent":"五十嵐保健予防課長","answer":"ホームページ等でフルミストについて詳しくお知らせする予定はないのですが、入れている医療機関もそんなに多くないような状況ということも伺っておりますので、今の時点では特に区民に対して周知をしていく予定はございません。","id":"exchange-107"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、７１ページ、八潮北公園スケートボード場についてお伺いいたします。現状と、今後どういうふうに展開していくという課題や展望というのですか、そういうものがもしあったら教えてほしいと求めました。","respondent":"三井スポーツ推進課長","answer":"令和５年度は一旦利用数が落ち着いておりますが、今年度はまた月平均約３７０件と上がってきております。やはり今後も多くの方に利用いただけるよう、公園課とも連携しながら広く周知していきたいと考えております。","id":"exchange-108"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それと、あとコーンでスケートボード禁止とうたわれております。ぜひ今後、そういった啓発を含めて公園課とも連携してほしいと求めましたので、何かあればご答弁を。","respondent":"大友公園課長","answer":"やっているところがあり、苦情等もあり、その関係で「禁止」という表示をさせていただいているところです。委員からご提案いただいた形等々も踏まえまして、「八潮北公園にスケートボード場があります」という表記も併せて設置していきたいと考えています。","id":"exchange-109"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"改めて啓発、ポスターなり告知をしていただいて、要望で終わりたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-110"},{"speaker":"田中委員","kind":"質問・要望","question":"行政同士で財源を求め合うとか仕事を求め合うということではなくて、東京都として、あるいは品川区として。そこを確認させてほしいと求めました。","respondent":"加島財政課長","answer":"そして今、プラスチック製品の回収などといったことに、種々取り組んでいるところです。基礎自治体である区が担うという姿勢で、この清掃事業をはじめ、区の行政サービスに向き合ってきているところです。","id":"exchange-111"},{"speaker":"田中委員","kind":"質問・要望","question":"戦闘的な交渉ではなくて、住民の子どもを扱う行政体として、しっかりソフトの面での視点を踏まえた財政調整協議にぜひ臨んでいただきたい。ぜひよろしくお願いを申し上げ、このテーマは今後も続くと思いますが、どうぞ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-112"},{"speaker":"吉田委員","kind":"質問・要望","question":"９９ページ、それから１２４ページ、それから１２９ページの０歳児見守り・子育てサポート事業で見守りおむつ定期便について伺います。その辺についての、本来の目的に沿った、区としての検証や成果、課題などもありましたら教えてほしいと求めました。","respondent":"石橋品川保健センター所長","answer":"委員ご質問の見守りの趣旨、この件の成果についてのご質問と捉えました。毎月同じ支援員の方がご自宅に訪問することで、相談も継続的に実施しておりまして、しっかりと見守りができていると認識しております。","id":"exchange-113"},{"speaker":"吉田委員","kind":"確認","question":"どういう方たちがこの事業に、直接、区民の方と会う仕事に取り組まれるのかということを、何度も確認しています。どういう研修を行われているのか、どういうふうにスキルを判断されているのかについて伺いたいと思います。","respondent":"石橋品川保健センター所長","answer":"見守り支援員の方には、区の子育て支援の紹介、保護者対応などのコンプライアンスについての研修をしっかりしています。私も支援員の方と、お子さんに会って状況の確認をされているということは、しっかりとこの目で確認もさせていただいているところです。","id":"exchange-114"},{"speaker":"吉田委員","kind":"質問・要望","question":"それが今後のスキルアップにつながると思いますので、その辺を教えていただきたいのと、結局、資格については全く問わないということなのでしょうか。その辺も確認させてください。","respondent":"石橋品川保健センター所長","answer":"区から対応するなど、今はしておりますが、しっかりその場で対応できるようなスキルをブラッシュアップするようにという形で努めております。実際、併せて子育て経験のある方ということも条件にしておりましたので、子育て経験が何かしらある方を今採用しているところになります。","id":"exchange-115"},{"speaker":"吉田委員","kind":"質問・要望","question":"自分が学校に行っている間にお母さんが自殺してしまったらどうしようと思って学校に行けないなどというお子さんがいらっしゃるという話を伺いました。もっと年齢の低い子どもたちへの調査などを考えておられたら伺いたいと思います。","respondent":"染谷子ども家庭支援センター長","answer":"今、委員からお話がございました、やはりヤングケアラーの定義に当てはまってくる部分かと思います。今、関係機関との連携の中で、そういった幼いお子さんの状況などにもきちんと対応できるような体制を取っていきたいと考えております。","id":"exchange-116"},{"speaker":"吉田委員","kind":"質問・要望","question":"本当によかったと思っているのですけれども、その配食のサービスを求めるときに、特に理由などは必要ないでしょうか。自分たちはこういう状況で配食を求めると言えば、誰でもサービスが受けられるのか、その辺についても確認させてください。","respondent":"染谷子ども家庭支援センター長","answer":"ヤングケアラーに対する配食支援サービス事業ですけれども、まず区のほうで子ども家庭支援センターのケースワーカー、支援計画を作成します。","id":"exchange-117"},{"speaker":"吉田委員","kind":"質問・要望","question":"その辺についても今後は整備されていくことを求めますが、その辺について現状はどうなのでしょうか。例えば掃除とか洗濯などという支援はあるのか尋ねました。","respondent":"染谷子ども家庭支援センター長","answer":"現在行っております家事支援の訪問支援事業ですけれども、乳幼児・児童の保育といったところも含めまして実施するような形になっておりまして、こちらとしても重々認識しているところでございまして。","id":"exchange-118"},{"speaker":"吉田委員","kind":"質問・要望","question":"保育所等の質の確保・向上のための巡回支援指導事業費補助金について伺います。品川区のホームページには、この事業について、のびしな支援隊ですか、成果が出ているのですが、実施回数しか出ていないのです。","respondent":"芝野保育入園調整課長","answer":"のびしな支援隊は、巡回支援指導員が各施設を回っておりまして、認可外保育所３８回など合計３００回実施しております。安全対策の実施状況などを確認しまして、また園運営や職員の姿勢、保護者対応などの悩みも聞かせていただいているものであります。","id":"exchange-119"},{"speaker":"吉田委員","kind":"質問・要望","question":"これからも保育の質の確保に向けてぜひ頑張ってほしいと求めました。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-120"},{"speaker":"若林委員","kind":"質問・要望","question":"２０１５年からスタート、開始いたしまして１０年ということで、そろそろ見直しを図ったほうがよろしいのではないでしょうかという観点です。１０年たちましたので、しっかりと見直しをしたほうがいいと思いましたので、ここで要望します。","respondent":"菅野高齢者福祉課長","answer":"事業開始から約１０年が経過しまして、いま一度、紙おむつ事業の助成額や所得制限については見直す必要があると考えているところです。事業を実施している社会福祉協議会には、区としましては、その事業経費に係る支援を積極的に行ってまいりたいと思っているところです。","id":"exchange-121"},{"speaker":"若林委員","kind":"提案","question":"いわゆる特定施設有料老人ホームというのでしょうか、そちらにも、また今後のさらなる検討の１つの課題としてご提案させてほしいと求めました。","respondent":"菅野高齢者福祉課長","answer":"今、あとはグループホームなどにつきましては、現段階では紙おむつは自己負担という形で徴収させていただいているとは聞いております。ホームによっては紙おむつを使用しないという形で対応しているなど、その辺りの検証を図りながら、今後も研究していきたいと思います。","id":"exchange-122"},{"speaker":"西本委員","kind":"質問","question":"私からは、主要施策の成果報告書の８ページ、今までもいろいろ質問が出ていましたが、３つの無償化に対してお聞きします。特に品川区の負担というところから見ると、どうなっていくのかの動向を説明を求めました。","respondent":"加島財政課長","answer":"保育料の第２子無償化につきましては、先ほども答えましたが、１０月から東京都より補助金が入っているところです。そのようなことが各施策の柱として、ビジョンとしています。","id":"exchange-123"},{"speaker":"西本委員","kind":"質問","question":"なぜかというと、スタートは、例えば先ほどのように、第２子の保育料については、東京都に先駆けて品川区がやっている。そこを説明を求めました。","respondent":"加島財政課長","answer":"先ほどもございましたが、住民に身近な基礎自治体としてできることというところで進めているのが、令和５年度に進めたものが３つの無償化です。令和５年度決算につきましては、必要な施策に必要な財源を投入できるように、区として考えを持って動いているところです。","id":"exchange-124"},{"speaker":"西本委員","kind":"質問","question":"なぜ３つの無償化が、優先順位が高いのでしょうか。だから、福祉を充実しているからという認識でよろしいのか尋ねました。","respondent":"加島財政課長","answer":"こちらは教材や給食費など福祉的な考え方に傾いているのではないかというご指摘がございましたけれども、今、無償化を進めているところです。１０分の１０、こちらが既に先行実施しているものに対して、それは財源獲得に動いてまいります。","id":"exchange-125"},{"speaker":"西本委員","kind":"質問","question":"では何をどうするのですかと、さんざん私は言っていますけれども、少し見方を変えていきたいと思うのです。１０分の１０、説明不足でしたと言われればそれまでかもしれませんけれども、これからどういう考え方で区政運営をしていくのかを、答えるよう求めました。","respondent":"加島財政課長","answer":"今までやってきたことについて特定財源を獲得できるのであれば、区として獲得に動いてまいります。言わせていただくのであれば、先駆的に進めたことに対して、区として区の施策にやっと周りが追いついてきたと自負しております。","id":"exchange-126"},{"speaker":"西本委員","kind":"意見","question":"品川区の皆さん、理事者の皆さん、今までやってきたことを、もっと自信を持ってやってください。そして、未来のある、希望のある品川区の運営というか、事業の展開をお願いして終わりたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-127"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"行政評価も２０億円、今年も２０億円を目標としてやってきているけれども、ではこれはいつまで続くのですか。これは予算の問題になってきてしまうから、今度、予算をどう組み立てるのか尋ねました。","respondent":"久保田企画経営部長、加島財政課長、吉岡政策推進担当課長","answer":"これは本当に粘り強く交渉していかなければならないと考えているところでございまして、こうした中で、これを引き続き粘り強く続けていく。… 機動的な支出の１つの例といたしましては、こちらは財政調整基金から約１３０億円を取り崩して実施したところです。… 令和７年度予算編成に係る基本方針、全庁において事業の見直しを行いまして財源の確保を行っていくことといたしまして、意思統一を図ったところです。","id":"exchange-128"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"２０人ぐらい入れるところを、ほんの三、四人で使っていていいのかなど、いろいろな発想もあるじゃないですか。そういう人たちも、ぜひその辺を考えていただきたいというのが今日の質問の主眼なのですが、ぜひお考えを説明を求めました。","respondent":"崎村企画課長","answer":"施設を利用しない一般の普通の区民の方の負担の公平性、受益者負担の適正化ということについては、課題意識を持って取り組んでいるところです。他区においては施設使用料を見直したり、そういった大きな課題について、企画課を中心に全体的に検討してまいりたいと考えております。","id":"exchange-129"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そうすると、指定管理料の話にもなったりするわけじゃないですか。きゅりあんなども含めて、ぜひ私はそれをやっていただきたいと思うので、お願いで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-130"},{"speaker":"高橋（し）委員","kind":"質問","question":"品川区議会会議規則第７７条の８に基づく、私は見つけられなかったので、お伺いします。予算ではどの程度の額を計上していたのか尋ねました。","respondent":"大澤区議会事務局長","answer":"参考人の費用弁償につきましては、予算計上もしておりませんし、今まで実績もございません。","id":"exchange-131"},{"speaker":"高橋（し）委員","kind":"提案","question":"本会議において候補者の所信を伺うことなく、区長による候補者の履歴による提案説明を頂いて議決してきました。この認識で正しいか尋ねました。","respondent":"大澤区議会事務局長","answer":"委員のご認識で合っているかと存じます。","id":"exchange-132"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"議会の同意により区長によって任命されるわけですから、人物としての輪郭がつかない状態では、区民の方への説明はなかなか難しい状況です。教育行政の先頭に立っていく決意はいかがですか、江戸川区における教育のビジョンの考え方はいかがですか、明快にお答えになっております。","respondent":"大澤区議会事務局長","answer":"委員のご提案のような、議会として参考人からの聴取ということであれば、どのような手続が必要か、今後、詳細に研究してまいりたいと思います。","id":"exchange-133"},{"speaker":"高橋（し）委員","kind":"質問","question":"こちら側がどういうふうに考えるかというところがありますが、その点を踏まえて区にお尋ねしますが、それは今までもやっていますと。今お話ししたような状況の中から検討の余地があると考えますが、区としてどのように進めていくのか、お考えを伺います。","respondent":"勝亦総務課長","answer":"人事案件の任命に伴いましては、丁寧な説明が必要であること。引き続き丁寧な説明をしてご理解を頂くような形で、説明、情報提供をさせていただければと考えております。","id":"exchange-134"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"区で準備をしていただきたいということになった場合は、今お話にあったようなご協力というか、体制を整えるための状況は整えていただけるわけか尋ねました。","respondent":"勝亦総務課長","answer":"そういった趣旨で必要な対応を取ってまいりたいと考えています。","id":"exchange-135"},{"speaker":"高橋（し）委員","kind":"質問","question":"先ほども長々と説明して申し訳なかったのですが、非常に重要な人事案件であり、品川区民の方々にとって大きな意味を持つ議決です。私たちに大変責任があるわけですから、もちろん、ぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-136"},{"speaker":"松本委員","kind":"質問・要望","question":"私からは、５２ページ、特別区民税、１６１ページ、生活保護費弁償金について伺います。第６３条返還の資力、第７８条徴収金の不正の手段について、当区の傾向があれば伺います。","respondent":"豊嶋生活福祉課長","answer":"そうしたものがなぜ発生するかと申しますと、当区の場合は遡及年金の額が多かったものと、あとは遺産相続をしたケースが７割から８割を占めている。そんな現状です。","id":"exchange-137"},{"speaker":"松本委員","kind":"質問","question":"この辺りは別の機会に伺っていきたいとは思うのですけれども、不納欠損額については結構変動があると見ております。先ほどもおっしゃられていたとおりで、回収しないといけないお金ではあると思うのですけれども、この回収に向けた取組について伺えればと思います。","respondent":"豊嶋生活福祉課長","answer":"２つから考えられるのは、やはり高齢化しているということが１つ言えるのではないかと考えています。その辺りは、状況を見ながら適時適切に行っているところです。","id":"exchange-138"},{"speaker":"松本委員","kind":"質問","question":"第６３条の返還金、これと、所得税や特別区民税の関係をお伺いしたいと思います。まずお伺いしたいのですけれども、特別区民税がどのように認定、請求されていくのかというところをお願いいたします。","respondent":"吉野税務課長","answer":"ただ、住民税の場合は、実際にもらったときの１期目に賦課という形で、そこで一括で請求するような形になります。それぞれの年度が４００万円以下であれば、申告、扶養制度というのは国のほうでうたっております。","id":"exchange-139"},{"speaker":"松本委員","kind":"質問・要望","question":"ただ１か年に全部収入が入ってしまうことによって、それを払ってしまった場合に、受給者の方がどうなってしまうのか。これは結構、大きな問題になってくるかと思いますので、またちょっと別の機会にやらせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-140"},{"speaker":"藤原委員","kind":"質問","question":"たばこ税について伺いますが、２３区の中で毎回上位だと思うのですけれども、今回は何位ぐらいでしょうか。たばこ税は減っていると思うのですけれども、その減った分析は含めないで、減ったことについてどういう感想があるか、教えていただけますか。","respondent":"吉野税務課長","answer":"そういった部分で、納税交渉といったところにつきましては、大分早く対応できるようになった次第です。これは、恐らくコロナ禍が５類に明けて、それで社会に皆さんが出られてというところで、買う先が品川区ではなくて勤務先になったものと思われます。","id":"exchange-141"},{"speaker":"藤原委員","kind":"意見","question":"１位ということで、これは職員の方の努力もあると思います。それについて、健康課としてはどう思いますかとの意見を述べました。","respondent":"若生健康課長","answer":"私どもとしましては、喫煙している方の割合を減らすということや、受動喫煙をなくす取組を進めているところです。区民の健康増進、ひいては医療費の削減にも寄与することですので、引き続き努力してまいりたいと考えております。","id":"exchange-142"},{"speaker":"藤原委員","kind":"質問","question":"次の質問に行きますが、１０４ページ、１３６ページで、埋蔵文化財。そして、教育委員会庶務課の中に係があると思うのですけれど、どのぐらいの方でやられていますか。","respondent":"舩木庶務課長","answer":"埋蔵文化財に関するご質問ですが、令和５年度の実績は５件です。体制につきましては、会計年度も含めて、係長を含めて、学術の専門の４名で対応しております。","id":"exchange-143"},{"speaker":"藤原委員","kind":"質問・要望","question":"ですから、ここの人数をしっかり増やしていかないとと考えていますが、この辺についてはいかがでしょうか。伝統、改めて今日訴えさせてほしいと求めましたので、ご答弁をお願いします。","respondent":"舩木庶務課長","answer":"今後の文化向上・発展の基礎となるものです。業務体制も必要かと考えておりますので、現状のところの課題も含めて、必要な人員体制というか執行体制について検討してまいりたいと考えております。","id":"exchange-144"},{"speaker":"藤原委員","kind":"質問","question":"それで、戦略課長というのは、「戦略」がついて何が変わったのですか。ですから、そのときから多分、自分が管理職になったらこうしたいのだ、ああしたいのだという思いがあったと私は思うのです。","respondent":"大森文化観光戦略課長","answer":"は、地域にお金が落ちていくというところを１つ大きなところとして、戦略的に考えていく必要があるかと考えています。そういうところに私が率先して取り組んでいくことが重要ではないかと考えております。","id":"exchange-145"},{"speaker":"藤原委員","kind":"質問","question":"６０ページの財政調整についてお伺いしますが、実際、児童相談所が出発しました。それで、今の協議について、答えづらいことはあると思うのですけれども、率直にどう思うか、答弁していただけますか。","respondent":"加島財政課長、久保田企画経営部長","answer":"今後も１２区程度続くと見込まれる中では、私はもっと財源を確保する立場として動いていかなければならないと考えております。これから令和７年度に向けての都区財政調整協議が始まりますけれども、財源確保に粘り強く… 平成１７年５月に区長会の会長に就任されて、都区制度改革、主要５課題の解決に全力で取り組まれておられました。","id":"exchange-146"},{"speaker":"藤原委員","kind":"質問・要望","question":"だって、常任委員会でも、こういう委員会でも、本会議でも、いっぱいこうやって要望が出ているじゃないですか。交渉していっていただきたいと思うのですけれども、いつまで私も質問できるか分からないので、ぜひ何か答弁いただければ幸いです。","respondent":"新井副区長","answer":"トータルとして、いかに使えるお金を確保していくか。戦略的に考えていかなければいけないと思っていますし、一円でも多く、区民のために使える財源を確保していくという思いは同じです。","id":"exchange-147"},{"speaker":"鈴木委員","kind":"質問・要望","question":"こういう相談者の方のような、この支援をぜひとも受けられるようにしていただきたいと思うのですけれども、いかがでしょうかということです。だけど、０歳児から保育園に預けている人は受け取れないということであれば、この点についてもお伺いしたいと思います。","respondent":"石橋品川保健センター所長","answer":"保育園に行っている方を対象から外すという制度ではありませんので、今、そちらで選んでいただいてご利用していただくような形でお願いしています。経済的支援というところの部分になりますが、また別の視点から、利用者の方の声を把握して検討してまいりたいとは思っております。","id":"exchange-148"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひ、誰もが受け取れる、保育園に０歳児で預けている方でも受け取れる。休みを取って受け取りに来るというのは本末転倒だと思いますので、そういう方向でぜひともご検討ほしいと求めましたが、いかがか尋ねました。","respondent":"石橋品川保健センター所長","answer":"見守り支援員から保健センターに緊急時、平日、月曜日から金曜日の９時から１８時までの見守りという形で設定しています。日時につきましては、今後そういった体制をしっかり整えた上で、どうしていくべきかを検討してまいりたいと考えております。","id":"exchange-149"},{"speaker":"鈴木委員","kind":"質問・要望","question":"第２回定例会でも介護報酬引下げを求める請願が出され、国でも調査すると言っていながら、引き下げられたままなわけです。区として訪問介護の事業所で閉鎖されているところがどれぐらいあるのか、把握されているところがありましたら教えてほしいと求めました。","respondent":"菅野高齢者福祉課長","answer":"そして、令和６年度は１事業者が廃止と捉えております。理由としては、把握し切れていないところはあるのですけれども、やはり人員不足や赤字経営などというような理由が主だと捉えております。","id":"exchange-150"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうところからしたら、課長からも答弁を伺っていますけれども、その辺のところはどういう状況になっているのかも伺いたいと思います。そこをアップさせていくという検討もぜひ必要なのではないかと思うのですけれども、その点についても伺います。","respondent":"菅野高齢者福祉課長","answer":"４月以降の訪問事業の事業者にどのような売上げ等の影響が出ているかというのも、まだ二、三か月の部分しか分析できないというところもあります。その辺りのところ、そして課長会での情報等も捉えながら、今後も注視していきたいと考えています。","id":"exchange-151"},{"speaker":"鈴木委員","kind":"質問・要望","question":"３年間続かずに、そういうことで手を挙げていっていただきたいということで、改めて求めておきたいと思います。１事業所当たり８８万円ぐらいということで、こういうこともぜひご検討いただけたらと思うのですが、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"他区についても、区としましては、１万円の居住支援手当というのを他区に先駆けて行っている部分もあります。区の独自の部分、いいところも伸ばしつつ、ほかの補助については研究していきたいと思います。","id":"exchange-152"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本当に介護保険料を払ってもサービスが受けられないという状況にならないように、ぜひ支援もよろしくお願いしたいと思います。令和７年度末でこの事業が終了するということですけれども、強力に東京都に求めていただきたいということで、要望だけさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-153"},{"speaker":"大倉委員","kind":"質問・要望","question":"その中で１点、こちらのコーディネーターも含めて教えていただきたいのですが、役割というところも併せて教えてください。令和５年４月に施行されたこども基本法の理念を踏まえ、もう少し長くしてほしいみたいな声があったので、関連にはなりましたが伺いました。","respondent":"柏木学務課長、中谷指導課長、荒木学校施設担当課長","answer":"様々検討させていただいているのですけれども、１つのところ、ネットワークの遅延については解消する必要があると考えているところです。引き続き… 時給が１,２７２円というところになっています。時給は１,２５０円となっております。 私からは、コミュニティ・スクールＤＡＹの意見について回答します。どうぞよろしくお願いします。","id":"exchange-154"},{"speaker":"大倉委員","kind":"質問・要望","question":"属人的になりがちでというので、一般質問では、この金額をもう少し見直すことができないのかというところについて伺いたいと思います。地元の人たちと、そういったところを見据えた取組をしていっていただきたいと思うのですが、その件についてお考えを説明を求めました。","respondent":"中谷指導課長","answer":"昨年度から実施しております。対話的な取組を増やして、また改善案や解決案というものも広がりを見せていけるのかと考えていますので、そのような支援をしてまいりたいと思います。","id":"exchange-155"},{"speaker":"あくつ委員","kind":"質問","question":"私からは、１３４ページ、都支出金、災害対応力向上支援事業補助金、１６３ページ、水と緑の市町村との交流事業参加費から伺ってまいります。都支出金、災害時応急物資確保費、４５０万円ですけれども、補助金の用途・目的について、まず説明を求めました。","respondent":"羽鳥防災体制整備担当課長","answer":"私からは、都補助金についてご回答します。２分の１の補助金、上限額４５０万円ということで事業が行われましたので、そちらの補助金を活用して携帯トイレを備蓄したものです。","id":"exchange-156"},{"speaker":"あくつ委員","kind":"確認","question":"今後、災害対応として導入されるトイレトラックについて確認してまいります。そして納車はいつなのか、伺います。","respondent":"羽鳥防災体制整備担当課長","answer":"こちらは、助けあいジャパンというところに発注いたしまして、７月３０日付で契約締結になってあります。納車日は２月の末を予定しています。","id":"exchange-157"},{"speaker":"あくつ委員","kind":"確認","question":"発注先である助けあいジャパンに確認しましたところ、間もなく大阪府交野市での納品が全国初になるであろうということでした。これまでも何度も確認してまいりましたが、遠からず、そして必ずやってくると思います。","respondent":"羽鳥防災体制整備担当課長","answer":"区の職員として役割があると認識していますので、今、調整しています。訓練のときに、地震体験車と同じようにトイレトラックも輸送するということを想定しますと、区の防災課の職員が運転するということは考えられます。","id":"exchange-158"},{"speaker":"あくつ委員","kind":"質問・要望","question":"災害時のトイレ問題について伺ったとき、本年５月に能登半島、珠洲市に災害ボランティアとして現地に入りました。品川区としての具体的な災害時のトイレ確保・管理計画の策定の検討に、ぜひ入ってほしいと求めましたが、いかがか尋ねました。","respondent":"羽鳥防災体制整備担当課長","answer":"引き続き、トイレの確保・管理計画につきましては、他自治体、他区の状況なども参考にさせていただければと思います。本部といたしましては、物資調達課というところが責任する部署になりまして、そこの責任者は防災体制整備担当課長である私になります。","id":"exchange-159"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２０１４年から１０年にわたり民間交流を積み重ねてきたことも踏まえまして、災害協定や文化・観光等の交流を求める質問を致しました。先日の公明党の一般質問で、災害時相互支援協定の早期締結を求める質問に対して、引き続き協議をしていくとの答弁を頂いたところです。","respondent":"平原防災課長","answer":"ただいまご質問にございました長野県飯田市との災害時相互援助協定ですが、この間、先方と協議してきたところ、内容につきまして整いまして、明日１０月３日に協定の調印を行う予定です。","id":"exchange-160"},{"speaker":"あくつ委員","kind":"質問","question":"こうした中で、各所管に伺っていきたいと思います。例えば町会・自治会、地域の区民の交流先として、今後、飯田市を含めていくということはいかがか尋ねました。","respondent":"宮澤地域活動課長、中西環境課長","answer":"飯田市の町会・自治会と地域との交流というところでのお答えです。課題があるかと思いますけれども、互いのメリットがあるように、町会・自治会を含めまして周知していきたいと考えています。過去には環境モデル都市にも選定された、非常に環境面で前向きに取り組んでいらっしゃる自治体だと認識しています。","id":"exchange-161"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"旧荏原第四中学校の跡地活用についてお伺いいたします。ぜひこの整備に向けて、引き続き検討を前に進めていただきたいと考えていますが、これまでの検討状況や今後の進め方などを説明を求めました。","respondent":"吉岡政策推進担当課長","answer":"今年度は外部有識者３名を交えた庁内検討会を開催いたしまして、施設のモデルプラン、整備・運営手法等の検討を進めているところです。","id":"exchange-162"},{"speaker":"まつざわ委員","kind":"意見","question":"築５０年以上の施設というのが９０施設、これは全体の割合ですと２６.９％と、老朽化した施設というのが大変増加しているということが分かります。そして今後の整備の在り方、考え方について、ご見解を説明を求めました。","respondent":"吉岡政策推進担当課長","answer":"全体的な考え方ですけれども、平成２９年の策定時におきましては、築４０年以上の施設が全体の割合で３６.５％。今後の整備の考え方ですが、財政の負担を考慮しながらも、子育て支援施設や福祉保健施設等の新たな行政需要には適時適切に対応いたしまして。","id":"exchange-163"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"審議して本当に必要なもの、求められているものの検討、そして整備を進めていただきたいと思っています。ぜひとも計画的に改修や改善というのを行っていただきたいのですが、改築費用の低減、ご見解を説明を求めました。","respondent":"吉岡政策推進担当課長","answer":"区民ニーズの変化に対応できているか、複合化、廃止といったところを様々幅広く検討していくことが必要だと考えております。幅広く区民の皆様に利用していただくような条件整備についても検討してまいりたいと考えております。","id":"exchange-164"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"品川区の人口もしばらくは増え続けていくと考えていますが、年齢の構成、そして区民ニーズについても大きな変化が出てくると考えています。品川区にとって本当に、そして品川区民にとって本当に必要な施設を整備していただきたいと最後要望しまして、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-165"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/285407?Template=document&Id=6849#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":124783,"voices":382}},{"id":"r06-20241003-4","meetingId":"r06-c-settlement","date":"2024年10月3日","dateIso":"2024-10-03","committee":"決算特別委員会","time":"午前 ９時３０分～午後 ４時５１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を174件整理しています。","topics":[{"id":"topic-01","title":"９時３０分開会 ◯新妻委員長 おはようございます。 ただいまより、決算特別委員会を開きます。 それでは、令和５年度品川区一般会計歳入歳出決算","agenda":"９時３０分開会 ◯新妻委員長 おはようございます。 ただいまより、決算特別委員会を開きます。 それでは、令和５年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"こしば委員","kind":"提案","question":"その際には、非喫煙者からも、煙のにおいがたまらないので、コンテナ型喫煙所の整備の拡大を求めるお声も複数お聞きいたしました。その課題について、まず教えていただけますか尋ねました。","respondent":"河合生活安全担当課長","answer":"それ以外の場所の喫煙に関する苦情等も全域に及んでいる状況がありますので、やはり喫煙所の整備は全域で必要だという認識に立っております。したがいまして、民間の公衆喫煙所の助成等を含めて、積極的に検討していきたいという考えです。","id":"exchange-001"},{"speaker":"こしば委員","kind":"質問","question":"適地が少ない中で、東京２３区が喫煙所整備のために民間に頼らざるを得ない状況にあることは分かりました。本区でも、公衆喫煙所整備事業について、まだ数年しかたっておりませんが、これまでの実績について教えてほしいと求めました。","respondent":"河合生活安全担当課長","answer":"実績につきましては、五反田地区ですが、令和５年度に１件の助成の実績となっています。本年については、今、１件の申請待ちというような形で推移しております。","id":"exchange-002"},{"speaker":"こしば委員","kind":"質問","question":"一律３００万円だったものが、今年の４月から、面積に応じて９００万円まで助成されることになりました。品川区でも、この制度活性化のために、区民の健康を守るために、この制度の拡大を促したいと思いますが、ご見解を伺います。","respondent":"河合生活安全担当課長","answer":"委員のお話にありました千代田区、渋谷区、そのほかにも中央区や港区など民間喫煙所の助成に力を入れている区の情勢をこちらも調査しております。","id":"exchange-003"},{"speaker":"こしば委員","kind":"質問・要望","question":"区内の公園にあります灰皿が、たしか私の調べでは１５カ所あったと思いますが、今、閉鎖されているのは、コロナ対策であると伺っております。順次閉鎖されました喫煙所の再開も含めた喫煙所の整備といったものも検討いただきたいと考えますが、見解を伺います。","respondent":"河合生活安全担当課長","answer":"連携してやっておりますので、町会等のまちの声もしっかり聞いた上で検討というところになっておりますので、そういったところで公園課が判断していくものと考えております。","id":"exchange-004"},{"speaker":"こしば委員","kind":"質問・要望","question":"地域の方からも何とかしてもらいたいという声もありました。そういった路上喫煙が禁止されている場所以外にも、こういった喫煙所の整備の検討を改めて求めたいと考えますが、区のお考えを説明を求めました。","respondent":"河合生活安全担当課長","answer":"区といたしましても、喫煙所の運営事業者等に、様々な助成事業のご案内等を進めているところです。したがいまして、事業者といろいろ打合せをしまして、大森地区に、今後、申請が来るような形で推進しています。","id":"exchange-005"},{"speaker":"ゆきた委員","kind":"質問","question":"私も街頭演説をする際に、ひどい煙の被害を何とかしてほしいというお声も度々伺っています。今後の人の混雑等を鑑みて、路上喫煙禁止・地域美化推進地区の指定や、さらなる対策の進捗について教えてほしいと求めました。","respondent":"河合生活安全担当課長","answer":"朝、そういったところで施工管理のほうにも申し入れして、こちらのパトロール隊と一緒に声かけをするなどして対応した経緯があります。","id":"exchange-006"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"要望としては、パーティションだけでなく、コンテナ型の喫煙所も考えてほしいと求めました。読み取れないほど劣化していますので、喫煙スペースの境界が区民へと分かる工夫も要望したいと思いますが、見解をお聞きしたいと思います。","respondent":"河合生活安全担当課長","answer":"西大井駅前のコンテナ型の喫煙所の検討は、実際にいたしました。設置できる場所が町会の御神輿を置く場所に限定されてしまうというところがございまして、そういったところも含めて検討いたしまして、現在。","id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問","question":"いまだにたばこのポイ捨てに悩まされて、注意喚起の掲示物だけでは対策として効果が薄いというお声も聞いています。こういったことに対して、現状、区の対策について、改めてお聞きできればと思います。","respondent":"河合生活安全担当課長","answer":"委員のほうで、その辺はうれしく思うところなのですが、そこは声かけの啓発も含めて力を入れていかなければいけないところであると認識しております。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"たばこのポイ捨てで火事を起こした場合、たばこのポイ捨てで火災を発生させた際には刑事罰に処せられるとの警告の掲示を要望させていただきました。ここについての進捗として、以上２点、お伺いしたいと思います。","respondent":"河合生活安全担当課長","answer":"防犯カメラの設置位置の関係です。こちらは、町会や自治会の設置の助成等を行っておりますけれども、こういった設置場所につきましては。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"吸殻ごみの９０％、横浜市では７０％の吸殻ごみが削減され、相乗効果としてもペットボトルや空き缶等のごみも削減されています。こういったところで、問題の解消を図るためにも、実証実験として、吸殻入れを投票型喫煙所の吸殻入れに変えていくことについて要望として終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"山本委員","kind":"確認","question":"１７９ページの区民アンケート、１８７ページのいじめ防止対策推進事業経費、２１１ページの地域スポーツ支援について伺います。事業の目的に対して取り組んでいる内容や定量的な目標設定が妥当かどうか、誰がどのように判断をしているのかを確認させてください。","respondent":"吉岡政策推進担当課長","answer":"事務事業評価シートに掲載されております事業の目的、あるいは取組、目標設定についてのご質問かと思います。総合実施計画ですとか個別計画の策定時、各所管がしっかりと検討、最終的には区として決定しています。","id":"exchange-011"},{"speaker":"山本委員","kind":"確認","question":"ここで個別の事務事業評価シートの内容について確認をします。区のご見解を伺います。","respondent":"吉岡政策推進担当課長","answer":"全体の考え方をご説明しますと、小事業内で複数の事業等を実施しております場合は、それぞれ指標を設定しています。継続して昨年度からの課題と捉えておりますので、事業の内容にもよりますけれども、今後とも定量的なアウトカム指標の設定に努めてまいります。","id":"exchange-012"},{"speaker":"山本委員","kind":"確認","question":"目的に対しての目標の妥当性を確認することが、施策に関し効果的に評価する極めて重要な点であると考えます。この点、外部機関によるレビューや目標設定などで民間企業のコンサルティングなど、アドバイスを受けることは難しいか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"対応する時間数、この事務事業評価とは別に実施しております政策評価、こちらの政策を進めていく主要な事業につきましては。こうした指標の設定につきましても、議会の皆様にチェックいただきまして、そういったご提案につきましても参考にさせていただいているところです。","id":"exchange-013"},{"speaker":"山本委員","kind":"質問・要望","question":"このような状況を踏まえ、以下の２点について要望を申し上げます。区のご意見を伺います。","respondent":"吉岡政策推進担当課長","answer":"すぐに大幅な変更はございませんけれども、効果的な手法については、引き続き検討していきたいと考えております。こちらについても、どのような周知方法があるか、そういった媒体も含めて検討していきたいと考えております。","id":"exchange-014"},{"speaker":"山本委員","kind":"確認","question":"続きまして、地域スポーツ支援について伺います。当日の参加者数や周知方法、アンケートによる満足度の確認について説明を求めました。","respondent":"三井スポーツ推進課長","answer":"周知方法ですが、広報しながわ、ＳＮＳ、あとは小中学校にチラシ配布や、近隣の皆様にポスティング等を実施しているところです。満足度については、来場者にアンケートを実施しまして、イベント満足度を把握できるようにしております。","id":"exchange-015"},{"speaker":"山本委員","kind":"質問","question":"イベントの楽しさをさらに多くの方に知っていただけるよう、動画を活用して広く周知することをご検討いただけませんでしょうか。今後の周知方法と来場者数の把握についてご検討いただけますか尋ねました。","respondent":"三井スポーツ推進課長、與那嶺戦略広報課長","answer":"動画ですが、ほかのスポーツの事業でも動画でのＳＮＳ発信はしておりますので、発信方法につきましては、事業ごとの必要性に応じて考えてまいります。周知方法は、ＳＮＳを可能な限り使っていきたいと考えております。 情報発信の観点につきまして、私からご説明します。ＬＩＮＥ、そういったものを効果的に使っていただけるように、それぞれの所管をサポートしていく考えです。","id":"exchange-016"},{"speaker":"山本委員","kind":"質問","question":"それぞれに対して、区のご見解を伺います。デジタル技術を活用することによって、コストと手間を大幅に削減できると考えますが、いかがか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"もう１点、定期的な区民アンケートの実施についてです。定期的な実施については、今後、引き続き検討させていただきたいところです。","id":"exchange-017"},{"speaker":"山本委員","kind":"質問","question":"そして最後に質問させていただいた区民アンケート、その全てに共通する課題は、区民の皆様の声を直接聞く効果的な仕組みがないことだと感じています。最後に、いじめ防止対策推進事業経費について伺いたいところですが、時間も限られておりますので、次の機会で質問させていただこうと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"１７９ページ、区民アンケートについて伺います。区の人権尊重の定めで、外国人差別の禁止の規定はどのように定められているのか伺いたいと思います。","respondent":"木村人権・ジェンダー平等推進課長","answer":"区において、現在、１９９３年（平成５年）に立ち上げた「人権尊重都市品川宣言」という宣言文があります。先住民族、外国人への差別ということで話が入っておりますので、こちらの宣言文において考え方を広く周知していくというところで対応しています。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いますけれども、２０１０年から続くこの東京都の私立外国人学校教育運営費補助金打切りは、区の見解を伺いたいと思います。今言った品川区の外国人学級児童・生徒等保護者補助金ですが、当然存続すべきですが、いかがか尋ねました。","respondent":"勝亦総務課長","answer":"朝鮮、韓国の３国を対象としまして、こちらにお住まいのご家族への支援という形で補助を実施しています。拡充等につきましては、今後、他区の状況等を調査しながら研究してまいりたいと考えております。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"むしろ無知によるいわれのない差別や偏見を受け続け苦しんできたのが在日朝鮮人の方、朝鮮学校に通う子どもとその家族ではないでしょうか。伺いたいのですが、差別することなく支援するよう検討してほしいと求めましたが、いかがか尋ねました。","respondent":"勝亦総務課長","answer":"こちらの学校に通っていて品川区に住民票を持たれる方ということでございまして、まず、国籍による差別というか区別はございません。外国人学校への給食費等の支援等につきましては、区立学校の給食費の支援等については教育委員会のほうで行っておりますが。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"エリアが南部ですから、南部ということで通っていますので、そういった意味では品川区の子どもが通っているのです。その点でいかがか尋ねました。","respondent":"勝亦総務課長","answer":"通われている区民の方、住民登録がある方への支援という形で、学校に対する支援ではございません。そういった意味では、それぞれの区民の方への支援は既に行っているというふうに捉えております。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ教育委員会とも連携して、支援の対象を広げていただきたいと要望したいと思います。アンケートは、もう時間がなくなってしまいましたので、また次の機会でやりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"筒井委員","kind":"質問・要望","question":"２０１６年３月に策定されたものですけれど、障害者について、そうしたユニバーサルツーリズムといったことが書かれているのかなと確認したところ。ユニバーサルツーリズムの観点を取り入れた都市型観光プランを新たに作成していただきたいのですけれども、その点、いかがお考えか尋ねました。","respondent":"大森文化観光戦略課長","answer":"改定を見送りまして、今後、改定をしていくという計画になってあります。その際におきましては、先ほどの観点を入れたところで十分に検討しまして計画をつくってまいりたいと存じます。","id":"exchange-024"},{"speaker":"筒井委員","kind":"質問・要望","question":"障害者にも優しいということは、やはり高齢者の方にも優しいということですから、高齢者の方のこれからの観光に対しても優しい取組ができる。次に改定が見込まれる都市型観光プランにぜひ取り入れていただきたいと思うのですけれども、その点、いかがお考えか尋ねました。","respondent":"大森文化観光戦略課長","answer":"ナイトタイムエコノミーに関しましては、我が課でも、きちんと発信していこうというふうに考えながら取り組んでいるところです。新たな計画改定のタイミングにつきましても、ナイトタイムエコノミー、そういったところにもしっかりと注視しまして進めてまいりたいと思います。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問","question":"それは先日の私の一般質問のご答弁にもありましたとおり、将来的に遺贈が１つ大きな条件、理由だと考えています。この２点の文書が必要だと思うのですけれども、一般質問から３か月くらいたちましたけれども、どうなっているのかを説明を求めました。","respondent":"吉岡政策推進担当課長、勝亦総務課長","answer":"旧料亭「秀」の件ですけれども、遺贈のお話がございましたので、まずそちらを私からお答えします。こちらにつきましては、既に所有者から品川区に対してご提出いただいているところです。 こちらにつきましては、国際友好協会と秀との賃貸借契約になってあります。つきましては、賃貸借契約に関しては、遺贈については関連のないものとして取り扱っております。","id":"exchange-026"},{"speaker":"筒井委員","kind":"確認","question":"遺贈を表明する所有者の公式的な文書が区に提出されたということで確認がとれました。やはり遺贈をするかどうかというのは、遺贈という条件を入れてくださいという旨の提言をすべきだと思うのですけれども、いかがお考えか尋ねました。","respondent":"勝亦総務課長、吉岡政策推進担当課長","answer":"賃貸借契約に関しましては、あくまで国際友好協会と、持ち主との関係の賃貸借契約ですので、そちらについて、遺贈の考え方は賃貸借には反映しないものと考えております。先ほどの総務課長の答弁にもございましたとおり、賃貸借契約につきましては、あくまで旧料亭「秀」の所有者と国際友好協会で行ったものです。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問・要望","question":"遺贈は、秀の所有者の方は、確実に品川区に遺贈をしてくれるのでしょうか。そこをしっかりと確認させていただきたいのですけれども。","respondent":"吉岡政策推進担当課長","answer":"遺贈を表明する文書をご提出いただいたと先ほど答弁申し上げましたけれども、この後、所有者から公正証書遺言を作成する、そういったところでこうした遺贈が担保されるです。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問","question":"そうしたものをしっかりとっていただいて、確実に品川区に遺贈していただくよう、よろしくお願い申し上げます。投票済証についてお伺いいたしますけれども、臨時啓発費に当たると、投票済証はそもそも発行義務があるのかどうかということをまずお伺いいたします。","respondent":"今井選挙管理委員会事務局長","answer":"私ども、今度の１０月２７日の選挙におきましても、シナモロールとハタチの龍馬のデザインで作成する予定です。この投票済証については、公職選挙法で発行を義務づけられておりませんので、全国では発行していない選挙管理委員会もあると聞いております。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"発行義務はないにもかかわらず、せっかく作成されているのですから、ぜひ投票済証の活用をお願いしたいと考えています。絶対いると思いますので、そうしたことも踏まえて、ぜひこの投票済証の活用をお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"せらく委員","kind":"質問・要望","question":"続きまして、文字起こしの精度面でお聞きしたいのですけれども、文字起こし後に校正に要する時間を大体で教えていただきたいです。製品の耐用年数はどれくらいなのか尋ねました。","respondent":"西澤ＤＸ戦略担当課長","answer":"文字起こしの精度は、会議の内容や集音状況、要は、外部環境によっても依存するので、大体５割から６割ぐらいかと考えております。早ければ３０分ぐらいでできるものもあれば、１時間、２時間かかるようなものもあります。","id":"exchange-031"},{"speaker":"せらく委員","kind":"提案","question":"今後の提案や要望につなげていきたいと考えていますので、本日は情報をいただきまして、ありがとうあります。続きまして、昨年７月に地域コミュニティアプリを展開するＰＩＡＺＺＡ株式会社と連携協定を品川区が締結したと確認いたしましたとの意見を述べました。","respondent":"西澤ＤＸ戦略担当課長","answer":"地域交流型のＳＮＳ、掲示板のサービスでございまして、利用者同士のＮ対Ｎのコミュニケーションができるということが特徴になっております。環境課、保健センター、そちらを今後も継続して設置していくというところが挙げられるかと考えております。","id":"exchange-032"},{"speaker":"せらく委員","kind":"質問・要望","question":"どのように活用することで区民に有益なものになると想定していますでしょうか。このピアッザの連携協定において、費用が発生していたら説明を求めました。","respondent":"西澤ＤＸ戦略担当課長","answer":"連携協定締結の効果の１つとしては、早期に品川エリアのコミュニティを開設できたことが挙げられると考えております。イベントの情報発信を積極的に実施いただくことが重要かと考えていまして、今後もチラシの配布を実施して普及に努めていければと考えております。","id":"exchange-033"},{"speaker":"せらく委員","kind":"質問・要望","question":"広報については、引き続き、様々な形で取り組んでいただけたらと思います。町会・自治会へは、アプローチしていれば、事例など詳しく教えてほしいと求めました。","respondent":"宮澤地域活動課長","answer":"地域ＳＮＳ「ピアッザ」ですけれども、現状では、町会・自治会への周知はしていないところです。特定のＳＮＳでの活用を促す予定はございませんけれども、例えば掲示板であったり、周知啓発の依頼があれば協力していきたいと考えています。","id":"exchange-034"},{"speaker":"せらく委員","kind":"質問・要望","question":"今、国民健康保険の加入・脱退など７つのＡＩチャットボットが使えるというところなのですけれども、また別のアカウントに飛んでくるように感じます。同一のＬＩＮＥ内ではできなかったのかというところを教えてほしいと求めました。","respondent":"西澤ＤＸ戦略担当課長","answer":"ＡＩチャットボットは、ロボットが用意されておりまして、こちらが８個、契約しておりまして、それごとに回答するようなものになっております。それに対して回答するようなものになっておりますので、逆に変な回答をしてしまうといったものがあるので、分けております。","id":"exchange-035"},{"speaker":"せらく委員","kind":"質問・要望","question":"ほかの自治体を見ていると、同一のＬＩＮＥ内でやっているところもあるのかなと感じましたので、質問をさせていただきました。自分が求めている回答にたどり着けたかみたいな、こちらの導入については、いかがか尋ねました。","respondent":"西澤ＤＸ戦略担当課長","answer":"現時点ではできないのですけれども、今後、ベンダーと改善要望などを出しながら研究していきたいと考えています。さらなる活用につながり、区民の利便性向上にもつながっていくと考えておりますので、研究していきたいと考えています。","id":"exchange-036"},{"speaker":"横山委員","kind":"質問","question":"私からは、１８７ページ、いじめ防止対策推進事業経費、１８９ページ、職員研修費についてお伺いいたします。１点目に、いじめ防止対策推進事業経費についてお伺いいたします。","respondent":"石井コンプライアンス推進担当課長","answer":"いじめ相談対策室の成果ですけれども、社会福祉士を持つ、もしくは公認心理師の資格を持ついじめ相談員が、被害児童生徒・保護者に寄り添った丁寧な対応をすることにより、いじめの早期発見、早期解決につながっていることが成果です。","id":"exchange-037"},{"speaker":"横山委員","kind":"質問・要望","question":"使う人の問題であることを確認した上で、損害賠償請求について学ぶなど、これからの時代に必要な情報モラルについての授業が行われていました。情報モラル教育の強化へとつなげていただきたいのですが、今後のいじめの根本解決に対する方向性について、区のご見解を説明を求めました。","respondent":"石井コンプライアンス推進担当課長","answer":"逆に言うと、残りの９５％にいかに啓発をしていくかということが大事だと考えております。ＳＮＳ相談に関して、何度も何度もやって、最終的には画像を投稿した人に対しての削除をお願いするという対応もお願いしたこともあります。","id":"exchange-038"},{"speaker":"横山委員","kind":"質問","question":"２点目に、職員研修費についてお伺いいたします。類似の職務を担当する正規の職員と会計年度任用職員などの正規の職員以外の職員の方々では、受講する研修の内容や回数などに違いはあるのか尋ねました。","respondent":"田口人材育成担当課長","answer":"採用２年目研修、３年目研修ですとか、分け隔てなく受講していただくことが可能となっております。","id":"exchange-039"},{"speaker":"横山委員","kind":"質問","question":"それぞれの職層において研修が変わっているということと、選択で受けられる研修があるということでお伺いしました。選択で受けられる研修の場合、どういった内容の選択ができるものがあるのか尋ねました。","respondent":"田口人材育成担当課長","answer":"選択で受けられる研修ですが、例えば、専門的な研修としましては、戸籍の研修、税の研修などがあります。一般的な対応能力を上げるためのクレームの対応の研修ですとか、メンタルヘルスの研修など、そのようなものが様々あります。","id":"exchange-040"},{"speaker":"横山委員","kind":"質問・要望","question":"ある一定の時間がかかるものですから、かつ、できるだけ早期に着手していただきたいと考えています。会計年度任用職員などの研修を受けやすくしていただくなど、さらに充実させていただきたいと考えていますが、区のお考えを説明を求めました。","respondent":"田口人材育成担当課長","answer":"私たちのほうからもリコメンドといいますか、推薦をするなど、受講について取り計らっていくことが必要だと考えております。","id":"exchange-041"},{"speaker":"横山委員","kind":"質問・要望","question":"やはり１年間ですとか２年間ですとか、区としても促してほしいと求めましたので、最後に一言お願いします。","respondent":"田口人材育成担当課長","answer":"なるべく正規職員との差をですが、正規職員と会計年度任用職員どちらも含めまして、今、キャリアプランを様々区のほうでも打ち出していますので、一緒になって考えていけたらと考えています。","id":"exchange-042"},{"speaker":"西村委員","kind":"質問","question":"１８５ページ、市町村交流事業、１９７ページ、町会・自治会加入促進支援について伺ってまいります。完全委託化とは、どのようなものか、令和５年度決算、６７２万円余のマウントしながわの活用状況と課題について伺います。","respondent":"勝亦総務課長","answer":"マウントしながわの里山再生活動ということで、年間４回、区のほうで募集をかけて、引率等を行って実施しています。直営事業で実施している中で、それから、いろいろな方に参加いただくような形をとりたいと考えております。","id":"exchange-043"},{"speaker":"西村委員","kind":"質問・要望","question":"契約期間もあるとは思うのですが、次の更新に向けての見直しも含めて検討してはいかがかというお考えをお聞かせほしいと求めました。こちらも併せてお考えを説明を求めました。","respondent":"勝亦総務課長","answer":"そういった考え方、豊かな自然に区民に触れていただくという考え方でやってありますので、こういったものは進めてまいります。委託等を検討していく中で、より多くの方に気軽に参加いただけるように、周知を広めてまいりたいと考えております。","id":"exchange-044"},{"speaker":"西村委員","kind":"提案","question":"ぜひともいま一度ご検討いただきたいと思っておりまして、見直しとともに、新たな取組に向けてもご提案をさせてほしいと求めました。特にテレワークの普及、ワーキングホリデーなど、働き方の変化もある中、新しい交流の形としてご検討ほしいと求めましたが、いかがか尋ねました。","respondent":"勝亦総務課長","answer":"そういった意味では、教育の部分等でも様々なテーマを持った交流の形が考えられるのかなと捉えてあります。今後、様々な手法を検討してまいりたいと思います。","id":"exchange-045"},{"speaker":"西村委員","kind":"提案","question":"次に、町会・自治会加入促進支援について伺ってまいります。区民まつりのある取組で、ＱＲコードを読み込み登録してくれたら練乳をプレゼントするという取組があったと伺っておりますとの意見を述べました。","respondent":"宮澤地域活動課長","answer":"配布しているうちわに、町会加入に向けたＱＲコードをつけて、すぐにでも加入ができるような形での取組をしております。町会・自治会の各イベント等でもできるような販促品といいますか、啓発品というものも検討していきたいと考えております。","id":"exchange-046"},{"speaker":"西村委員","kind":"質問","question":"その中で区の捉え方をお伺いしたいと思います。区内でも、この夏、盆踊りを展開する祭りが複数あったかと思いますが、盆踊りの開催件数も併せて説明を求めました。","respondent":"宮澤地域活動課長","answer":"これから実施される会場もありますが、１２会場で盆踊りを実施しておりますし、１０件の町会が盆踊り大会をやっております。今年新設した地域力連携促進補助金で、新たに３件の申請も今年度いただいているです。","id":"exchange-047"},{"speaker":"西村委員","kind":"意見","question":"この区内のお祭りに勢いをつけ背中を押してくれたのが、地域力連携促進補助金ではないかと考えています。実際の申請件数と、もともとの想定と比較した現状を説明を求めました。","respondent":"宮澤地域活動課長","answer":"地域力連携促進補助金、想定は年間１５件です。ただ、今年度、既にもう１２件の申請が来ているというところで、想定以上の取組が地域で行われているのかなと感じているところです。","id":"exchange-048"},{"speaker":"西村委員","kind":"質問・要望","question":"補助率の向上や見直しもご検討いただきたいと考えています。ご見解を説明を求めました。","respondent":"宮澤地域活動課長","answer":"地域力連携、地域の多様な主体と連携しながら、町会・自治会活動をということで推進していくためです。連携が次につながるというところで、地域のにぎわいや活性化にもつながると思いますので、今後の補助の拡充については検討と考えております。","id":"exchange-049"},{"speaker":"塚本委員","kind":"質問・要望","question":"１７３ページ、同じ１７３ページの行政評価から、主にはＩＣＴシステムの経費的なところについて伺っていきたいと思います。最初に、まず、この改定のポイントについて教えてほしいと求めました。","respondent":"吉岡政策推進担当課長","answer":"整備の方針を示すとともに、太陽光パネルの設置や、こういった促進する考え方も示しています。ＰＰＰ／ＰＦＩ手法導入優先的検討の考え方を整理いたしまして、本計画におきましても、その検討規定を加えさせていただいたところです。","id":"exchange-050"},{"speaker":"塚本委員","kind":"質問・要望","question":"これを区民のいわゆる要望とか、建て替えの目安とか、そういったことがしっかりと計画されるということが大事だと考えています。その点に関して、区の見解をお伺いしたいと思います。","respondent":"吉岡政策推進担当課長","answer":"当然、区民のニーズ、こういったものも大きく変化してきたところです。ますます検討を加速化させていく中で、こういったものも各自治体の事例も参考にしながら、しっかりと検討していく必要があると考えているところです。","id":"exchange-051"},{"speaker":"塚本委員","kind":"提案","question":"これはそうしてくれという要望とか提案ではなくて、１つの例として考えたことを少し話すと、品川区でやっているかと思います。意思決定プロセス、こういったことがどういうふうに進められていくのか、どういうふうな形で進められるのかということをお伺いしたいと思いますとの意見を述べました。","respondent":"吉岡政策推進担当課長","answer":"こういった施設が必要だと考えていくケースもありますし、こういった庁内連携、そういった部分をしっかりと検討していくというような体制です。","id":"exchange-052"},{"speaker":"塚本委員","kind":"質問・要望","question":"こういったことは機を逸せずにスピーディーに時代に対応して進めていっていただきたいということでお願いしたいと思います。点検等によって予防保全で修繕等が必要だとなってきたときの予算は、今、どのような形で措置されているのかお伺いしたいと思います。","respondent":"長尾施設整備課長","answer":"そういったタイミングで状況を確認しながら、施設整備課に施設の主管課から、どのぐらいの費用がかかるかというようなところの見積りの依頼が来ます。","id":"exchange-053"},{"speaker":"塚本委員","kind":"質問","question":"今のやり取りで査定がされて、必要な予算がこれだけですというものが決まったときに、それは、あらかじめ当初予算の中で、ある程度積まれているということでよろしいか尋ねました。","respondent":"長尾施設整備課長","answer":"査定がなされて、当初予算の中に組み込まれていくということになります。","id":"exchange-054"},{"speaker":"塚本委員","kind":"質問","question":"ということは、当初予算の中に入っていないと、補正予算とかという話にならざるを得ないという、こういう場合もあるということですか。それは工事の規模にもよるのでしょうか、その辺のことをもう少しお伺いしたいと思います。","respondent":"長尾施設整備課長","answer":"例えば設備とかになりますと、使っている中で予期しないような故障であるとか不具合は出てきます。そういった場合につきましては、補正予算を組んで対応などを行っている状況です。","id":"exchange-055"},{"speaker":"塚本委員","kind":"質問","question":"これが今年度、２年目になりますけれども、令和６年度になると７００万円ということで、前年度より３００万円プラスになっている。初期投資、次年度以降は比較的減少していくのかなという印象なのですけれども、この増額になっているのはなぜかということをお伺いしたいと思います。","respondent":"吉岡政策推進担当課長","answer":"重要度がより高いものを令和５年度に実施、残りの部分につきましては令和６年度に改修する予定というところで対応を進めたところでございまして、作業を進めていきたいと考えております。","id":"exchange-056"},{"speaker":"塚本委員","kind":"質問","question":"現状についての状況をお聞きしたいことと、こういったクラウド化によるメリットを生かしてのシステム経費の削減というようなことも１つあるのではないかなと思いますが、その点についてお伺いしたいと思います。","respondent":"横田デジタル推進課長","answer":"２点目のクラウドですが、区では外部委託利用実施手順を設けておりまして、順次クラウドのほうへ移行しております。なお、システム標準化におきまして、基幹システムにおきましては、順次、ガバメントクラウドへ移行していく予定です。","id":"exchange-057"},{"speaker":"おぎの委員","kind":"質問","question":"私からは、２１９ページ、マイナンバーカード普及促進、２２０ページ、統計調査費についてお聞きします。マイナンバーカードについてお伺いします。","respondent":"築山戸籍住民課長","answer":"マイナンバーの保有枚数率は７２.８％となっております。保険証との連携については、こちらでは把握しておりません。","id":"exchange-058"},{"speaker":"おぎの委員","kind":"質問","question":"区内の医療機関での使用の割合というものも、どうか尋ねました。","respondent":"築山戸籍住民課長","answer":"同様に把握はしておりません。","id":"exchange-059"},{"speaker":"おぎの委員","kind":"確認","question":"令和６年１２月２日以降、有効期限が切れても自動的に保険証の発行元から資格確認証が交付されますので、引き続き保険診療を受けることができます。２０２４年２月の通知により、それを解除することができ、送られてくる資格確認証により従来の紙の保険証同様に使うことができます。","respondent":"築山戸籍住民課長","answer":"保険証につきましては所管外ですので答えられない部分がありますが、マイナンバーの普及等につきましては、区ホームページですとか、そのほか、引き続きの交付、交付解除等で進めてまいります。","id":"exchange-060"},{"speaker":"おぎの委員","kind":"質問","question":"保険分野が管轄外ということですので、また追って保険の担当の方にも伺いたいと思います。それにより品川区民の生活を把握して事業の予算を算定していると思われますが、基準にしている品川区民のモデル家庭はあるのか尋ねました。","respondent":"宮澤地域活動課長","answer":"例えばですけれども、令和５年度に実施しました５年に一度の調査として、住宅・土地統計調査があります。国勢調査につきましては、全調査という形になります。","id":"exchange-061"},{"speaker":"おぎの委員","kind":"意見","question":"区民の生活に合った施策は自信を持って進めていただけると思いますので、機会がありましたら、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"のだて委員","kind":"質問・要望","question":"私たちが求めてきたことですので、やはりこの情報公開というのは、やはり区が保有している情報は区民の財産です。それはなぜなのか伺いたいと思います。","respondent":"與那嶺戦略広報課長","answer":"情報公開制度についてです。実施機関、区政の透明性を確保し、区民と区政の信頼関係の強化に資することを目的としているという形で定めているものです。","id":"exchange-063"},{"speaker":"のだて委員","kind":"質問","question":"私も一部ですけれども、世田谷区や杉並区の条例を見ましたけれども、そこには、知る権利のことや、区政参加のことが書かれております。品川区の条例には書いていないということで、そうした姿勢が欠けているのではないかと思うのですが、なぜ書かれていないのか伺いたいと思います。","respondent":"與那嶺戦略広報課長","answer":"品川区情報公開条例の目的として、区民の行政情報の公開を求める権利を保障するですとか、区政の透明性を確保するというところもあります。そこの趣旨といたしましては、区民の知る権利であるとか、区政参加というところについて包含しているものと考えています。","id":"exchange-064"},{"speaker":"のだて委員","kind":"質問・要望","question":"こうした区政の情報は区民のものという姿勢で情報公開の徹底をしていただきたいと思うのですけれども、いかがでしょうか。様々報告書などを情報公開しても、やはりそうしたところも情報公開を徹底していただきたいと思うのですけれども、いかがか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"非公開についての考え方ですが、まず、品川区情報公開制度におきましても、まず、行政情報は公開が原則です。公開の範囲におきましては、情報公開の実施機関である各所管課において適切に行われるものと認識しております。","id":"exchange-065"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ公約の観点からも、情報公開をさらに進めていただきたいと思うのですけれども、いかがでしょうか。このままだと公約に反するものではないかと思いますけれども、いかがか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"繰り返しになりますけれども、情報公開制度におきましては、行政情報は原則公開の考えを持って行っております。その上で、非公開条項が定められているものにおいては、それぞれ適切に判断されているものという形で運用しているものです。","id":"exchange-066"},{"speaker":"のだて委員","kind":"質問","question":"法人の利益を害するということと、区民の間に混乱を生じさせることを理由に、９９％黒塗り非公開というふうに出てきました。条例でも区政の透明性確保と書かれておりますが、透明性が確保されていると、これで言えるのか伺いたいと思います。","respondent":"與那嶺戦略広報課長、泉広町事業調整担当課長","answer":"あくまでそこの公開の範囲、そして非公開情報の確認におきましては、それぞれ業務を所管している部署のところで適切に判断しているものと考えています。区民の皆様にご説明をしたり、公開すると区民の皆様に混乱を生じさせるおそれがあるという場合には、非公開としている事例があります。","id":"exchange-067"},{"speaker":"のだて委員","kind":"質問","question":"準備段階の場合は公開しないと言いますけれども、そうなると、計画段階から住民参加、区民参加を保障されていないということになると思いますが、いかがか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"まだ検討が深まっていないというようなところの内容も含まれてありますので、一定程度、まとまりを見せた段階で区民の皆様にお示しをするというところで進めてまいりたいと考えています。","id":"exchange-068"},{"speaker":"のだて委員","kind":"質問・要望","question":"一般質問でも全国の９９％の首長が参加する平和首長会議が、核抑止論から脱却をするとか、核兵器禁止条約への参加を国に求めるということで。実際そうした危険なことになると、区はそのときも何も言わないのか伺います。","respondent":"勝亦総務課長","answer":"平和首長会議におきましては、加盟都市において、それぞれ連帯交流を図りながら、それぞれの自治体の平和施策を進めていくものと考えております。２点目、石破新政権の話ですけれども、安全保障に関することは国の事項と考えております。","id":"exchange-069"},{"speaker":"ひがし委員","kind":"質問","question":"１８７ページ、２１５ページ、順不同で質問をします。区としても一丸となり取り組むべきだと考えますが、この住民票の続柄の課題に対する検討状況、今後の方針等について、答えるよう求めました。","respondent":"築山戸籍住民課長","answer":"積極的に検討を進めてきたところですが、法制度上、（未届）の記載ができないという判断をせざるを得なくなったところです。９月に人権・ジェンダー平等推進課と連携し、戸籍住民課全職員を対象にして、ジェンダー平等と性の多様性について研修を行ったところです。","id":"exchange-070"},{"speaker":"ひがし委員","kind":"質問・要望","question":"国にも意見書を出そうか、要望書を検討しているということでしたので、ぜひその点についても積極的に進めていただきたいとお願いを申し上げます。次に、東京都パートナーシップ宣誓制度活用経費について伺います。","respondent":"木村人権・ジェンダー平等推進課長","answer":"その結果として、１月末に確認したときよりも増加している、７か月程度で少し増加があったというところで考えております。支援する方々も含め、今年度は４回開催する予定で、今週末も開催する予定です。","id":"exchange-071"},{"speaker":"ひがし委員","kind":"質問","question":"現在、みんなのひろば、そして、このような講座があって、どういうふうに実態として動いていけばよいかと講師の方にも相談をさせていただきました。そういうようなグッズみたいなものを品川区でも検討できないかなと思いますが、まず、その点についていかがか尋ねました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"過去２回、そういう方々と、今後についてもお話し合いながらやらせていただければと考えております。グッズに関しましては、今後、検討させていただきたいと思います。","id":"exchange-072"},{"speaker":"ひがし委員","kind":"提案","question":"申請をデジタルで行って、デジタルで物が来る、あまり婚姻したというような形がない、少し寂しく感じるというご意見も伺っています。具体的な提案としては、例えば、今、婚姻届を出すと、撮影ブースがありますよねとの意見を述べました。","respondent":"築山戸籍住民課長","answer":"記念品については、婚姻届と連動し、男女の婚姻を前提としたものを現在提供しているところです。同性パートナーも含め、どなたでも利用しやすくなるよう、環境の提供をしてまいりたいと考えております。","id":"exchange-073"},{"speaker":"ひがし委員","kind":"意見","question":"もし戸籍住民課のほうで難しければ、場所はジェンダー平等推進センターでもよいのかなと思います。冊子というところも検討していただければいいのかなと思うので、ぜひ違う課の課長、お答えほしいと求めました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"はない状態ではありますが、それに対してのお祝いというか、そういった形で何か気持ちをあらわせるようなことができればと考えております。","id":"exchange-074"},{"speaker":"ひがし委員","kind":"質問・要望","question":"まずは利用を進めていくということでしたので、そこの利用だけでは足りないというところを、しっかり区としても取り組んでほしいと求めました。区としての発信も力を入れていただければなと思いますので、この点、要望でとどめします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"中塚委員","kind":"質問","question":"この大量購入はなぜなのか、いつからなのか、伺います。こうした大量購入は、部落解放同盟だけなのか、私はやめるべきだと思いますが、いかがか尋ねました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"いつからかというところから先にお答えしますが、大変申し訳ありません、こちらについてはお答えが難しいところになります。かなり昔からありますし、今でも続いている問題になりますので、こちらの新聞をとって管理職の方々への人権意識の醸成に努めているところです。","id":"exchange-076"},{"speaker":"中塚委員","kind":"質問・要望","question":"改めてやめるべきだと思いますが、伺います。そして、こうした大量購入は、解放新聞だけだと私は思いますが、先ほども伺いましたが、答えるよう求めました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"知っておかなければならない情報について、繰り返し掲載されているものになりますので、こちらをもって管理職の皆様には人権意識を醸成していただくという考えで購入をしています。","id":"exchange-077"},{"speaker":"中塚委員","kind":"質問・要望","question":"引き続き、この問題は取り上げていきたいと思いますが、ぜひ購入はやめていただきたいと改めて求めたいと思います。条例に基づいて主催者とよく話合い、今日的にふさわしい祭りの在り方を検討すべきだと思いますが、いかがか尋ねました。","respondent":"小林地域産業振興課長","answer":"２日間にわたるお祭りでは、旧東海道の地域の特性、町並みを生かしたものです。地域活性化につながっていく、そういう趣旨で行われるイベントということで、区も後援を行っているところです。","id":"exchange-078"},{"speaker":"中塚委員","kind":"質問・要望","question":"私は、今日的にふさわしい祭りの姿を丁寧に検討すべきだと思います。ぜひ主催者と話し合っていただいて、検討していただきたいと求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"えのした委員","kind":"質問","question":"私からは、２１１ページの地域スポーツ等推進経費についてお伺いします。対象者、また、令和５年度の実績などもご説明お願いします。","respondent":"三井スポーツ推進課長","answer":"こちらは、全国規模の大会に出場する１８歳以下の子どもたちを対象に、出場に係る負担の軽減や競技力の向上を図るための助成制度となります。","id":"exchange-080"},{"speaker":"えのした委員","kind":"質問","question":"品川区を代表して頑張っている少年少女への支援は大変重要だと考えております。対象になるのは全国大会規模と言っておりますけれども、こちらの意味の中には、世界大会も入るという理解でよろしいのか尋ねました。","respondent":"三井スポーツ推進課長","answer":"世界大会も含まれております。","id":"exchange-081"},{"speaker":"えのした委員","kind":"確認","question":"確認が取れました。４年後、ロサンゼルスの２０２８オリンピック・パラリンピックを目指す品川のトップアスリートを応援する意味で、区のご見解をお伺いいたします。","respondent":"三井スポーツ推進課長","answer":"プロスポーツクラブと連携してプロスポーツ教室などを実施しておりますが、アスリートの方をどのように支援していくことが有効なのかということについて、いろいろな方策を探ってまいりたいと考えております。","id":"exchange-082"},{"speaker":"えのした委員","kind":"質問・要望","question":"デフリンピック認知度１２０％プロジェクトでもこういうものが活用されておりますし、区民との交流事業など、要望します。アンケート等質問がありましたが、私も当日お伺いさせていただいて、こちらの取組についてお知らせください。","respondent":"三井スポーツ推進課長","answer":"今回、パラスポーツチャレンジデーでは、デフリンピックの開催１年前記念としまして、デフリンピックの取組も行いました。」というダンスがあるのですが、そちらのイベントを実施するなど、全体的にデフリンピックの啓発をしておりました。","id":"exchange-083"},{"speaker":"えのした委員","kind":"質問","question":"私もお伺いしたのですけれども、しゅわしゅわダンスですか、昨対で来場者が１.６倍ぐらいの参加人数ということをお伺いいたしました。私は昨年もお伺いさせていただきましたが、肌感覚でも来場者が増えていると実感しております。","respondent":"三井スポーツ推進課長","answer":"今年度は、パラスポーツチャレンジデー内で試行的にスリー・オン・スリーの小学生向けのミニバスケ大会を実施しまして、参加した子どもたちは。","id":"exchange-084"},{"speaker":"えのした委員","kind":"質問","question":"そうすると、地域を巻き込んで、近隣の方も来場が増えると感じておりますので、そちらのほうも引き続き前向きにご検討ほしいと求めました。先ほどもお伺いしましたが、今後の目標などがありましたら、お知らせください。","respondent":"三井スポーツ推進課長","answer":"今回、パラスポーツチャレンジデーを皮切りに、９月末にはホッケー教室内で手話でサッカーというものを初めて実施させていただきました。えばら」というような文化イベントでも、同時にデフスポーツの啓発イベントも実施していくことを計画しております。","id":"exchange-085"},{"speaker":"えのした委員","kind":"意見","question":"続きまして、品川区は、８月に公式デフリンピックサポーターを任命されました。今後は公式サポーターをどのように活用していくのか、目標などございましたら、お知らせくださいとの意見を述べました。","respondent":"三井スポーツ推進課長","answer":"今回、例えば、先ほどご説明した１０月のデフサッカー日本代表エキシビションマッチも植松隼人さんにお越しいただくことになっております。","id":"exchange-086"},{"speaker":"えのした委員","kind":"質問","question":"手話教室をイベント等で行っていると参加がしやすいと思いますので、そちらのほうも引き続き取り組んでほしいと求めました。デフリンピック認知度１２０％、何かこれからの意気込み等がございましたら、いただけますか尋ねました。","respondent":"三井スポーツ推進課長","answer":"１００％より上ということで、そういうものを含めて深めていただきたいということで１２０％としておりますので、部として積極的にデフリンピック啓発をしていきたいと考えております。","id":"exchange-087"},{"speaker":"やなぎさわ委員","kind":"質問","question":"私からは、２１５ページのふるさと納税と、２１１ページのしながわシティランについて質問します。現在、大井競馬場に関連するふるさと納税の返礼品はどのようなものがありますか尋ねました。","respondent":"吉野税務課長","answer":"お食事がついた観覧ということで、今、展開しております。","id":"exchange-088"},{"speaker":"やなぎさわ委員","kind":"質問","question":"「ウマ娘」というアニメ、そしてスマホのアプリをご存じでしょうか。質問なのですけれども、もしくはバックヤードツアーなどを企画してみてはいかがかと思うのですが、いかがか尋ねました。","respondent":"吉野税務課長","answer":"それに関しまして抜本的な見直しは継続的に進めていくのですけれども、利用して、品川区の魅力をどんどん発信していきたいと今考えているところです。","id":"exchange-089"},{"speaker":"やなぎさわ委員","kind":"提案","question":"ぜひ前向きに参考にしていただければと思っているのと、加えて提案したいのが、競馬のレースの命名権なのです。いつでもできるかなと思っているのですけれども、こういったこともルール的には可能なのかお伺いしたいのですけれども、いかがか尋ねました。","respondent":"吉野税務課長","answer":"ふるさと納税自体が地場産業という形になりますので、大井競馬場でやれば、それは可能かと思います。","id":"exchange-090"},{"speaker":"やなぎさわ委員","kind":"質問","question":"先ほど例に挙げたのは、品川区の１日を使ってといいますか、それだけでも大分ふるさと納税の起爆剤になるのではないかと個人的には思っております。このたび追加されたと思うのですが、セガサミーを選ばれたのは、品川区に本社があるからということでよろしいか尋ねました。","respondent":"吉野税務課長","answer":"委員のおっしゃるとおり、本社が品川区にある企業であれば、こういったところのイベントを展開できます。","id":"exchange-091"},{"speaker":"やなぎさわ委員","kind":"提案","question":"私がさらに提案したいのは、同じセガサミーというところで、もう１つ所有しているプロチームがあります。この２年間で爆増しているということで、セガサミーのプロの選手にマージャンを教えてもらうみたいな、そういった検討の余地はいかがか尋ねました。","respondent":"吉野税務課長","answer":"今、委員がおっしゃっていただいた内容なのですけれども、検討できるかと思います。","id":"exchange-092"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"しながわシティランなのですけれども、委員の皆さんにお伺いしたいのですけれども、しながわシティランに登録された方はおられますでしょうか。そういった方も含めて、やはり第１回ということなので、皆さん、周知に力を入れてほしいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"},{"speaker":"こんの委員","kind":"質問","question":"２０１ページ、２２１ページ、順不同で質問をします。現在の取組も含めて、こうした課題についてのご見解をまず説明を求めました。","respondent":"今井選挙管理委員会事務局長","answer":"この郵便投票のいわゆる障害の程度や要介護度のところを拡大していけないかというような要望も出ているところ、検討がされているところです。介護保険制度や同行援護の中での移動支援、サービスなどを、それぞれの所管課と連携してご案内している状況です。","id":"exchange-094"},{"speaker":"こんの委員","kind":"質問","question":"もう１つ、予約制で有権者の自宅を巡回するなど、移動投票所の導入に向けたマニュアルが製作されております。いわゆる投票所まで行くアクセスの支援、こうしたことを今後考えていくことが必要ではないかと思いますが、いかがか尋ねました。","respondent":"今井選挙管理委員会事務局長","answer":"アトレなどの民間施設での実施ですとか、つくば市で導入を検討されておりましたが、実施見送りになったところです。事務連絡によりまして、全国の自治体でそれぞれの事情に応じて、公選法の規定の中で実施できるようになったものと認識しております。","id":"exchange-095"},{"speaker":"こんの委員","kind":"意見","question":"国がそういう働きかけを全国自治体にされるということですので、そうしたことでお願いしたいと思います。ご答弁をもう一度お願いしたいと思いますとの意見を述べました。","respondent":"今井選挙管理委員会事務局長","answer":"地域の皆さんもたくさんいらっしゃいますので、いろいろな効果を通して、どのような形が実現可能か検討させていただきたいと考えています。","id":"exchange-096"},{"speaker":"こんの委員","kind":"質問・要望","question":"参考までに伺いたいのですが、これは人材派遣なども活用していると思われますけれども、どのような雇用方法で確保されているのか。代替職員雇用経費の中で、今回は３,１２９万円余の決算が出ておりますので、参考までに伺いたいと思います。","respondent":"宮尾人事課長","answer":"対応している方法ですけれども、人材派遣を活用する、このような方法で対応しています。令和５年度は、延べ２５人、１０９月の実績がございました。","id":"exchange-097"},{"speaker":"こんの委員","kind":"質問","question":"ほかの例でいきますと、そうした経費に使われているのだと思いますが、人材を確保するためには本当に大変なのだなという現状を参考までに伺いました。引き続き、確保を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-098"},{"speaker":"石田（し）委員","kind":"質問","question":"１８６ページ、１８１ページ、ＩＣＴ推進管理費についてお伺いします。私は子どもたちに見せたくないなと思うのだけれども、その点について、どのように考えるか説明を求めました。","respondent":"河合生活安全担当課長","answer":"喫煙者が減ってきて１５％を切るような形ではありますが、やはり実態として喫煙所が足りないという認識しています。公設の喫煙所の整備もあまり進んでいないというところで、やはり民間の力をお借りして拡大していくというところは、方針としてやるところです。","id":"exchange-099"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"実は苦情も来て今回この質問をしていますけれども、ぜひそういった部分も考えてご検討ほしいと求めましたが、その点も併せてお聞かせください。今回、令和５年度の給料について、前年度と比較をしてどのような推移になったのか説明を求めました。","respondent":"河合生活安全担当課長、宮尾人事課長","answer":"区内全体をバランスよくというところで、連携しながら、情報共有しながらやっているところです。ほかのところで、公園が活用できるようなところだったら、まちの声を聞いて再開ということで連携してやっていきたいと考えております。 人件費に関するお尋ねです。令和４年度が１３.４％ですので、ポイントとして０.６ポイントほど歳出総額に占める人件費が下がっているという令和５年度決算の状況です。","id":"exchange-100"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それは、月例給を平均２.６８％、１万５１４円、期末・勤勉手当（ボーナス）を０.１か月分、それぞれ引き上げるよう求めました。しっかり職員の皆さんの給料を上げていく必要があると思いますが、この千葉市の件も含めて、どのように考えているのか説明を求めました。","respondent":"宮尾人事課長","answer":"給料がどのぐらいの水準であるかというのは、学生を含め、本当に大きな興味関心事として見られています。品川区が１区で単独で、少しでも職員の働く環境の魅力の向上、そういうところも含めて取り組んでまいりたいと考えております。","id":"exchange-101"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"言葉１つとっても、そういった様々な事業を見ても、その入口がどこにあるのかがなかなか分かりづらいと思うのです。アプリ１つとっても、区民にとってもサービスが向上するのではないかと思うのですけれども、その辺の考えを説明を求めました。","respondent":"西澤ＤＸ戦略担当課長","answer":"今、品川区のホームページで、チャットボットだとか、そういったもののリンクを貼っておりまして、そこから見られるようにしております。さらに、こういったところの利便性を向上させるために、ホームページの検討などといったところを進められればいいなと考えています。","id":"exchange-102"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"区役所は必要なくなってくるのではないかなと思うので、ぜひそういった部分も含めて、ＤＸ化をさらに進めてほしいと求めました。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"２１９ページ、斎場運営費、２１７ページ、住居表示管理事務費についてお伺いいたします。年間６１０件の葬儀が可能ですよとはうたわれているのですけれども、やはり利用件数５００件と出ているので、その辺についてお伺いしたいと思います。","respondent":"築山戸籍住民課長","answer":"こちらにつきましては、現在、検討を進めているところです。６から７割が２０人以下、２割から３割が１０人以下といったような形で、式に参列する方も少なくなっているといった状況があります。","id":"exchange-104"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それと、２１７ページ、住居表示管理事務費についてお伺いいたします。これについて、これは間違いないのかということを確認させてほしいと求めました。","respondent":"築山戸籍住民課長","answer":"こちらは、区が電話で２３区に調査したところ、枝番号の付番を行っている自治体は１２区ございました。利用件数につきましては、年一、二点、多くても四、五件という状況です。","id":"exchange-105"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"確認できました。ぜひともこれ、事務がより一層効率化すると思いますので、令和５年度の実績以上に、令和６年度もぜひ実績を上げてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"},{"speaker":"鈴木委員","kind":"質問・要望","question":"２０３０年の目標も、さらに５０％よりも引き上げて、実効ある取組が求められていると思っています。３９施設中、設置可能が２７施設ということで、その点についても伺います。","respondent":"長尾施設整備課長","answer":"こちらの調査結果につきましての報告というところですけれども、こちらについては少し検討させていただきたいと思います。調査対象の中で実際に設置が可能という結論になりましたのは２７施設となっておりますが、太陽光パネルを順次設置していきたいと考えております。","id":"exchange-107"},{"speaker":"鈴木委員","kind":"質問・要望","question":"しっかりと計画を作って、私は公表もしていただきたいと思っているのですが、その点を伺いたいと思います。私は、エコルとごしのような建物にすることが必要なのではないかと思っているのですけれども、その考え方についても説明を求めました。","respondent":"長尾施設整備課長","answer":"特に個別につくる予定はございませんが、区有施設におきましても、順次計画的に太陽光発電設備を設置していく予定としております。ＺＥＢ認証取得を令和１２年度までに１２施設と定めておりますが、そこにとらわれることなく積極的に検討を進めていきたいと考えております。","id":"exchange-108"},{"speaker":"鈴木委員","kind":"質問・要望","question":"できる限りの、区としてできる公共施設というところで取組を進めていただきたいと強く要望しておきます。それから、会計年度任用職員の中で、女性の占める割合も伺います。","respondent":"宮尾人事課長","answer":"それから、会計年度任用職員の中で女性の占める割合ですけれども、１,１８５人、率にして８０.９％です。一定程度、採用の質を確保するという意味でも、現行の取組をしっかりと継続してまいりたいと考えています。","id":"exchange-109"},{"speaker":"田中委員","kind":"質問・要望","question":"私は、２０３ページの観光資源整備事業、１８３ページの二十歳の集い式典経費、２１８ページの選挙費に関連してお伺いしたいと思います。それで、決算なので、まずは先に確認をしますが、ハタチの龍馬ＰＲ事業があります。","respondent":"大森文化観光戦略課長","answer":"その動画を冊子にしたものですとか、ハタチの龍馬のＸによるつぶやき等を年間１５０件程度上げている。そのほか、クリアファイル等の作成をしています。","id":"exchange-110"},{"speaker":"田中委員","kind":"質問・要望","question":"そういう歴史的な財産と資源をより積極的に有効に生かしていくべきという思いの中で言うと、例えば１人は、石破総理が誕生しました。より積極的に観光資源の１つとして、ぜひ生かしていただきたいと考えていますが、いかがか尋ねました。","respondent":"大森文化観光戦略課長","answer":"伊藤博文公の西大井六丁目に、正確には、ご夫婦の墓所になるかと認識しています。そういった３か所を回って西大井に行くというところでも、今後、観光協会等と連携しながらＰＲに努めてまいろうかと思います。","id":"exchange-111"},{"speaker":"田中委員","kind":"質問・要望","question":"板垣退助も有効に観光資源にぜひ生かしてほしいと求めましたが、このときに、今までは参政権は２０歳以上でありました。今は１８歳以上でありますけれども、より理解を示していただくように働きかけるべきだと思いますが、それぞれお答えをほしいと求めました。","respondent":"大森文化観光戦略課長、勝亦総務課長","answer":"観光面という部分では、先ほども説明しましたが、ハタチの龍馬の動画等を作っております。関係者や管理者の許諾が取れれば、ぜひそういったところを動画等で取り上げさせていただきたいという候補に挙がってくることと存じます。 二十歳の集いに関わらず、選挙権の啓発等は非常に大事なことだと考えています。選挙管理委員会事務局とも調整しながら、啓発等を行ってまいりたいと考えております。","id":"exchange-112"},{"speaker":"吉田委員","kind":"質問","question":"私からは、１７９ページの情報公開等経費、１８９ページの職員研修費について伺います。職層研修の中に、多分ここでそういう決裁権者の研修も行われていると思うのですけれども、その点について、どのような研修が行われているか伺います。","respondent":"田口人材育成担当課長","answer":"改めて基礎の１つ１つをやっていくというよりは、公務員としての全体の奉仕者としてしっかりと見ていくというような、そのような精神的な面について主に改めて学習をし直しています。","id":"exchange-113"},{"speaker":"吉田委員","kind":"質問","question":"どこに視点を持つべきかとか、その結果、細かい不適切文書もいろいろあるのです。そういうことが実際に起きているということでは、その研修についても見直す必要があるのではないかなと思いますが、その点についていかがか尋ねました。","respondent":"田口人材育成担当課長","answer":"研修の見直しについてですが、研修について、中身自体は随時見直しをしています。不適切なということで、そういうところをしっかり解決できて共有できる、そういうような環境づくりをしていくことが必要であると考えております。","id":"exchange-114"},{"speaker":"吉田委員","kind":"質問・要望","question":"こういうことがあったということは、あまり暴き立てるべきではないと思ったので言わなかったのですけれども、よろしくお願いいたします。もし今の検討状況とか、ご報告いただけることがあったら、教えてほしいと求めました。","respondent":"田口人材育成担当課長","answer":"コンプライアンスについての研修ですが、まずは今年度、ｅ－ラーニングによりまして、全職員に対してコンプライアンスの研修を必修で、まさに現在、実施をしています。","id":"exchange-115"},{"speaker":"吉田委員","kind":"提案","question":"それを確認したかったので、原則情報公開ということでよいですね。品川区の情報公開条例の第７条(2)につきましても、限定的に解釈をしていただきたいと思うのですが、いかがか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"情報公開制度についてのご質問にお答えいたします。情報公開制度の趣旨に鑑みて、公開してよい範囲というところについては、それぞれの所管部署において適切に判断されていくものと考えております。","id":"exchange-116"},{"speaker":"吉田委員","kind":"質問","question":"その中で、すごく広く解釈されてしまうと、本当にどこが原則公開なのだという感じに思えてしまうわけです。例えばこういうものということをきちんと明記して、それ以外のことは公開というように判断するべきだと思うのですけれども、いかがか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"委員のおっしゃるとおり、まず、情報公開制度を区の各機関が正しく理解して制度を運用していくことが大事なことだと認識しています。こういった法令に関する部分については、そういったものも活用しながら適切に制度が運用できるように我々としてもサポートしたいと考えています。","id":"exchange-117"},{"speaker":"吉田委員","kind":"確認","question":"品川区の場合、それぞれの所管に対して情報公開請求をいたしますので、そこの解釈が入ってしまっているようなことも少し感じたりするのです。でも、基本は、大きく品川区全体としての方針を持っているということで確認させていただいてよろしいか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"委員おっしゃるとおりです。","id":"exchange-118"},{"speaker":"吉田委員","kind":"質問","question":"区としての大きい方針は定めるべきというようなことについて、あと、それぞれの所管に任せているというようなご答弁が今まであったのです。やはり所管に任せるべきところと、区全体としての方針をきちんと定めているという認識でよろしいか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"繰り返しの答弁にはなってしまいますけれども、委員ご認識のとおり、制度の運用については各所属のところで適切に判断していくところではあります。","id":"exchange-119"},{"speaker":"吉田委員","kind":"確認","question":"最初の質問に戻ってしまうのですけれども、区全体でしっかり研修を進めながら、みんなで認識していくという考えでよろしいでしょうか。その点について、最後に確認させてください。","respondent":"與那嶺戦略広報課長","answer":"こちらも先ほど少し触れた内容ではありますが、情報公開制度の各所属においての理解を深めていくということは非常に大事なことだと考えています。引き続き、各部署において適切に事務が執行できるよう、こちらとしてもサポートしたいと考えております。","id":"exchange-120"},{"speaker":"若林委員","kind":"質問・要望","question":"一般質問でも港区の調査の概要もお知らせしながら質問しましたけれども、ここら辺についての考え方も併せてこの際伺っておきたいと思います。そこで、今後見直すということであれば、どのようなことを盛り込むのかということも、方向性を確認させてほしいと求めました。","respondent":"河合生活安全担当課長","answer":"やはり設置費用というよりも維持管理の助成の金額が大事だという声がありますので、維持管理のほうの引き上げを検討してまいりたいと考えております。そういったところを、区民、町会の声を聞きました上で検討してまいりたいと考えております。","id":"exchange-121"},{"speaker":"若林委員","kind":"質問・要望","question":"あの近くに住んでいる方から、昨日の夜も電話があったのですが、いわゆるあそこ、あそこという言い方でよいでしょうか。「どこですか」と言ったら、そこは１つ大きなポイントかなと、また力を入れてほしいと求めました。","respondent":"河合生活安全担当課長","answer":"１点目、今、進めているところです。こちらも連携しながらというところで、連携しながら、両方が住みやすい町になるように努めてまいりたいと考えております。","id":"exchange-122"},{"speaker":"若林委員","kind":"質問","question":"１点だけの質問になると思いますけれども、Ａ４判かＡ５判の黒い背景がありまして、品川区の認識あるかどうか。３年前ですけれどもパラリンピックが９７.９％、デフリンピックは１６.３％の認知しかないということで、一言お願いします。","respondent":"三井スポーツ推進課長","answer":"品川区聴覚障害者協会から、そういうものがあるということは聞いております。","id":"exchange-123"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろと、それに続けて、少し深掘りをしたいのと、確認をさせていただきたいことが多々出てまいりましたので、まずそこをしたいと思います。それを確認したいと思います。","respondent":"吉岡政策推進担当課長","answer":"まず、有償による賃貸借契約、自由に内装工事を行ってよいこと。これらの内容を受けて、区として、当該物件の活用可能性の検討を開始したです。","id":"exchange-124"},{"speaker":"西本委員","kind":"質問","question":"公式文書とは何ですか。効力のない公式文書とは何か尋ねました。","respondent":"吉岡政策推進担当課長","answer":"こちらの所有者のほうで行った契約書において、「遺贈」という文言があったとしても、そこに法的拘束力がないということで発言をしたものです。","id":"exchange-125"},{"speaker":"西本委員","kind":"意見","question":"そこをはっきりしてほしいのです。そこはもう少しはっきり言ってくださいとの意見を述べました。","respondent":"吉岡政策推進担当課長","answer":"午前中のところでも申し上げたとおり、これから公正証書遺言を作成するということで、本人からお約束をいただいているところです。ですので、そちらのほうで、こちらの遺贈が１００％、非常に高い可能性でなされるというふうに区として考えているところです。","id":"exchange-126"},{"speaker":"西本委員","kind":"質問・要望","question":"だから、先ほど答弁があった関係ありませんというのは、少し違うのではないでしょうか。そのご見解をほしいと求めました。","respondent":"吉岡政策推進担当課長","answer":"従前から、品川区の執務スペース、こういった不足のところからお願いしてきたところです。こちらが地域の方や商店街の方、こういったところでも公益性が担保できると考えているところです。","id":"exchange-127"},{"speaker":"西本委員","kind":"意見","question":"１００％品川区の税金を使って運営していただいて、それで今回の移転も、品川区から言ったわけです。そこはどう考えていますかとの意見を述べました。","respondent":"吉岡政策推進担当課長、勝亦総務課長","answer":"国際友好協会の移転に関して、区が関係ないということは全く申し上げていると思っておりません。総務委員会のほうでも、国際友好協会の移転についてはご報告を差し上げたところです。 国際友好協会と料亭「秀」との賃貸借契約について、区は関係ないということではなく、遺贈に関しては、国際友好協会の賃貸借契約には関わる話ではないので、賃貸借契約に記載していないということを申し上げたまでです。","id":"exchange-128"},{"speaker":"西本委員","kind":"質問","question":"これからどうなっていくのか、契約書も含め、しっかりと透明性ある形で区議会のほうに提示していただくことは可能なのですね。そうお考えであるという認識でよろしいか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"所有者の方に申し訳ないという気持ちがありますので、そちらについては、お気をつけていただきたいと思います。","id":"exchange-129"},{"speaker":"石田（秀）委員","kind":"確認","question":"私からは、２１５ページ、ふるさと納税について伺っていきたいと考えています。だけれども、１つだけ確認したいのは、ふるさと納税、出るものが多いわけでありまして、ここに手を入れなければならないわけです。","respondent":"吉野税務課長","answer":"本制度は、対応は税務課が企画経営部に入ることによりまして、全庁的な視点を持つことができました。いろいろな課が連携しておりますので、そういった意味でいきますと、全庁的にみんなで対応しているというようなことになります。","id":"exchange-130"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"でもう１回お答えいただきたいのですが、税務課がやられているけれども、全庁的にやられるのだ。やはり中途採用、１,０００万円ぐらいもらっていらっしゃるという話だったけれども、その１,０００万円がどうという話ではない。","respondent":"久保田企画経営部長","answer":"企画課と財政課、また、その他関係する部署で連携して全庁的な対応ができていると我々は認識しております。組織や人材の件につきましても、我々も引き続き検討していく必要があると考えているところです。","id":"exchange-131"},{"speaker":"石田（秀）委員","kind":"質問","question":"外部人材を入れてとか、私は兼務はやめて専任だと思っているので、そこら辺の考え方も教えてください。１分半ぐらいあるので、お答えがなかった部分と、今の話をぜひ。","respondent":"久保田企画経営部長","answer":"認識、考えているところですので、今後の検討になるのかなと考えているところです。それと、国にきちんと要望を伝えて、制度の改正の見直しも抜本的に行っていただきたいということも訴えていきたいと考えているところです。","id":"exchange-132"},{"speaker":"石田（秀）委員","kind":"意見","question":"計画する、兼務を解くのか、外部人材を入れるのか、検討してと言って、もう１年ですよ。だけど、やっと少しずつ、動き出したことについては、よいと思っているので、ぜひとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-133"},{"speaker":"高橋（し）委員","kind":"質問","question":"昨年度の１２月に区のホームページで公表されていますが、これは人事管理費のどの事業に該当するのでしょうか。経費がかからないように、人事課の職員の方が更新作業をしているのか、お尋ねします。","respondent":"宮尾人事課長","answer":"今、委員お尋ねのありました人事行政運営の公表ですけれども、特に何か委託をして経費を使わせていただいているとか、そういうことではなく、職員が手作りでといいますか、自らの手で作らせていただいているところです。","id":"exchange-134"},{"speaker":"高橋（し）委員","kind":"質問","question":"１９２名。職層別がどのようになっているのか、資料の中に載っていないため、検討の余地があるかと思いますが、いかがか尋ねました。","respondent":"宮尾人事課長","answer":"記載内容に関するお尋ねです。より分かりやすい、見やすい表示となるように、今後努めてまいりたいと思います。","id":"exchange-135"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"少し質問を変えますが、令和５年度中の退職者のうち、その人数を教えてほしいと求めました。特別職の方も退職していると思いますので、同様にお伺いします。","respondent":"宮尾人事課長","answer":"常勤の正規職員で５名でございまして、それぞれ区内の法人等で再就職をしています。特別職の方についても１名おりまして、区内の関連団体に再就職をしています。","id":"exchange-136"},{"speaker":"高橋（し）委員","kind":"質問","question":"今、お辞めになった方の人数と、区内の法人等というお話があったのですが、具体的にどのような団体なのかお尋ねしたいと思います。公表すると、何らかご都合が悪いことがあるのか尋ねました。","respondent":"宮尾人事課長","answer":"例えば、しながわ観光協会、福栄会、三徳会等です。","id":"exchange-137"},{"speaker":"高橋（し）委員","kind":"質問","question":"私は、昨年の第４回定例会の一般質問でお話しして、詳細はご存じかと思いますので、省略いたします。どのような研究をされているのかお伺いします。","respondent":"宮尾人事課長","answer":"地方公務員法で退職の適正な管理を確保するということが求められております。他自治体の内容ですとか、方法ですとか、そういったものも含めて検討を進めているところです。","id":"exchange-138"},{"speaker":"高橋（し）委員","kind":"質問","question":"早い時期に議案の検討が必要だと思いますが、改めて人事当局のお考えをお伺いします。所属されている品川区も、当然そういった制度を整える必要があると思いますが、いかがか尋ねました。","respondent":"宮尾人事課長","answer":"公表も含めまして、法に求められている適正な退職管理というテーマに沿って、どういったやり方でそれが達成できるかというところを、まさに今、検討しています。","id":"exchange-139"},{"speaker":"高橋（し）委員","kind":"意見","question":"ということは、まだまだ研究をするということなのか、それとも、どれぐらいのスパンで迅速に進めていくのかというところをまた１つお尋ねします。いま一度お願いしますとの意見を述べました。","respondent":"宮尾人事課長","answer":"適正な退職管理の中で、項目として出ております届出、それから公表というところに向けては、具体的に手法も含めて、今まさに検討しています。","id":"exchange-140"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ぜひ早期に退職管理の条例制定と、管理職退職者の再就職先、その公表を実施することを求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-141"},{"speaker":"松本委員","kind":"質問","question":"私からは、１７２ページ、財政管理費、２２３ページ、監査委員運営費、２２１ページ、選挙管理委員会運営費について、順不同で伺います。選挙管理委員会運営費について伺います。","respondent":"今井選挙管理委員会事務局長","answer":"初めに、令和５年度のこの決算に示しているほかに、令和４年度にも事前に横断幕や選挙ポスターの選挙啓発物品などを執行いたしたところです。","id":"exchange-142"},{"speaker":"松本委員","kind":"意見","question":"経費の削減に努めていただいたというところで、とてもよいのかなと思います。この投票率について、ここは見解というか、やはり選挙の投票率が低いという認識は選挙管理委員会としてもおありかというところをお願いいたしますとの意見を述べました。","respondent":"今井選挙管理委員会事務局長","answer":"都知事選挙につきましても、前回は、東京都の平均よりは５ポイント以上高いです。区といたしましても、今まで若い世代にも出前模擬選挙などを実施してまいりましたので。","id":"exchange-143"},{"speaker":"松本委員","kind":"質問","question":"区役所での期日前投票は告示の翌日から可能だったのですけれども、地域センターのほうでは、この期日前投票は７日間だったのですか。この差が出てくることについて、法律とか条例、あるいは規則で差を設けないといけないとか、そういう規則なり何か根拠があるのかをお伺いいたします。","respondent":"今井選挙管理委員会事務局長","answer":"期日前投票につきましては、当該選挙の期日の公示または告示があった日の翌日から選挙の前日まで行わせることができるです。７日間が選挙期間ですので、地域センターは告示の翌日からになりますので、月曜日からということになっております。","id":"exchange-144"},{"speaker":"松本委員","kind":"質問・要望","question":"何日にするかというところが、必ずしも、翌日以降であれば法的な拘束はないというところで伺いました。地域センターについても、期日前投票所を公示の翌日から開いてほしいと求めましたが、いかがか尋ねました。","respondent":"今井選挙管理委員会事務局長","answer":"今回の衆議院選挙の準備に当たっても、現在も区民集会所のキャンセルなどについて、大変区民の皆様にもご迷惑をおかけしています。","id":"exchange-145"},{"speaker":"松本委員","kind":"質問","question":"時間があまりないのですが、次に、財政管理費と監査委員運営費について伺います。そちらについて伺えればと思います。","respondent":"高山監査委員事務局長","answer":"第２６表に取り上げる基準と申しますと、こちらは決算審査をするに当たりまして、ヒアリングを行っているところです。５００を超える事業の中から、このような１００万円以上に該当するものの中から３０％相違があるものをこの表のほうに掲出しているものです。","id":"exchange-146"},{"speaker":"松本委員","kind":"質問・要望","question":"今回の執行率についてどういうふうに考えていくのかというところもお伺いしたかったのですけれども、また別の機会に行わせてほしいと求めました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-147"},{"speaker":"藤原委員","kind":"質問","question":"１８３ページ、しながわ平和の花壇、２０１ページ、喫煙のことで伺いますが、まず、平和の花壇について、改めてこの目的を教えてください。西大井駅の、あの場所になぜつくったのか説明を求めました。","respondent":"勝亦総務課長","answer":"平成２７年から開始しておりまして、平成２６年に、しながわ平和の花壇を設置しています。平成元年に既に設置されていたものでございまして、こちらの周辺に西大井の平和の花壇を設置した、そういうことです。","id":"exchange-148"},{"speaker":"藤原委員","kind":"質問","question":"真正面から見ると、モニュメントがあるところはお花がきれいですけれども、その左は雑草ではないですか。その点についてどう考えられますか。","respondent":"勝亦総務課長","answer":"「平和の誓い」像があるという文脈の中で、この周辺に平和の花壇を設置したという経緯はあります。さらなる場所の拡大ですとか、花壇を広げていくというような考え方はあろうかと思いますので、いろいろ考えていきたいと思います。","id":"exchange-149"},{"speaker":"藤原委員","kind":"質問","question":"逆に、喫煙所、交番の前でよいではないですか。その辺について、両課長、どうか尋ねました。","respondent":"勝亦総務課長、河合生活安全担当課長","answer":"シルバー人材センターに管理をお願いしておりますけれども、水は駅のほうからポリタンク等で運んでいただいていると認識しております。状況等を様々関係課とも相談しながら考えていきたいと思います。 おおむね２０名であれば、喫煙者は対応できるというところで、しっかり確認はしております。煙の流出等が出たときには、歩行者の選択性がありませんので、喫煙所としては一番よい場所かなということで判断しております。","id":"exchange-150"},{"speaker":"藤原委員","kind":"質問","question":"グッズはすばらしいですから、ぜひ課に帰って、グッズの話が出たとお伝えください。次は、２２１ページ、区議会議員選挙についてお伺いしますが、国政、都政、区政とあります。","respondent":"今井選挙管理委員会事務局長","answer":"その制度の趣旨は、今、委員がおっしゃっているとおりだと考えています。その３項目以外につきましては、自治体で実施できるという規定がないために、国の見解となっております。","id":"exchange-151"},{"speaker":"藤原委員","kind":"確認","question":"「政治は、子育てや介護を担っていたり、社会で生きづらさを感じている方こそやるべきです。本人に確認をとっていないから、選挙管理委員会事務局長、どう思われますか。","respondent":"今井選挙管理委員会事務局長","answer":"先ほど申しましたとおり、全ての国民、いわゆる立候補資格のある皆さんが、公営制度を活用しながら立候補するというのは大変重要なことだと思いますので、そのためにこの公営制度があるという認識です。","id":"exchange-152"},{"speaker":"藤原委員","kind":"質問","question":"１７３ページ、ＳＤＧｓについてお伺いしますが、これ、担当課長が初めてできましたよね、この部署。どういう思いで、どういう成果を出していくか、その辺の思いをぜひ説明を求めました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"これを契機といたしまして、全庁的に各部署と連携を図りながら、ＳＤＧｓの達成に向けた各取組をさらに加速させてまいりたいと考えているところです。こちらを着実に進めてまいります。","id":"exchange-153"},{"speaker":"石田（ち）委員","kind":"質問","question":"１８６ページの人権啓発費、選択的夫婦別姓についてと、リプロダクティブ・ヘルス／ライツについて伺いたいと思います。それは品川区の数ではなくて東京都全体での数ということなのか、品川区の数は分からないのでしょうか、伺いたいと思います。","respondent":"木村人権・ジェンダー平等推進課長","answer":"今の１,３００件余という数に関しましては、東京都で公表されているものになります。数自体は定期的に確認させていただいて把握をして、それに合わせてというか、事業について検討を進めているところになります。","id":"exchange-154"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、こうした大きな変化が起こっている今も、区は選択的夫婦別姓については国の議論だと言い続けるのでしょうか、伺いたいと思います。そして、区として、ぜひ国に議論をしていただきたい、そして実現をということを求めていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"築山戸籍住民課長","answer":"選択的夫婦別姓についてです。こちらにつきましては、立法機関である国会の場で議論を十分に尽くすべきものと考えており、国の動向を注視してまいる考えです。","id":"exchange-155"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この選択的夫婦別姓を求めることは、何ら矛盾しないし、むしろ求めないことのほうが矛盾すると私は思います。このリプロについては、どのように取り組まれようとしているのか、女性の自己決定権を保障するという認識で取り組まれていくのか伺いたいと思います。","respondent":"木村人権・ジェンダー平等推進課長","answer":"７月から立ち上がった推進会議のほうでも、丁寧にご説明ですとか、そういった形で区民の方々へも理解ができるように進めてまいりたいと思います。今、皆さんが普通に使っているという言葉もありますので、そういった形で取り組んでいくようにさせていただきたいと思います。","id":"exchange-156"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"分かるようにしていただきたい。丁寧にとおっしゃったので、これがどういうものなのかということが分かるようにしていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"委員の方々と一緒に考えていくような形で、条例の基本理念について広く入れていけるように、委員の方々と一緒に考えていきたいと考えています。","id":"exchange-157"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私もその推進会議の第１回目を傍聴しましたけれども、そして、本当に十分議論していただきたいなと思いました。これの結果について、区としては、どう考えていらっしゃるか伺いたいと思います。","respondent":"木村人権・ジェンダー平等推進課長","answer":"こうした問題の重要性について、男性を含めて広く周知を、社会の認識を高めるというところを理念というように考えております。その１つ、薬のことをとるだけではなくて、子どもの頃から、女性だけではなく、皆さんに健康について考えていただく機会を持ちたいと考えています。","id":"exchange-158"},{"speaker":"大倉委員","kind":"質問・要望","question":"１９７ページ、２０１ページ、公契約条例制定についてということでお伺いできればと思っています。実感されているのかというところを教えていただきたいことと、研修とか、どのぐらいの方が受けているのか説明を求めました。","respondent":"西澤ＤＸ戦略担当課長、宮澤地域活動課長、佐藤経理課長","answer":"実施時間は９０分から１２０分で、講義とハンズオンを含めた内容になっておりまして、実際に職員が触れるような環境で研修を実施しております。… もう１つは、マンションとの連携というところで、加入していない町会との関係づくり、そういったところも支援をしております。加入だけでなく… それはこれまでの検討に加えまして、現場に近いところから具体的な意見をいただくということで条例案を検討していくことを目的にしております。","id":"exchange-159"},{"speaker":"大倉委員","kind":"質問・要望","question":"第４回定例会での条例制定を目指しとあるのですが、例えば、そういうことも考え得るのかなというところの確認をさせてほしいと求めました。ＡＩチャットボットにそのまま移りますが、令和５年度から、今まで４業務から３業務を増やして、今、７になっているのか尋ねました。","respondent":"佐藤経理課長、西澤ＤＸ戦略担当課長、宮澤地域活動課長","answer":"今回の検討委員会においても、先般の答弁のとおり、第４回定例会への提案を目指して準備してまいります。ＡＩチャットボットについてご説明します。そして、そういったキャラクターが使えるかという技術的に可能かというところも確認した上で進めていきたいと考… ＮＰＯの活動の支援というところにも入ってくるかと思います。","id":"exchange-160"},{"speaker":"大倉委員","kind":"質問","question":"第４回定例会を目指すというところであるということで、様々検討委員会の中でご意見をいただきながら進めていってほしいと求めました。時間がないので、また改めていろいろなところで質問したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-161"},{"speaker":"あくつ委員","kind":"質問・要望","question":"本年５月に、会派６名で、この目で確認をしてまいりました。それまでは車で４時間かかりますけれども、観光の観点からも、ぜひこの１０年間、これを活用してほしいと求めましたが、いかがか尋ねました。","respondent":"大森文化観光戦略課長","answer":"飯田市との観光面での連携ということで、リニア開通まで、向こう１０年間あるということで、これまでも交流を深めてきたと認識しています。","id":"exchange-162"},{"speaker":"あくつ委員","kind":"質問","question":"昭和６１年８月に水と緑の市町村との交流事業基本構想を策定し、８１市町村からのオファーがあって、この２つが選ばれた。災害協定を結んだばかりですから、根拠を見据えていってはいかがかと思いますが、ご見解を伺います。","respondent":"勝亦総務課長","answer":"こういったものの中で相互の自治体が連携を深めて、それぞれが協力し合って元気になっていく、こういったコンセプトで進めてきているものです。そういった意味では、今後とも、様々なジャンルで交流連携を通して相互に発展していけるよう努めてまいりたいと考えております。","id":"exchange-163"},{"speaker":"あくつ委員","kind":"質問","question":"次に、おくやみコーナーと、ＲＰＡ等について、書かない窓口の推進について伺ってまいります。本年の行財政改革特別委員会の中で、デジタル推進課長から、これはいつからスタートするのか説明を求めました。","respondent":"横田デジタル推進課長","answer":"現在、契約を進めているところでございまして、１月を目指して今動いているところです。","id":"exchange-164"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それともう１つ、これも意見です。これは４情報、１回それを入力すれば、こちらのほうも伺います。","respondent":"横田デジタル推進課長","answer":"委員ご指摘のとおり、パソコンに口座番号を入力することによりまして、複数の帳票に反映するような仕組みを構築する予定です。生年月日、性別を入力することによって、複数帳票に反映するような仕組みを構築する予定です。","id":"exchange-165"},{"speaker":"あくつ委員","kind":"提案","question":"３月の予算特別委員会で、これは当時の情報戦略担当課長に伺ったのですが、品川区の交通安全担当に金融機関から回ってきます。ご提案いただいた業務も、まだ我々のほうには要望は上がってきておりませんが、区民の利便性向上と業務の効率が図れる可能性がありますのでとの意見を述べました。","respondent":"西澤ＤＸ戦略担当課長","answer":"本件に関して、令和６年３月から４月にかけて、地域交通政策課とデジタル推進課で検討を行いました。本件では断念せざるを得ませんでしたが、別の方法で効率化を視野にフィージビリティを見極めながら、引き続き検討していきたいと考えています。","id":"exchange-166"},{"speaker":"あくつ委員","kind":"質問・要望","question":"保険会社のほうにも確認をして、準公金扱いということで、用紙には一定の制限があるということでございました。最後に、外国人観光客誘致事業、インバウンド向け整備・ＰＲ事業、これは時間もないですから簡単に申し上げます。","respondent":"大森文化観光戦略課長","answer":"インバウンドに向けての観光客の取り込みということで、こちらは、引き続き進めてまいりたいと思います。しながわ観光協会ホームページのほうに載っておりますので、ぜひ皆さん、ご覧ください。","id":"exchange-167"},{"speaker":"まつざわ委員","kind":"質問","question":"私からは、２０１ページ、生活安全推進事業、これは防犯と防犯カメラについて、時間があれば、１９５ページの地域振興経費について質問します。ここ最近の認知件数の推移について説明を求めました。","respondent":"河合生活安全担当課長","answer":"令和４年以降、行動制限が解除されてから若干その反動といいますか、増加に転じております。２年連続微増という形になっているのですけれども、微減という形になっておりますので、治安が著しく悪化しているという状況ではございません。","id":"exchange-168"},{"speaker":"まつざわ委員","kind":"確認","question":"確認しました。この自動通話録音機の貸出し数は、区内にある程度広がったから減ってきたのか、この減少した数の確認をさせてください。","respondent":"河合生活安全担当課長","answer":"警察もご案内していただくようなことがありまして、そのアポ電が減少したこともありますので、そういったところで減少したところもあります。","id":"exchange-169"},{"speaker":"まつざわ委員","kind":"確認","question":"犯罪抑止の効果的なものの１つとして、防犯カメラが有効な手段として広く認知され、設置が品川区でも進んでいます。足りているのか、足りていないのか、そこら辺を確認させてください。","respondent":"河合生活安全担当課長","answer":"商店街等の地域団体に設置していただくものに助成するという設置費、手集計で、おおむね１,３６８台の設置を把握しているのですけれども。","id":"exchange-170"},{"speaker":"まつざわ委員","kind":"質問","question":"この維持管理費は、要は、固定費です。事件が発生した際に、この防犯カメラを活用するのは誰なのか、説明を求めました。","respondent":"河合生活安全担当課長","answer":"事件が発生した際には、やはり警察などの捜査機関が活用するという形になります。","id":"exchange-171"},{"speaker":"まつざわ委員","kind":"提案","question":"７年間にわたって同じような要望を出していますが、町会・自治会は、あくまでも犯罪抑止に協力している形です。そこら辺は検討してほしいと求めましたが、２点、ご見解を説明を求めました。","respondent":"河合生活安全担当課長","answer":"町会などの財政負担は、やはり考えていかなければいけないですので、助成率等については検討していく必要があるかなというところで判断しております。","id":"exchange-172"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"これは大変好評だと伺っております。そこに対して重点的に助成金を拡充していく、そういったお考えがあるかどうか、ご見解を説明を求めました。","respondent":"河合生活安全担当課長","answer":"まず、本年度から、個人宅の戸建て住宅の防犯カメラと録画機能付きインターホンの設置に関する助成を開始しております。ですので、その時々の治安情勢と区民のニーズを確認しながら、その時々に追加するかどうかということは検討かなというところで考えております。","id":"exchange-173"},{"speaker":"まつざわ委員","kind":"提案","question":"これは前にも質問したのですけれども、そういった声がある中、見守りを可視化するということはどうかなということを提案させていただきたいのです。そういうところがあったりするので、そういった部分でしなみちレポートのような可視化、そういった考え方を説明を求めました。","respondent":"河合生活安全担当課長","answer":"不審者情報とか、そういったものは素早く発信されますので、デジポリスの普及促進としてやっているところです。委員ご指摘のとおり、やはり見守りというのは、ながら見守りが大切ですので、そういったアプリの活用なども検討していきたいと考えております。","id":"exchange-174"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/285407?Template=document&Id=6851#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":116435,"voices":390}}]);
